```csharp
public static int LongestIncreasingSubsequence(int[] arr)
{
    int n = arr.Length;
    int[] top = new int[n];
    int piles = 0;

    for (int i = 0; i < n; i++)
    {
        // Binary search to find the correct pile to place the current element
        int left = 0;
        int right = piles;

        while (left < right)
        {
            int mid = left + (right - left) / 2;
            if (arr[i] > arr[top[mid]])
            {
                left = mid + 1;
            }
            else
            {
                right = mid;
            }
        }

        // Place the current element in the correct pile
        if (left == piles)
        {
            piles++;
        }
        top[left] = i;
    }

    return piles;
}
```

