using System;

public class InvalidInterestRateException : Exception
{
    public InvalidInterestRateException(string message) : base(message)
    {
    }
}

public class InvalidNumberOfYearsException : Exception
{
    public InvalidNumberOfYearsException(string message) : base(message)
    {
    }
}

public class IncompleteDataException : Exception
{
    public IncompleteDataException(string message) : base(message)
    {
    }
}

public class CompoundInterestCalculator
{
    private double principalAmount;
    private double interestRate;
    private int numberOfYears;

    public CompoundInterestCalculator(double principalAmount, double interestRate, int numberOfYears)
    {
        if (principalAmount <= 0)
        {
            throw new ArgumentException("Principal amount must be positive");
        }

        PrincipalAmount = principalAmount;
        InterestRate = interestRate;
        NumberOfYears = numberOfYears;
    }

    public double PrincipalAmount
    {
        get { return principalAmount; }
        set
        {
            if (value <= 0)
            {
                throw new ArgumentException("Principal amount must be positive");
            }
            principalAmount = value;
        }
    }

    public double InterestRate
    {
        get { return interestRate; }
        set
        {
            if (value < 0 || value > 0.1)
            {
                throw new InvalidInterestRateException("Interest rate must be between 0 and 10%");
            }
            interestRate = value;
        }
    }

    public int NumberOfYears
    {
        get { return numberOfYears; }
        set
        {
            if (value <= 0)
            {
                throw new InvalidNumberOfYearsException("Number of years must be a positive integer");
            }
            numberOfYears = value;
        }
    }

    public double CalculateInterest()
    {
        double compoundInterest = PrincipalAmount * Math.Pow(1 + InterestRate, NumberOfYears) - PrincipalAmount;
        return compoundInterest;
    }

    public double CalculateTotalAmount()
    {
        double totalAmount = PrincipalAmount + CalculateInterest();
        return totalAmount;
    }

    public double CalculateMonthlyPayment()
    {
        if (PrincipalAmount <= 0 || InterestRate <= 0 || NumberOfYears <= 0)
        {
            throw new IncompleteDataException("Principal amount, interest rate, and number of years must be set");
        }

        double monthlyPayment = CalculateTotalAmount() / (NumberOfYears * 12);
        return monthlyPayment;
    }
}
