    static void CustomSort(int[] arr)
    {
        int n = arr.Length;

        for (int i = 0; i < n - 1; i++)
        {
            for (int j = 0; j < n - i - 1; j++)
            {
                if (ShouldSwap(arr[j], arr[j + 1]))
                {
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }
    }

    static bool ShouldSwap(int a, int b)
    {
        if (a % 2 == 0 && b % 2 == 0)
        {
            if (a % 3 == 0 && b % 3 != 0)
            {
                return a > b;
            }
            else if (a % 3 != 0 && b % 3 == 0)
            {
                return a < b;
            }
        }
        else if (a % 2 != 0 && b % 2 != 0)
        {
            if (a % 5 == 0 && b % 5 != 0)
            {
                return a > b;
            }
            else if (a % 5 != 0 && b % 5 == 0)
            {
                return a < b;
            }
        }

        return false; // No swapping needed
    }
}
