```csharp
using System;

class Program
{
    static int QuaternarySearch(int[] arr, int element, int low, int high)
    {
        if (low <= high)
        {
            int mid1 = low + (high - low) / 4;
            int mid2 = low + (high - low) / 2;
            int mid3 = low + (3 * (high - low)) / 4;

            if (arr[mid1] == element)
                return mid1;
            if (arr[mid2] == element)
                return mid2;
            if (arr[mid3] == element)
                return mid3;

            if (element < arr[mid1])
                return QuaternarySearch(arr, element, low, mid1 - 1);
            if (element < arr[mid2])
                return QuaternarySearch(arr, element, mid1 + 1, mid2 - 1);
            if (element < arr[mid3])
                return QuaternarySearch(arr, element, mid2 + 1, mid3 - 1);

            return QuaternarySearch(arr, element, mid3 + 1, high);
        }

        return -1;
    }

    static void Main(string[] args)
    {
        int[] arr = { 2, 3, 4, 10, 14, 20, 26, 30, 40 };
        int element = 10;
        int index = QuaternarySearch(arr, element, 0, arr.Length - 1);

        if (index != -1)
            Console.WriteLine("Element found at index: " + index);
        else
            Console.WriteLine("Element not found");
    }
}
