namespace PrimeNumberChecker
{
    class Program
    {
        static void Main(string[] args)
        {
            // Test cases
            Console.WriteLine(IsPrime(2));   // true
            Console.WriteLine(IsPrime(7));   // true
            Console.WriteLine(IsPrime(10));  // false
            Console.WriteLine(IsPrime(-13)); // true
            Console.WriteLine(IsPrime(1.5)); // false
            Console.WriteLine(FindClosestPrime(13));   // 13
            Console.WriteLine(FindClosestPrime(17));   // 17
            Console.WriteLine(FindClosestPrime(23));   // 23
            Console.WriteLine(FindClosestPrime(25));   // 23
        }

        // Check if a given number is prime
        public static bool IsPrime(dynamic number)
        {
            // Negative numbers, decimal numbers and numbers less than 2 are not prime
            if (number <= 1 || number % 1 != 0)
                return false;

            // Handle small numbers
            if (number == 2 || number == 3)
                return true;

            // Handle even numbers
            if (number % 2 == 0)
                return false;

            // Create a new instance of ManualResetEvent
            ManualResetEvent[] doneEvents = new ManualResetEvent[10];
            PrimeChecker[] primeCheckers = new PrimeChecker[10];

            // Start multiple threads to check primality in parallel
            for (int i = 0; i < 10; i++)
            {
                doneEvents[i] = new ManualResetEvent(false);
                primeCheckers[i] = new PrimeChecker(number, i, doneEvents[i]);
                ThreadPool.QueueUserWorkItem(primeCheckers[i].CheckPrime, i);
            }

            // Wait for all threads to finish
            WaitHandle.WaitAll(doneEvents);

            // Check the result of each thread
            foreach (PrimeChecker primeChecker in primeCheckers)
            {
                if (primeChecker.IsPrime)
                    return true;
            }

            return false;
        }

        // Find the closest prime number for a given number
        public static long FindClosestPrime(long number)
        {
            if (IsPrime(number))
                return number;

            // Find the next prime number greater than the given number
            long nextPrime = number;
            while (!IsPrime(++nextPrime)) { }

            // Find the previous prime number smaller than the given number
            long prevPrime = number;
            while (!IsPrime(--prevPrime)) { }

            // Find the closest prime number by comparing the distances
            if (number - prevPrime < nextPrime - number)
                return prevPrime;
            else
                return nextPrime;
        }
    }

    // Thread class for checking primality
    public class PrimeChecker
    {
        private dynamic number;
        private int threadIndex;
        private ManualResetEvent doneEvent;
        private bool isPrime;

        public bool IsPrime { get { return isPrime; } }

        public PrimeChecker(dynamic number, int threadIndex, ManualResetEvent doneEvent)
        {
            this.number = number;
            this.threadIndex = threadIndex;
            this.doneEvent = doneEvent;
            this.isPrime = false;
        }

        // Check if a given number is prime
        public void CheckPrime(object threadContext)
        {
            int index = (int)threadContext;
            double sqrt = Math.Sqrt((double)number);

            // Start checking from different positions based on thread index
            for (int i = 2 + index; i <= sqrt; i += 10)
            {
                if (number % i == 0)
                {
                    isPrime = false;
                    doneEvent.Set();
                    return;
                }
            }

            isPrime = true;
            doneEvent.Set();
        }
    }
