public class AnagramChecker
{
    public static bool CheckAnagram(string string1, string string2)
    {
        // Remove leading and trailing spaces
        string1 = string1.Trim();
        string2 = string2.Trim();

        // Check if the strings have invalid characters or uppercase letters
        if (!IsValidString(string1) || !IsValidString(string2))
        {
            return false;
        }

        // Convert the strings to lowercase
        string1 = string1.ToLower();
        string2 = string2.ToLower();

        // Create dictionaries to store the frequency of each letter in the strings
        Dictionary<char, int> frequency1 = new Dictionary<char, int>();
        Dictionary<char, int> frequency2 = new Dictionary<char, int>();

        // Count the frequency of each letter in string1
        foreach (char c in string1)
        {
            if (frequency1.ContainsKey(c))
            {
                frequency1[c]++;
            }
            else
            {
                frequency1[c] = 1;
            }
        }

        // Count the frequency of each letter in string2
        foreach (char c in string2)
        {
            if (frequency2.ContainsKey(c))
            {
                frequency2[c]++;
            }
            else
            {
                frequency2[c] = 1;
            }
        }

        // Check if the frequencies of all letters are the same in both strings
        if (frequency1.Count != frequency2.Count)
        {
            return false;
        }

        foreach (char c in frequency1.Keys)
        {
            if (!frequency2.ContainsKey(c) || frequency1[c] != frequency2[c])
            {
                return false;
            }
        }

        return true;
    }

