using System.Linq;

public class SuccessRateTracker
{
    private List<PingDataPoint> dataPoints;

    public SuccessRateTracker()
    {
        dataPoints = new List<PingDataPoint>();
    }

    public void AddDataPoint(PingDataPoint dataPoint)
    {
        dataPoints.Add(dataPoint);
    }

    public double CalculateSuccessRate(DateTime startTime, DateTime endTime)
    {
        var dataPointsWithinWindow = dataPoints.Where(p => p.Timestamp >= startTime && p.Timestamp <= endTime).ToList();
        if (dataPointsWithinWindow.Count == 0)
        {
            return 0.0; // No data points within the specified time window
        }

        var successfulDataPoints = dataPointsWithinWindow.Count(p => p.Success);
        return (double)successfulDataPoints / dataPointsWithinWindow.Count * 100;
    }
}
