    private BlockType[,] grid;
    private bool vertical;

    public Board(int rows, int columns, bool vertical)
    {
        grid = new BlockType[rows, columns];
        this.vertical = vertical;
    }

    public void PlaceBlock(int column, BlockType block)
    {
        if (column < 0 || column >= grid.GetLength(1))
        {
            throw new ArgumentOutOfRangeException(nameof(column), "Invalid column index");
        }

        for (int row = grid.GetLength(0) - 1; row >= 0; row--)
        {
            if (grid[row, column] == BlockType.None)
            {
                grid[row, column] = block;
                break;
            }
        }
    }

    public bool CheckForWin()
    {
        int consecutiveCount = 0;

        for (int col = 0; col < grid.GetLength(1); col++)
        {
            for (int row = 0; row < grid.GetLength(0); row++)
            {
                if (grid[row, col] != BlockType.None)
                {
                    consecutiveCount++;
                    if (consecutiveCount == 4)
                    {
                        return true;
                    }
                }
                else
                {
                    consecutiveCount = 0;
                }
            }
            consecutiveCount = 0;
        }

        return false;
    }

    public void ResetBoard()
    {
        for (int row = 0; row < grid.GetLength(0); row++)
        {
            for (int col = 0; col < grid.GetLength(1); col++)
            {
                grid[row, col] = BlockType.None;
            }
        }
    }

    public bool Vertical
    {
        get { return vertical; }
        set { vertical = value; }
    }
}
