using System;
using System.Collections.Generic;

public class PriorityQueue
{
    private SortedDictionary<int, Queue<Seeker>> queueMap;

    public PriorityQueue()
    {
        queueMap = new SortedDictionary<int, Queue<Seeker>>();
    }

    public void Enqueue(int order, Seeker seeker)
    {
        if (!queueMap.ContainsKey(order))
        {
            queueMap[order] = new Queue<Seeker>();
        }
        queueMap[order].Enqueue(seeker);
    }

    public Seeker Dequeue()
    {
        if (queueMap.Count == 0)
        {
            throw new InvalidOperationException("Priority queue is empty");
        }

        var highestPriority = queueMap.First().Key;
        var element = queueMap[highestPriority].Dequeue();
        if (queueMap[highestPriority].Count == 0)
        {
            queueMap.Remove(highestPriority);
        }
        return element;
    }

    public int Count
    {
        get
        {
            int count = 0;
            foreach (var queue in queueMap.Values)
            {
                count += queue.Count;
            }
            return count;
        }
    }
}
```

This implementation uses a `SortedDictionary` to map priorities to queues of elements. When enqueuing, it checks if a queue for the given priority exists, and if not, creates one. When dequeuing, it retrieves the element from the queue with the highest priority and removes the queue if it becomes empty. The `Count` property iterates through all queues to calculate the total count of elements in the priority queue.

