using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;

public class DIContainer
{
    private readonly Dictionary<Type, Type> _typeMap = new Dictionary<Type, Type>();

    public void Register<TInterface, TImplementation>()
    {
        _typeMap[typeof(TInterface)] = typeof(TImplementation);
    }

    public TInterface Resolve<TInterface>()
    {
        Type implementationType = _typeMap[typeof(TInterface)];
        ConstructorInfo constructor = implementationType.GetConstructors().First();
        ParameterInfo[] parameters = constructor.GetParameters();
        object[] resolvedParameters = parameters.Select(p => Resolve(p.ParameterType)).ToArray();
        return (TInterface)Activator.CreateInstance(implementationType, resolvedParameters);
    }

    public TInterface ResolvePropertyInjection<TInterface>()
    {
        Type implementationType = _typeMap[typeof(TInterface)];
        TInterface instance = (TInterface)Activator.CreateInstance(implementationType);
        PropertyInfo[] properties = implementationType.GetProperties()
            .Where(p => p.GetCustomAttribute<DependencyAttribute>() != null).ToArray();
        foreach (PropertyInfo property in properties)
        {
            Type propertyType = property.PropertyType;
            object resolvedProperty = Resolve(propertyType);
            property.SetValue(instance, resolvedProperty);
        }
        return instance;
    }
}

