using System;

public class NewtonRaphson
{
    public delegate double Function(double x);
    public delegate double Derivative(double x);

    public static double? NewtonRaphsonMethod(Function func, Derivative derivative, double initialGuess, double tolerance, int maxIterations)
    {
        double x = initialGuess;
        int iteration = 0;

        while (iteration < maxIterations)
        {
            double fx = func(x);
            double fpx = derivative(x);

            if (Math.Abs(fpx) < 1e-12)  // Check for division by zero
            {
                return null;
            }

            double nextX = x - fx / fpx;

            if (Math.Abs(nextX - x) < tolerance)  // Check for convergence
            {
                return nextX;
            }

            x = nextX;
            iteration++;
        }

        return null;  // Return null if maxIterations is reached without convergence
    }
}
```

