using System;
using System.Collections.Generic;

public class BadHealthEntry
{
    public DateTime Timestamp { get; set; }
    public string Message { get; set; }
}

public class CircularHealthBuffer
{
    private List<BadHealthEntry> _entries;
    private int _currentIndex;

    public CircularHealthBuffer()
    {
        _entries = new List<BadHealthEntry>();
        _currentIndex = 0;
    }

    public void Insert(BadHealthEntry entry)
    {
        if (_entries.Count < 50)
        {
            _entries.Add(entry);
        }
        else
        {
            _entries[_currentIndex] = entry;
            _currentIndex = (_currentIndex + 1) % 50;
        }
    }

    public List<BadHealthEntry> GetEntries()
    {
        return _entries;
    }
}
```

In the solution, the `CircularHealthBuffer` class maintains a list of `BadHealthEntry` objects and an index to keep track of the current position in the circular buffer. The `Insert` method adds a new entry to the buffer, replacing the oldest entry when the buffer is full. The `GetEntries` method returns all the entries in the buffer.

