    private byte[] bytes;

    public static Identifier FromBytes(byte[] bytes, int offset, int length, bool littleEndian)
    {
        byte[] identifierBytes = new byte[length];
        Array.Copy(bytes, offset, identifierBytes, 0, length);
        if (littleEndian && BitConverter.IsLittleEndian)
        {
            Array.Reverse(identifierBytes);
        }
        return new Identifier { bytes = identifierBytes };
    }

    public byte[] ToByteArrayOfSpecifiedEndianness(bool littleEndian)
    {
        byte[] result = (byte[])bytes.Clone();
        if (littleEndian && BitConverter.IsLittleEndian)
        {
            Array.Reverse(result);
        }
        return result;
    }

    public string ToString()
    {
        return BitConverter.ToString(bytes).Replace("-", "").ToLower();
    }
}
