    private List<DOMSheet> sheets;
    private bool disposed = false;

    public CustomSheetCollection()
    {
        sheets = new List<DOMSheet>();
    }

    public void AddSheet(DOMSheet sheet)
    {
        if (disposed)
        {
            throw new ObjectDisposedException("CustomSheetCollection");
        }
        sheets.Add(sheet);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!disposed)
        {
            if (disposing)
            {
                if (sheets != null)
                {
                    foreach (var sheet in sheets)
                    {
                        sheet.Dispose();
                    }
                    sheets.Clear();
                    sheets = null;
                }
            }
            disposed = true;
        }
    }

    public IEnumerator GetEnumerator()
    {
        if (disposed)
        {
            throw new ObjectDisposedException("CustomSheetCollection");
        }
        return sheets.GetEnumerator();
    }
}
