public class MapSet<TKey, TValue>
{
    private Dictionary<TKey, ISet<TValue>> map;

    // Constructor and other methods are assumed to be implemented

    public bool MapEquals(MapSet<TKey, TValue> other)
    {
        // Check if the other instance is null or of a different type
        if (other == null || this.GetType() != other.GetType())
        {
            return false;
        }

        // Check if the number of key-value mappings is the same
        if (this.map.Count != other.map.Count)
        {
            return false;
        }

        // Check if each key in the current instance exists in the other instance
        foreach (var kvp in this.map)
        {
            if (!other.map.TryGetValue(kvp.Key, out var otherValues))
            {
                return false;
            }

            // Check if the set of values for the current key is equal to the set of values for the same key in the other instance
            if (!kvp.Value.SetEquals(otherValues))
            {
                return false;
            }
        }

        return true; // All key-value mappings are equal
    }
