```csharp
using System;
using System.Collections.Concurrent;
using System.Reflection;

namespace HoleOverHttp.WsProvider
{
    public class ReflectCallProvider : CallProvider
    {
        private readonly ConcurrentDictionary<string, Tuple<MethodInfo, object>> _methods =
            new ConcurrentDictionary<string, Tuple<MethodInfo, object>>();

        public override void RegisterService(object service)
        {
            if (service == null)
            {
                throw new ArgumentNullException(nameof(service));
            }

            var serviceType = service.GetType();
            var methods = serviceType.GetMethods(BindingFlags.Public | BindingFlags.Instance);

            foreach (var method in methods)
            {
                _methods.TryAdd(method.Name, Tuple.Create(method, service));
            }
        }

        public object InvokeMethod(string methodName, object[] parameters)
        {
            if (string.IsNullOrEmpty(methodName))
            {
                throw new ArgumentNullException(nameof(methodName));
            }

            if (!_methods.TryGetValue(methodName, out var methodInfo))
            {
                return $"Method '{methodName}' not found.";
            }

            try
            {
                var result = methodInfo.Item1.Invoke(methodInfo.Item2, parameters);
                return result;
            }
            catch (Exception ex)
            {
                return $"Error invoking method '{methodName}': {ex.Message}";
            }
        }
    }
}
```

