public static string ConvertToChinese(decimal number)
{
    string[] chineseDigits = { "零", "一", "二", "三", "四", "五", "六", "七", "八", "九" };
    string[] chineseUnits = { "", "十", "百", "千", "万", "十", "百", "千", "亿", "十", "百", "千" };

    string numberString = number.ToString();
    string chineseRepresentation = "";

    for (int i = 0; i < numberString.Length; i++)
    {
        int digit = int.Parse(numberString[i].ToString());
        int unitIndex = numberString.Length - i - 1;

        if (digit != 0)
        {
            chineseRepresentation += chineseDigits[digit] + chineseUnits[unitIndex];
        }
        else
        {
            if (unitIndex % 4 == 0) // Add "亿", "万" for appropriate positions
            {
                chineseRepresentation += chineseUnits[unitIndex];
            }
            else if (chineseRepresentation[chineseRepresentation.Length - 1] != "零") // Avoid consecutive "零"
            {
                chineseRepresentation += chineseDigits[digit];
            }
        }
    }

    // Remove leading and trailing "零"
    chineseRepresentation = chineseRepresentation.Trim('零');

    return chineseRepresentation;
}
```

