            while ((line = file.ReadLine()) != null)
            {
                var result = Regex.Split(line, @"(-|:|\s)", RegexOptions.IgnoreCase);
                var minCount = int.Parse(result[0]);
                var maxCount = int.Parse(result[2]);
                var character = result[4][0];
                var password = result[7];

