                    if (c == character)
                    {
                        count++;
                    }
                }

                if (count >= minCount && count <= maxCount)
                {
                    validPasswords++;
                }
            }
            file.Close();
            Console.WriteLine("Number of valid passwords: " + validPasswords);
        }
    }
}
