    public void DownloadFile(string remoteFilePath, string localDestinationPath)
    {
        try
        {
            // Establish a connection with the remote server
            var request = (HttpWebRequest)WebRequest.Create(remoteFilePath);
            var response = (HttpWebResponse)request.GetResponse();

            if (response.StatusCode == HttpStatusCode.OK)
            {
                // Read the file data from the response stream
                using (var stream = response.GetResponseStream())
                {
                    using (var fileStream = File.Create(localDestinationPath))
                    {
                        // Save the file data to the local destination path
                        stream.CopyTo(fileStream);
                    }
                }

                Console.WriteLine($"File '{remoteFilePath}' downloaded successfully to '{localDestinationPath}'");
            }
            else
            {
                Console.WriteLine($"Failed to download file '{remoteFilePath}'. Server returned status code: {response.StatusCode}");
            }
        }
        catch (WebException ex)
        {
            if (ex.Status == WebExceptionStatus.ProtocolError)
            {
                var response = (HttpWebResponse)ex.Response;
                Console.WriteLine($"Error: {response.StatusCode} - {response.StatusDescription}");
            }
            else
            {
                Console.WriteLine($"Error: {ex.Message}");
            }
        }
    }
}
