using OpenQA.Selenium;

public class NodeTextExtractor
{
    public static string GetNodeText(IWebElement node)
    {
        if (node.Matches("input[type=submit], input[type=button]"))
        {
            return node.GetProperty("value");
        }

        // Start with the node text, which includes all child nodes.
        // Remove each child node's text from this node to result in the text representative of this node alone.
        string nodeText = node.Text;
        foreach (var childNode in node.FindElements(By.XPath("./*")))
        {
            nodeText = nodeText.Replace(childNode.Text, "");
        }
        return nodeText.Trim();
    }
}
```

The `GetNodeText` function first checks if the node is an input element of type "submit" or "button" using the `Matches` method. If it matches, it retrieves the value of the input using `GetProperty`. If not, it retrieves the text content of the node and then iterates through its child nodes to remove their text content from the overall node text, resulting in the text representative of the node alone. Finally, it trims and returns the resulting text content.

