public class ShellCommandCallback
{
    private ManualResetEvent _commandCompleteEvent;

    public ShellCommandCallback(ManualResetEvent commandCompleteEvent)
    {
        _commandCompleteEvent = commandCompleteEvent;
    }

    public void ProcessCommand(Action commandAction)
    {
        if (Interlocked.Exchange(ref _commandCompleteEvent, null) != null)
        {
            throw new InvalidOperationException("Already a command processing");
        }

        try
        {
            commandAction.Invoke(); // Execute the command action
        }
        finally
        {
            _commandCompleteEvent.Set(); // Signal command processing completion
        }
    }
}
