```csharp
public class UserInterfaceTheme
{
    public virtual string HeaderColor { get; set; } = "hsla(0,0%,0%,0.87)";
    public virtual string BodyColor { get; set; } = "hsla(0,0%,0%,0.78)";
    public virtual string BodyWeight { get; set; } = "300";
    public virtual List<string> HeaderFontFamily { get; set; } = new List<string>
    {
        "Helvetica Neue",
        // Additional font families may be added here
    };

