    {
        // Validate header and body colors
        bool isHeaderColorValid = System.Text.RegularExpressions.Regex.IsMatch(HeaderColor, @"^hsla\(\d+,\d+%,\d+%,\d+(\.\d+)?\)$");
        bool isBodyColorValid = System.Text.RegularExpressions.Regex.IsMatch(BodyColor, @"^hsla\(\d+,\d+%,\d+%,\d+(\.\d+)?\)$");

        // Validate body weight
        bool isBodyWeightValid = int.TryParse(BodyWeight, out _);

        // Validate header font family
        bool isHeaderFontFamilyValid = HeaderFontFamily.Count > 0;

        return isHeaderColorValid && isBodyColorValid && isBodyWeightValid && isHeaderFontFamilyValid;
    }
}
