        {
            var sourceValue = source.GetType().GetProperty(sourceProperty).GetValue(source, null);
            target.GetType().GetProperty(targetProperty).SetValue(target, sourceValue, null);
        }
    }

    public void UpdateSource(string targetProperty)
    {
        var sourceProperty = bindings.FirstOrDefault(x => x.Value == targetProperty).Key;
        if (sourceProperty != null)
        {
            var targetValue = target.GetType().GetProperty(targetProperty).GetValue(target, null);
            source.GetType().GetProperty(sourceProperty).SetValue(source, targetValue, null);
        }
    }
}
