using System;
using System.Linq;

public class DataProcessor
{
    public virtual string ProcessData(string[] dataArray)
    {
        if (dataArray.Length == 0)
        {
            throw new ArgumentException("Input array cannot be empty.");
        }

        if (dataArray.All(s => int.TryParse(s, out _)))
        {
            int sum = dataArray.Select(int.Parse).Sum();
            return sum.ToString();
        }
        else
        {
            var distinctSortedArray = dataArray.Distinct().OrderBy(s => s).ToArray();
            if (distinctSortedArray.Length < dataArray.Length)
