    public static List<Vector3> GenerateVertices(List<Vector3> polyVertices, int[] polyIndices, int startIndex)
    {
        List<Vector3> vertices = new List<Vector3>();

        if (polyIndices.Length < 3)
            return vertices; // Return empty list if the number of indices is less than 3

        for (int i = 0; i < polyIndices.Length; i++)
        {
            vertices.Add(polyVertices[polyIndices[i]]);
        }

        // Shift the vertices based on the startIndex
        List<Vector3> shiftedVertices = new List<Vector3>();
        for (int i = 0; i < vertices.Count; i++)
        {
            int index = (startIndex + i) % vertices.Count;
            shiftedVertices.Add(vertices[index]);
        }

        return shiftedVertices;
    }

