```csharp
using System;
using System.IO;
using System.IO.Compression;
using System.Threading.Tasks;

public class CompressionUtility
{
    public MemoryStream Compress(Stream dataToCompress, bool leaveStreamOpen = false)
    {
        MemoryStream compressedStream = new MemoryStream();
        using (DeflateStream deflateStream = new DeflateStream(compressedStream, CompressionMode.Compress, leaveStreamOpen))
        {
            dataToCompress.CopyTo(deflateStream);
        }
        return compressedStream;
    }

    public async ValueTask<ArraySegment<byte>> CompressAsync(ReadOnlyMemory<byte> dataToCompress)
    {
        using (MemoryStream compressedStream = new MemoryStream())
        {
            using (DeflateStream deflateStream = new DeflateStream(compressedStream, CompressionMode.Compress, true))
            {
                await deflateStream.WriteAsync(dataToCompress);
            }
            return new ArraySegment<byte>(compressedStream.ToArray());
        }
    }

    public async ValueTask<MemoryStream> CompressAsync(Stream dataToCompress, bool leaveStreamOpen = false)
    {
        MemoryStream compressedStream = new MemoryStream();
        using (DeflateStream deflateStream = new DeflateStream(compressedStream, CompressionMode.Compress, leaveStreamOpen))
        {
            await dataToCompress.CopyToAsync(deflateStream);
        }
        return compressedStream;
    }
}
```

