using System;
using System.Collections.Generic;

public class UniqueStack
{
    private Stack<int> stack;
    private HashSet<int> uniqueSet;

    public UniqueStack()
    {
        stack = new Stack<int>();
        uniqueSet = new HashSet<int>();
    }

    public void Push(int value)
    {
        if (!uniqueSet.Contains(value))
        {
            stack.Push(value);
            uniqueSet.Add(value);
        }
    }

    public int Pop()
    {
        if (stack.Count == 0)
        {
            return -1;
        }
        int top = stack.Pop();
        uniqueSet.Remove(top);
        return top;
    }

    public int Peek()
    {
        if (stack.Count == 0)
        {
            return -1;
        }
        return stack.Peek();
    }

    public int GetMin()
    {
        if (stack.Count == 0)
        {
            return -1;
        }
        return uniqueSet.Min();
    }
}
