```csharp
// AcceptorHandler.cs
public class AcceptorHandler : IoHandlerAdapter
{
    public override void SessionOpened(IoSession session)
    {
        Console.WriteLine("New connection opened: " + session.RemoteEndPoint);
    }

    public override void MessageReceived(IoSession session, object message)
    {
        // Custom protocol message processing logic
        var receivedData = (byte[])message;
        // Process the received data according to the custom protocol
    }

    public override void SessionClosed(IoSession session)
    {
        Console.WriteLine("Connection closed: " + session.RemoteEndPoint);
    }
}

