class Program
{
    private static IoAcceptor acceptor;

    static void Main(string[] args)
    {
        var port = Int32.Parse(ConfigurationManager.AppSettings["ListenPort"]);
        var host = new IPEndPoint(IPAddress.Any, port);

        acceptor = new AsyncSocketAcceptor();
        acceptor.FilterChain.AddFirst("codec", new ProtocolCodecFilter(new DirectCodecFactory()));
        acceptor.Handler = SingleInstanceHelper<AcceptorHandler>.Instance;

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("按S键启动监听;");
        Console.WriteLine("按T键停止监听;");
        Console.WriteLine("按ESC键退出;");
        Console.ForegroundColor = ConsoleColor.Gray;

        ConsoleKeyInfo keyInfo;
        do
        {
            keyInfo = Console.ReadKey(true);
            switch (keyInfo.Key)
            {
                case ConsoleKey.S:
                    StartServer(host);
                    break;
                case ConsoleKey.T:
                    StopServer();
                    break;
            }
        } while (keyInfo.Key != ConsoleKey.Escape);
    }

    private static void StartServer(IPEndPoint host)
    {
        if (acceptor.Active)
        {
            Console.WriteLine("Server is already running.");
        }
        else
        {
            acceptor.Bind(host);
            Console.WriteLine("Server started and listening on port " + host.Port);
        }
    }

    private static void StopServer()
    {
        if (acceptor.Active)
        {
            acceptor.Unbind();
            Console.WriteLine("Server stopped.");
        }
        else
        {
            Console.WriteLine("Server is not running.");
        }
    }
}
