public string CustomEncode(string input)
{
    string _alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    int compensation = input.Length % 5 == 0 ? 0 : 5 - (input.Length % 5);
    byte[] bytes = System.Text.Encoding.ASCII.GetBytes(input);
    StringBuilder binaryString = new StringBuilder();

    for (int bitIndex = 0; bitIndex < input.Length * 5 - compensation; bitIndex += 8)
    {
        int dualbyte = bitIndex / 5 < input.Length ? _alphabet.IndexOf(bytes[bitIndex / 5]) << 10 : 0;
        dualbyte |= bitIndex / 5 + 1 < input.Length ? _alphabet.IndexOf(bytes[bitIndex / 5 + 1]) << 4 : 0;
        dualbyte |= bitIndex / 5 + 2 < input.Length ? _alphabet.IndexOf(bytes[bitIndex / 5 + 2]) >> 2 : 0;

        binaryString.Append(Convert.ToString(dualbyte, 2).PadLeft(8, '0'));
    }

    return binaryString.ToString();
}
```

The `CustomEncode` function first calculates the compensation value based on the length of the input string. It then converts the input string into a byte array using ASCII encoding. The function iterates through the input string, performing bitwise operations to generate the binary representation based on the custom encoding scheme. Finally, it returns the resulting binary string.

