public int Evaluate()
{
    if (Initializer == null) {
        throw new InvalidOperationException("Initializer expression is not provided");
    }
    return EvaluateExpression(Initializer);
}

private int EvaluateExpression(IExpression expression)
{
    if (expression is BinaryExpression binaryExpression)
    {
        int leftValue = EvaluateExpression(binaryExpression.Left);
        int rightValue = EvaluateExpression(binaryExpression.Right);
        switch (binaryExpression.Operator)
        {
            case Operator.Addition:
                return leftValue + rightValue;
            case Operator.Subtraction:
                return leftValue - rightValue;
            case Operator.Multiplication:
                return leftValue * rightValue;
            case Operator.Division:
                if (rightValue == 0) {
                    throw new DivideByZeroException("Division by zero is not allowed");
                }
                return leftValue / rightValue;
            default:
                throw new InvalidOperationException("Invalid operator");
        }
    }
    else if (expression is ConstantExpression constantExpression)
    {
        return constantExpression.Value;
    }
    else
    {
        throw new InvalidOperationException("Invalid expression type");
    }
}
