using System.Collections.Generic;

public class Cache<TItem>
{
    private readonly int capacity;
    private readonly Dictionary<string, LinkedListNode<(string, TItem)>> cacheMap;
    private readonly LinkedList<(string, TItem)> lruList;

    public Cache(int capacity)
    {
        this.capacity = capacity;
        cacheMap = new Dictionary<string, LinkedListNode<(string, TItem)>>();
        lruList = new LinkedList<(string, TItem)>();
    }

    public void Put(string key, TItem item)
    {
        if (cacheMap.TryGetValue(key, out var node))
        {
            lruList.Remove(node);
            lruList.AddFirst(node);
            node.Value = (key, item);
        }
        else
        {
            if (cacheMap.Count >= capacity)
            {
                var last = lruList.Last;
                lruList.RemoveLast();
                cacheMap.Remove(last.Value.Item1);
            }
            var newNode = new LinkedListNode<(string, TItem)>((key, item));
            lruList.AddFirst(newNode);
            cacheMap[key] = newNode;
        }
    }

    public TItem Get(string key)
    {
        if (cacheMap.TryGetValue(key, out var node))
        {
            lruList.Remove(node);
            lruList.AddFirst(node);
            return node.Value.Item2;
        }
        return default(TItem);
    }
}
