            PropertyInfo propInfo = typeof(T).GetProperty(propertyName);
            if (propInfo == null)
            {
                throw new ArgumentException($"Property '{propertyName}' does not exist on type '{typeof(T).Name}'.");
            }

            if (direction == Direction.Ascending)
            {
                return collection.OrderBy(x => propInfo.GetValue(x, null));
            }
            else
            {
                return collection.OrderByDescending(x => propInfo.GetValue(x, null));
            }
        }
    }
}
```

