using System;
using System.Linq.Expressions;
using System.Reflection;

public class ContractTypeHolder
{
    public string ContractType { get; set; }
    public int ContractDuration { get; set; }
    public object GetEntry(string propertyName)
    {
        PropertyInfo propertyInfo = typeof(ContractTypeHolder).GetProperty(propertyName);
        if (propertyInfo != null)
        {
            return propertyInfo.GetValue(this);
        }
        else
        {
            throw new ArgumentException("Property not found");
        }
    }
}

public static class PropertyExtractor
{
    public static object GetPropertyValue<T>(T obj, string propertyName)
    {
        Expression<Func<T, object>> getEntryExpression = (o, p) => o.GetEntry(p);
        MethodInfo getEntryMethod = ((MethodCallExpression)getEntryExpression.Body).Method;

        return getEntryMethod.Invoke(obj, new object[] { propertyName });
    }
}

public class Program
{
    public static void Main()
    {
        ContractTypeHolder holder = new ContractTypeHolder { ContractType = "Full-time", ContractDuration = 12 };
