```csharp
using System;
using System.Collections.Generic;

namespace LHGames.Interfaces
{
    public class GameSimulator
    {
        private int[,] grid;
        private Dictionary<Player, Tuple<int, int>> playerPositions;

        public void initializeGrid(int width, int height)
        {
            grid = new int[width, height];
            Random random = new Random();
            for (int i = 0; i < width; i++)
            {
                for (int j = 0; j < height; j++)
                {
                    grid[i, j] = random.Next(1, 10); // Randomly assign resources to each cell
                }
            }
        }

        public void addPlayer(Player player, int x, int y)
        {
            if (playerPositions == null)
            {
                playerPositions = new Dictionary<Player, Tuple<int, int>>();
            }
            playerPositions[player] = new Tuple<int, int>(x, y);
        }

        public void movePlayer(Player player, Direction direction)
        {
            if (playerPositions.ContainsKey(player))
            {
                Tuple<int, int> currentPosition = playerPositions[player];
                int newX = currentPosition.Item1;
                int newY = currentPosition.Item2;

                switch (direction)
                {
                    case Direction.Up:
                        newY--;
                        break;
                    case Direction.Down:
                        newY++;
                        break;
                    case Direction.Left:
                        newX--;
                        break;
                    case Direction.Right:
                        newX++;
                        break;
                }

                if (isValidMove(newX, newY))
                {
                    playerPositions[player] = new Tuple<int, int>(newX, newY);
                }
            }
        }

        public void collectResources(Player player)
        {
            if (playerPositions.ContainsKey(player))
            {
                Tuple<int, int> currentPosition = playerPositions[player];
                int x = currentPosition.Item1;
                int y = currentPosition.Item2;

                if (isValidCell(x, y))
                {
                    player.Resources += grid[x, y];
                    grid[x, y] = 0; // Clear the resources from the cell
                }
            }
        }

        public void simulateRound()
        {
            foreach (var player in playerPositions.Keys)
            {
                // Simulate movement and resource collection for each player
                movePlayer(player, GetRandomDirection());
                collectResources(player);
            }
        }

        private bool isValidMove(int x, int y)
        {
            return x >= 0 && x < grid.GetLength(0) && y >= 0 && y < grid.GetLength(1);
        }

        private bool isValidCell(int x, int y)
        {
            return isValidMove(x, y) && grid[x, y] > 0;
        }

        private Direction GetRandomDirection()
        {
            Array values = Enum.GetValues(typeof(Direction));
            Random random = new Random();
            return (Direction)values.GetValue(random.Next(values.Length));
        }
    }
}
```
In this solution, the `GameSimulator` class is implemented with the specified functionalities. The grid is initialized with random resources, players can be added and moved on the grid, and they can collect resources from the cells they are on. The `simulateRound` method allows simulating a round of the game, where each player moves and collects resources.

