```csharp
using System;
using System.Collections;
using System.Collections.Generic;
using System.Text;

public class JsonSerializer
{
    public string SerializeToJson(object obj)
    {
        StringBuilder jsonUtf8 = new StringBuilder();
        SerializeValue(obj, jsonUtf8);
        return jsonUtf8.ToString();
    }

    private void SerializeValue(object value, StringBuilder jsonUtf8)
    {
        if (value == null)
        {
            jsonUtf8.Append("null");
        }
        else if (value is string)
        {
            SerializeString((string)value, jsonUtf8);
        }
        else if (value is bool)
        {
            jsonUtf8.Append((bool)value ? "true" : "false");
        }
        else if (value is int || value is long || value is float || value is double)
        {
            jsonUtf8.Append(Convert.ToString(value, System.Globalization.CultureInfo.InvariantCulture));
        }
        else if (value is IEnumerable)
        {
            SerializeArray((IEnumerable)value, jsonUtf8);
        }
        else
        {
            SerializeObject(value, jsonUtf8);
        }
    }

    private void SerializeString(string value, StringBuilder jsonUtf8)
    {
        jsonUtf8.Append('"');
        foreach (char c in value)
        {
            switch (c)
            {
                case '"':
                    jsonUtf8.Append("\\\"");
                    break;
                case '\\':
                    jsonUtf8.Append("\\\\");
                    break;
                case '\b':
                    jsonUtf8.Append("\\b");
                    break;
                case '\f':
                    jsonUtf8.Append("\\f");
                    break;
                case '\n':
                    jsonUtf8.Append("\\n");
                    break;
                case '\r':
                    jsonUtf8.Append("\\r");
                    break;
                case '\t':
                    jsonUtf8.Append("\\t");
                    break;
                default:
                    if (char.GetUnicodeCategory(c) != System.Globalization.UnicodeCategory.Control)
                    {
                        jsonUtf8.Append(c);
                    }
                    else
                    {
                        jsonUtf8.Append("\\u" + ((int)c).ToString("x4"));
                    }
                    break;
            }
        }
        jsonUtf8.Append('"');
    }

    private void SerializeArray(IEnumerable array, StringBuilder jsonUtf8)
    {
        jsonUtf8.Append('[');
        bool first = true;
        foreach (var value in array)
        {
            if (!first)
            {
                jsonUtf8.Append(',');
            }
            SerializeValue(value, jsonUtf8);
            first = false;
        }
        jsonUtf8.Append(']');
    }

    private void SerializeObject(object obj, StringBuilder jsonUtf8)
    {
        jsonUtf8.Append('{');
        bool first = true;
        foreach (var property in obj.GetType().GetProperties())
        {
            if (!first)
            {
                jsonUtf8.Append(',');
            }
            SerializeString(property.Name, jsonUtf8);
            jsonUtf8.Append(':');
            SerializeValue(property.GetValue(obj), jsonUtf8);
            first = false;
        }
        jsonUtf8.Append('}');
    }
}
```

This solution provides a `JsonSerializer` class with a `SerializeToJson` method that serializes an object into a JSON string. The `SerializeToJson` method handles primitive types, arrays, and objects, including nested objects and arrays, and produces a valid JSON string according to the provided example.

