using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class ResourceService
{
    private readonly string connectionString;

    public ResourceService(string connectionString) => this.connectionString = connectionString;

    public async Task<List<string>> GetResourcesAsync(string resourceGroup)
    {
        List<string> resources = new List<string>();
        using (SqlConnection conn = await ConnectionHelper.GetOpenConnectionAsync(connectionString))
        {
            SqlCommand command = conn.CreateCommand();
            command.CommandText = "SELECT ResourceName FROM Resources WHERE ResourceGroup = @ResourceGroup";
            command.Parameters.AddWithValue("@ResourceGroup", resourceGroup);

            try
            {
                using (SqlDataReader reader = await command.ExecuteReaderAsync())
                {
                    while (await reader.ReadAsync())
                    {
                        resources.Add(reader.GetString(0));
                    }
                }
            }
            catch (SqlException ex)
            {
                // Handle SQL exception, log the error, and possibly throw a custom exception
                Console.WriteLine($"Error retrieving resources: {ex.Message}");
                throw;
            }
            catch (Exception ex)
            {
                // Handle other exceptions, log the error, and possibly throw a custom exception
                Console.WriteLine($"Error retrieving resources: {ex.Message}");
                throw;
            }
        }
        return resources;
    }
}

public static class ConnectionHelper
{
    public static async Task<SqlConnection> GetOpenConnectionAsync(string connectionString)
    {
        SqlConnection connection = new SqlConnection(connectionString);
        try
        {
            await connection.OpenAsync();
            return connection;
        }
        catch (SqlException ex)
        {
            // Handle SQL exception, log the error, and possibly throw a custom exception
            Console.WriteLine($"Error opening connection: {ex.Message}");
            throw;
        }
        catch (Exception ex)
        {
            // Handle other exceptions, log the error, and possibly throw a custom exception
            Console.WriteLine($"Error opening connection: {ex.Message}");
            throw;
        }
    }
}
