```csharp
using System;
using System.Collections.Generic;

public interface IDependencyResolver
{
    T Resolve<T>();
    object Resolve(Type type);
}

public class DependencyContainer : IDependencyResolver
{
    private readonly Dictionary<Type, Func<object>> _transientRegistrations = new Dictionary<Type, Func<object>>();
    private readonly Dictionary<Type, object> _singletonRegistrations = new Dictionary<Type, object>();

    public void RegisterTransient<TService, TImplementation>() where TImplementation : TService, new()
    {
        _transientRegistrations[typeof(TService)] = () => new TImplementation();
    }

    public void RegisterTransient<TService>(Func<TService> factoryMethod)
    {
        _transientRegistrations[typeof(TService)] = () => factoryMethod();
    }

    public void RegisterSingleton<TService, TImplementation>() where TImplementation : TService, new()
    {
        _singletonRegistrations[typeof(TService)] = new TImplementation();
    }

    public void RegisterSingleton<TService>(TService instance)
    {
        _singletonRegistrations[typeof(TService)] = instance;
    }

    public T Resolve<T>()
    {
        return (T)Resolve(typeof(T));
    }

    public object Resolve(Type type)
    {
        if (_transientRegistrations.TryGetValue(type, out var transientFactory))
        {
            return transientFactory();
        }

        if (_singletonRegistrations.TryGetValue(type, out var singletonInstance))
        {
            return singletonInstance;
        }

        throw new InvalidOperationException($"No registration for type '{type}'");
    }
}
```

This solution provides a basic implementation of a dependency injection container that supports registering and resolving transient and singleton dependencies. It allows for flexible registration of dependencies and resolves them using the provided registrations. The implementation can be extended to support additional features such as constructor parameter injection and handling circular dependencies.

