using System;

public class BankAccount
{
    private static int accountNumberCounter = 1001;
    private int accountNumber;
    private double balance;

    public BankAccount(double initialBalance)
    {
        accountNumber = accountNumberCounter++;
        balance = initialBalance;
    }

    public void Deposit(double amount)
    {
        balance += amount;
    }

    public bool Withdraw(double amount)
    {
        if (balance >= amount)
        {
            balance -= amount;
            return true;
        }
        return false;
    }

    public void Transfer(BankAccount recipient, double amount)
    {
        if (Withdraw(amount))
        {
            recipient.Deposit(amount);
            Console.WriteLine($"Transferred ${amount} from Account {accountNumber} to Account {recipient.accountNumber}");
        }
        else
        {
            Console.WriteLine($"Insufficient funds in Account {accountNumber} for the transfer");
        }
    }

    public string GetAccountInfo()
    {
        return $"Account Number: {accountNumber}, Balance: ${balance:F2}";
    }
}

class Program
{
    static void Main()
    {
        BankAccount account1 = new BankAccount(1000);
        BankAccount account2 = new BankAccount(500);

        Console.WriteLine("Initial Account Information:");
        Console.WriteLine(account1.GetAccountInfo());
        Console.WriteLine(account2.GetAccountInfo());

        account1.Deposit(500);
        account2.Deposit(200);

        Console.WriteLine("\nAccount Information after Deposits:");
        Console.WriteLine(account1.GetAccountInfo());
        Console.WriteLine(account2.GetAccountInfo());

        account1.Withdraw(200);
        account2.Withdraw(100);

        Console.WriteLine("\nAccount Information after Withdrawals:");
        Console.WriteLine(account1.GetAccountInfo());
        Console.WriteLine(account2.GetAccountInfo());

        account1.Transfer(account2, 300);

        Console.WriteLine("\nAccount Information after Transfer:");
        Console.WriteLine(account1.GetAccountInfo());
        Console.WriteLine(account2.GetAccountInfo());
    }
}
