            return new ConfigOptionList(Error: false, string.Empty, Extract(hoconObject).Select(s => new ConfigOption(s.Path, s.DefaultValue)).ToArray());
        }
        catch (Exception e)
        {
            return new ConfigOptionList(Error: true, e.Message, new ConfigOption[0]);
        }
    }

    private static List<(string Path, string DefaultValue)> Extract(HoconObject hoconObject, string currentPath = "")
    {
        var result = new List<(string Path, string DefaultValue)>();

        foreach (var field in hoconObject.Items)
        {
            var path = string.IsNullOrEmpty(currentPath) ? field.Key : $"{currentPath}.{field.Key}";
            if (field.Value.IsObject())
            {
                result.AddRange(Extract(field.Value.GetObject(), path));
            }
            else
            {
                result.Add((path, field.Value.ToString()));
            }
        }

        return result;
    }
}
