    static void Main()
    {
        string phrase = "the quick brown fox jumps over the lazy dog";
        Dictionary<string, int> biGramFrequency = GetBiGramFrequency(phrase);
        PrintBiGramFrequency(biGramFrequency);
    }

    static Dictionary<string, int> GetBiGramFrequency(string phrase)
    {
        string[] words = phrase.Split(' ');
        Dictionary<string, int> biGramFrequency = new Dictionary<string, int>();

        for (int i = 0; i < words.Length - 1; i++)
        {
            string biGram = $"{words[i]} {words[i + 1]}";
            if (biGramFrequency.ContainsKey(biGram))
            {
                biGramFrequency[biGram]++;
            }
            else
            {
                biGramFrequency[biGram] = 1;
            }
        }

        return biGramFrequency;
    }

    static void PrintBiGramFrequency(Dictionary<string, int> biGramFrequency)
    {
        Console.WriteLine("BiGram Analysis:");
        foreach (var biGram in biGramFrequency.OrderByDescending(pair => pair.Value))
        {
            Console.WriteLine($"{biGram.Key}: {biGram.Value}");
        }
    }
}
```

