public class Message
{
    public int m_activateEventId;
    public uint m_attachmentLength;
    public string m_attachment;

    public void Serialize(BinaryWriter bw)
    {
        bw.Write(m_activateEventId);
        bw.Write(m_attachmentLength);
        bw.Write(Encoding.UTF8.GetBytes(m_attachment));
    }

    public static Message Deserialize(BinaryReader br)
    {
        Message message = new Message();
        message.m_activateEventId = br.ReadInt32();
        message.m_attachmentLength = br.ReadUInt32();
        byte[] attachmentBytes = br.ReadBytes((int)message.m_attachmentLength);
        message.m_attachment = Encoding.UTF8.GetString(attachmentBytes);
        return message;
    }
}
