internal class RegisterAnswerContextModel : IMessageContextModel
{
    public Dictionary<string, int> CardsInBins = new Dictionary<string, int>();

    public void MoveCardToBin(string currentBin, bool isCorrectAnswer)
    {
        if (CardsInBins.ContainsKey(currentBin))
        {
            int currentCount = CardsInBins[currentBin];
            if (isCorrectAnswer)
            {
                if (currentCount > 0)
                {
                    CardsInBins[currentBin]--;
                    if (CardsInBins.ContainsKey("NextBin"))
                    {
                        CardsInBins["NextBin"]++;
                    }
                    else
                    {
                        CardsInBins["NextBin"] = 1;
                    }
                }
            }
            else
            {
                if (currentCount > 0)
                {
                    CardsInBins[currentBin]--;
                    if (CardsInBins.ContainsKey("PreviousBin"))
                    {
                        CardsInBins["PreviousBin"]++;
                    }
                    else
                    {
                        CardsInBins["PreviousBin"] = 1;
                    }
                }
            }
        }
    }
}
