```csharp
using UnityEngine;

public class LeanTranslate : MonoBehaviour
{
    [Tooltip("Ignore fingers with StartedOverGui?")]
    public bool IgnoreStartedOverGui = true;

    [Tooltip("Ignore fingers with IsOverGui?")]
    public bool IgnoreIsOverGui;

    [Tooltip("Ignore fingers if the finger count doesn't match? (0 = any)")]
    public int RequiredFingerCount;

    private Camera mainCamera;

    private void Start()
    {
        mainCamera = Camera.main;
    }

    private void Update()
    {
        if (Input.touchCount == RequiredFingerCount || RequiredFingerCount == 0)
        {
            for (int i = 0; i < Input.touchCount; i++)
            {
                Touch touch = Input.GetTouch(i);

                if ((IgnoreStartedOverGui && touch.phase == TouchPhase.Began && EventSystem.current.IsPointerOverGameObject(touch.fingerId)) ||
                    (IgnoreIsOverGui && EventSystem.current.IsPointerOverGameObject(touch.fingerId)))
                {
                    continue; // Ignore touch input over GUI elements
                }

                if (touch.phase == TouchPhase.Moved)
                {
                    Vector3 touchPosition = new Vector3(touch.position.x, touch.position.y, 0);
                    Vector3 worldPosition = mainCamera.ScreenToWorldPoint(touchPosition);
                    transform.position = worldPosition;
                }
            }
        }
    }
}
