{
    public List<MathMLNode> Children { get; } = new List<MathMLNode>();
}

public class MathMLParser
{
    public string ParseMathML(MathMLNode root)
    {
        StringBuilder parsedExpression = new StringBuilder();
        ParseNode(root, parsedExpression);
        return parsedExpression.ToString().Trim();
    }

    private void ParseNode(MathMLNode node, StringBuilder parsedExpression)
    {
        if (node is MathMLIdentifier identifier)
        {
            foreach (var child in identifier.Children)
            {
                ParseNode(child, parsedExpression);
                parsedExpression.Append(" ");
            }
        }
        else if (node is MathMLTextNode textNode)
        {
            parsedExpression.Append(textNode.Text);
        }
    }
}
