public class Container
{
    private static Container _instance;
    private Dictionary<string, object> _registry;

    public static Container Instance
    {
        get
        {
            if (_instance == null)
                _instance = new Container();

            return _instance;
        }
    }

    private Container()
    {
        _registry = new Dictionary<string, object>();
    }

    public void Register<T>(string key, T instance)
    {
        if (!_registry.ContainsKey(key))
            _registry.Add(key, instance);
        else
            throw new InvalidOperationException($"Key '{key}' is already registered in the container.");
    }

    public T Resolve<T>(string key)
    {
        if (_registry.ContainsKey(key))
            return (T)_registry[key];
        else
            return default(T);
    }
}

public class Program
{
    public static void Main()
    {
        Container container = Container.Instance;

        // Registering dependencies
        container.Register("logger", new Logger());
        container.Register("service", new Service());

        // Resolving dependencies
