List<string> UnifyStackTraces(List<string> managedStackTrace, List<string> nativeStackTrace) {
    List<string> unifiedStackTrace = new List<string>();
    int managedFrame = 0;

    for (int temp = 0; temp < managedStackTrace.Count; temp++) {
        bool found = false;

        for (int i = 0; i < nativeStackTrace.Count; i++) {
            if (managedStackTrace[temp] == nativeStackTrace[i]) {
                found = true;
                break;
            }
        }

        if (found) {
            unifiedStackTrace.Add(managedStackTrace[temp]);
            managedFrame = temp + 1;
        } else if (managedFrame > 0) {
            unifiedStackTrace.Add(managedStackTrace[temp]);
            managedFrame = temp + 1;
        }
    }

    return unifiedStackTrace;
}
```

