public class BitsSeqEndianCombo
{
    public enum Endianness
    {
        LittleEndian,
        BigEndian
    }

    public static byte[] FromFile(string filePath)
    {
        byte[] fileBytes = File.ReadAllBytes(filePath);
        byte[] parsedBits = new byte[fileBytes.Length * 8]; // Each byte contains 8 bits

        for (int i = 0; i < fileBytes.Length; i++)
        {
            byte currentByte = fileBytes[i];
            for (int j = 0; j < 8; j++)
            {
                int bitIndex = (i * 8) + (EndiannessIsLittleEndian() ? j : 7 - j);
                parsedBits[bitIndex] = (byte)((currentByte >> j) & 1);
            }
        }

        return parsedBits;
    }

    private static bool EndiannessIsLittleEndian()
    {
        int testValue = 1;
        byte[] bytes = BitConverter.GetBytes(testValue);
        return bytes[0] == 1; // If true, system is little-endian
    }
}
```

