using System;
using System.Collections.Generic;

public class OrderedDictionary<TKey, TValue>
{
    private readonly Dictionary<TKey, TValue> dictionary;
    private readonly List<TKey> insertionOrder;

    public OrderedDictionary()
    {
        dictionary = new Dictionary<TKey, TValue>();
        insertionOrder = new List<TKey>();
    }

    public void Add(TKey key, TValue value)
    {
        if (dictionary.ContainsKey(key))
        {
            dictionary[key] = value;
        }
        else
        {
            dictionary.Add(key, value);
            insertionOrder.Add(key);
        }
    }

    public void Remove(TKey key)
    {
        if (dictionary.ContainsKey(key))
        {
            dictionary.Remove(key);
            insertionOrder.Remove(key);
        }
    }

    public TValue GetValue(TKey key)
    {
        return dictionary[key];
    }

    public IEnumerable<TKey> GetKeys()
    {
        return insertionOrder;
    }

    public IEnumerable<TValue> GetValues()
    {
        foreach (var key in insertionOrder)
        {
            yield return dictionary[key];
        }
    }
}
```

This implementation of `OrderedDictionary` uses a `Dictionary` to store key-value pairs and a `List` to maintain the insertion order of keys. The `Add` method checks if the key already exists and updates the value if necessary, while also updating the insertion order. The `Remove` method removes the key-value pair from both the dictionary and the insertion order list. The `GetValue`, `GetKeys`, and `GetValues` methods provide access to the stored data while preserving the insertion order.

