```csharp
public enum Lifetime
{
    Transient,
    Singleton
}

public class DependencyContainer
{
    private readonly Dictionary<Type, Type> _registeredTypes = new Dictionary<Type, Type>();
    private readonly Dictionary<Type, object> _singletonInstances = new Dictionary<Type, object>();

    public void Register<TInterface, TImplementation>(Lifetime lifetime = Lifetime.Transient)
    {
        var interfaceType = typeof(TInterface);
        var implementationType = typeof(TImplementation);

        if (lifetime == Lifetime.Singleton && !_singletonInstances.ContainsKey(interfaceType))
        {
            _singletonInstances[interfaceType] = Activator.CreateInstance(implementationType);
        }

        _registeredTypes[interfaceType] = implementationType;
    }

    public TInterface Resolve<TInterface>()
    {
        return (TInterface)Resolve(typeof(TInterface));
    }

    private object Resolve(Type type)
    {
        if (_registeredTypes.TryGetValue(type, out var implementationType))
        {
            if (_singletonInstances.TryGetValue(type, out var instance))
            {
                return instance;
            }

            var constructor = implementationType.GetConstructors().First();
            var parameters = constructor.GetParameters()
                .Select(parameter => Resolve(parameter.ParameterType))
                .ToArray();

            var instance = Activator.CreateInstance(implementationType, parameters);
            return instance;
        }

        throw new InvalidOperationException($"Type {type.Name} is not registered in the container.");
    }
}
```

This solution provides a simple implementation of a dependency injection container in PascalABC.NET. The `DependencyContainer` class allows registration of types and their corresponding interfaces, supports both singleton and transient lifetimes, and resolves types with their dependencies using constructor injection. The example usage scenario demonstrates the registration and resolution of types using the `DependencyContainer`.

