using System.Threading.Tasks;

public class RuleManager
{
    private Dictionary<string, Task> ruleTasks = new Dictionary<string, Task>();

    public async Task ExecuteRuleAsync(string ruleName, Func<Task> action)
    {
        if (ruleTasks.ContainsKey(ruleName))
        {
            await ruleTasks[ruleName]; // Wait for the original actions to complete.
        }

        ruleTasks[ruleName] = action(); // Set up new observer for the rule.
    }

    public Task WaitForRuleActionsCompletedAsync(string ruleName)
    {
        if (ruleTasks.ContainsKey(ruleName))
        {
            return ruleTasks[ruleName]; // Return the task associated with the rule.
        }
        else
        {
            return Task.CompletedTask; // Return a completed task if the rule is not found.
        }
    }
}
