internal static void secp256k1_musig_sum_nonces(Span<GEJ> summed_nonces, MusigPubNonce[] pubnonces)
{
    int i;
    summed_nonces[0] = GEJ.Infinity;
    summed_nonces[1] = GEJ.Infinity;

    // Iterate through the MusigPubNonce array and sum the nonces
    for (i = 0; i < pubnonces.Length; i++)
    {
        // Convert the MusigPubNonce to group elements
        GE pubnonce0 = pubnonces[i].pubkeys[0].data;
        GE pubnonce1 = pubnonces[i].pubkeys[1].data;

        // Add the individual nonces to the summed_nonces
