    public interface IDependencyResolver
    {
        void Register<TService, TImplementation>() where TImplementation : TService;
        T Resolve<T>();
    }

    public class DependencyContainer : IDependencyResolver
    {
        private readonly Dictionary<Type, Type> _typeMap = new Dictionary<Type, Type>();

        public void Register<TService, TImplementation>() where TImplementation : TService
        {
            _typeMap[typeof(TService)] = typeof(TImplementation);
        }

        public T Resolve<T>()
        {
            return (T)Resolve(typeof(T));
        }

        private object Resolve(Type type)
        {
            Type implementationType = _typeMap[type];
            var constructor = implementationType.GetConstructors().First();
            var parameters = constructor.GetParameters().Select(p => Resolve(p.ParameterType)).ToArray();
            var instance = Activator.CreateInstance(implementationType, parameters);

            foreach (var property in implementationType.GetProperties().Where(p => p.CanWrite))
            {
                if (property.PropertyType.IsInterface)
                {
                    property.SetValue(instance, Resolve(property.PropertyType));
                }
            }

            return instance;
        }
    }

    public interface IService
    {
        void Serve();
    }

    public class Service : IService
    {
        public void Serve()
        {
            Console.WriteLine("Service served.");
        }
    }

