public class ResourceDictionaryManager
{
    private ResourceDictionary Resources { get; }

    public ResourceDictionaryManager(ResourceDictionary resources)
    {
        Resources = resources ?? throw new ArgumentNullException(nameof(resources));
    }

    public void AddResourceDictionary(string resourceFileName)
    {
        if (string.IsNullOrEmpty(resourceFileName))
        {
            throw new ArgumentException("Resource file name cannot be null or empty.");
        }

        if (!File.Exists(resourceFileName))
        {
            throw new FileNotFoundException("Specified resource file not found or could not be loaded.", resourceFileName);
        }

        ResourceDictionary newResourceDictionary = new ResourceDictionary();
        newResourceDictionary.Source = new Uri(resourceFileName, UriKind.RelativeOrAbsolute);

        bool dictionaryExists = false;
        for (int i = 0; i < Resources.MergedDictionaries.Count; i++)
        {
            if (Resources.MergedDictionaries[i].Source == newResourceDictionary.Source)
            {
                Resources.MergedDictionaries[i] = newResourceDictionary;
                dictionaryExists = true;
                break;
            }
        }

        if (!dictionaryExists)
        {
            Resources.MergedDictionaries.Add(newResourceDictionary);
        }
    }
}
```

