```csharp
using System;

public class InsufficientFundsException : Exception
{
    public InsufficientFundsException(string message) : base(message) { }
}

public class BankAccount
{
    public string AccountNumber { get; }
    public decimal Balance { get; protected set; }

    public BankAccount(string accountNumber, decimal initialBalance)
    {
        AccountNumber = accountNumber;
        Balance = initialBalance;
    }

    public virtual void Deposit(decimal amount)
    {
        Balance += amount;
    }

    public virtual void Withdraw(decimal amount)
    {
        if (Balance - amount < 0)
        {
            throw new InsufficientFundsException("Insufficient funds for withdrawal");
        }
        Balance -= amount;
    }

    public virtual void Transfer(decimal amount, BankAccount targetAccount)
    {
        if (Balance - amount < 0)
        {
            throw new InsufficientFundsException("Insufficient funds for transfer");
        }
        Balance -= amount;
        targetAccount.Deposit(amount);
    }
}

public class SavingsAccount : BankAccount
{
    public decimal InterestRate { get; }

    public SavingsAccount(string accountNumber, decimal initialBalance, decimal interestRate)
        : base(accountNumber, initialBalance)
    {
        InterestRate = interestRate;
    }

    public override void Withdraw(decimal amount)
    {
        if (Balance - amount < 0)
        {
            throw new InsufficientFundsException("Insufficient funds for withdrawal");
        }
        Balance -= amount;
    }
}

public class CheckingAccount : BankAccount
{
    public decimal OverdraftLimit { get; }

    public CheckingAccount(string accountNumber, decimal initialBalance, decimal overdraftLimit)
        : base(accountNumber, initialBalance)
    {
        OverdraftLimit = overdraftLimit;
    }

    public override void Withdraw(decimal amount)
    {
        if (Balance - amount < -OverdraftLimit)
        {
            throw new InsufficientFundsException("Exceeds overdraft limit for withdrawal");
        }
        Balance -= amount;
    }
}
