using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.Linq;
using System.Threading.Tasks;

public class CustomAuthorizationAttribute : AuthorizeAttribute, IAsyncAuthorizationFilter
{
    private readonly string _role;
    private readonly string _ipAddressSettingKey = "PrivilegedIPs"; // Key to retrieve privileged IPs from settings

    public CustomAuthorizationAttribute(string role)
    {
        _role = role;
    }

    public async Task OnAuthorizationAsync(AuthorizationFilterContext context)
    {
        var user = context.HttpContext.User;

        if (!user.Identity.IsAuthenticated)
        {
            context.Result = new StatusCodeResult(StatusCodes.Status401Unauthorized);
            return;
        }

        if (!user.IsInRole(_role))
        {
            context.Result = new StatusCodeResult(StatusCodes.Status403Forbidden);
            return;
        }

        var privilegedIPs = await GetPrivilegedIPsFromSettings(context.HttpContext.RequestServices);
        var clientIP = context.HttpContext.Connection.RemoteIpAddress;

        if (!privilegedIPs.Contains(clientIP))
        {
            context.Result = new StatusCodeResult(StatusCodes.Status403Forbidden);
            return;
        }
    }

    private async Task<IPNetwork[]> GetPrivilegedIPsFromSettings(IServiceProvider serviceProvider)
    {
        // Retrieve privileged IPs from settings using a service or repository
        var settingsService = serviceProvider.GetRequiredService<ISettingsService>();
        var privilegedIPs = await settingsService.GetPrivilegedIPsAsync(_ipAddressSettingKey);

        return privilegedIPs.Select(ip => IPNetwork.Parse(ip)).ToArray();
    }
}
```

In the solution, a custom authorization attribute `CustomAuthorizationAttribute` is created by extending the `AuthorizeAttribute` and implementing the `IAsyncAuthorizationFilter` interface. The `OnAuthorizationAsync` method is overridden to perform the role-based and IP address-based authorization logic. The privileged IP addresses are retrieved from the settings using a service and validated against the incoming request's IP address. If the user is not authenticated, not in the specified role, or the IP address is not privileged, the request is denied with the appropriate status code.

