// Implement Line class inheriting from Shape
public class Line : Shape
{
    private Point start;
    private Point end;

    public Line(Point start, Point end)
    {
        this.start = start;
        this.end = end;
    }

    public override void Draw(Graphics graphics)
    {
        graphics.DrawLine(Pens.Black, start, end);
    }

    public override bool ContainsPoint(Point point)
    {
        // For simplicity, assume a small tolerance for clicking on the line
        return DistancePointToLine(start, end, point) < 3;
    }

    private float DistancePointToLine(Point start, Point end, Point point)
    {
        float dx = end.X - start.X;
        float dy = end.Y - start.Y;
        float length = (float)Math.Sqrt(dx * dx + dy * dy);
        float u = ((point.X - start.X) * dx + (point.Y - start.Y) * dy) / (length * length);
        float x = start.X + u * dx;
        float y = start.Y + u * dy;
        return (float)Math.Sqrt((point.X - x) * (point.X - x) + (point.Y - y) * (point.Y - y));
    }
}

