using Sprache;

public class HttpHeaderParser
{
    static readonly Parser<char> s_hTab = Char('\t').Named("HTAB");
    static readonly Parser<char> s_sp = Char(' ').Named("SP");
    static readonly Parser<char> s_obsText = Char(c => c >= 0x80 && c <= 0xFF, "observable text").Named("obs-text");

    static readonly Parser<char> s_qdText =
        s_hTab.XOr(s_sp)
            .XOr(Char('!'))
            .XOr(Char(c => c >= 0x23 && c <= 0x5B, "%x23-5B"))
            .XOr(Char(c => c >= 0x5D && c <= 0x7E, "%x5D-7E"))
            .XOr(s_obsText)
            .Named("QDTEXT");

    static readonly Parser<char> s_dQuote = Char('"').Named("DQUOTE");

    static readonly Parser<char> s_quotedPair =
        Char('\\').Then(_ => AnyChar).Named("quoted-pair");

    static readonly Parser<string> s_quotedString =
        from open in s_dQuote
        from content in s_qdText.Or(s_quotedPair).Many().Text()
        from close in s_dQuote
        select content;

    public static string ParseHeaderValue(string input)
