using System;
using System.Collections.Generic;
using System.Threading;

public enum DisposalPolicy
{
    Automatic,
    Manual,
    Custom
}

public class ResourceManagement : IDisposable
{
    private DisposalPolicy _disposalPolicy;
    private List<IDisposable> _resources = new List<IDisposable>();
    private bool _disposed = false;
    private object _lock = new object();

    public ResourceManagement(DisposalPolicy disposalPolicy)
    {
        _disposalPolicy = disposalPolicy;
    }

    public void AddResource(IDisposable resource)
    {
        if (resource == null)
        {
            throw new ArgumentNullException(nameof(resource));
        }

        lock (_lock)
        {
            if (!_disposed)
            {
                _resources.Add(resource);
            }
            else
            {
                resource.Dispose();
            }
        }
    }

    public void Dispose()
    {
        if (_disposalPolicy == DisposalPolicy.Automatic)
        {
            DisposeResources();
        }
    }

