using System;
using System.Reflection;

public class TestRunner
{
    public void RunTests<T>() where T : new()
    {
        int totalTests = 0;
        int passedTests = 0;
        int failedTests = 0;

        T testClassInstance = new T();
        Type testClassType = typeof(T);

        foreach (var method in testClassType.GetMethods())
        {
            if (method.GetCustomAttributes(typeof(FactAttribute), false).Length > 0)
            {
                totalTests++;
                try
                {
                    method.Invoke(testClassInstance, null);
                    passedTests++;
                }
                catch (TargetInvocationException ex)
                {
                    Console.WriteLine($"Test {method.Name} failed: {ex.InnerException.Message}");
                    failedTests++;
                }
            }
        }

        Console.WriteLine($"Total tests run: {totalTests}");
        Console.WriteLine($"Tests passed: {passedTests}");
        Console.WriteLine($"Tests failed: {failedTests}");
    }
