public class RequestProcessor
{
    public string ProcessRequest(string jsonRequest)
    {
        JObject requestObject = JObject.Parse(jsonRequest);
        JArray names = (JArray)requestObject["names"];
        JArray types = (JArray)requestObject["types"];
        JArray values = (JArray)requestObject["values"];

        string processedInfo = "";
        for (int i = 0; i < names.Count; i++)
        {
            string name = names[i].ToString();
            string type = types[i].ToString();
            JToken value = values[i];

            if (type.Contains("["))
            {
                JArray arrayValue = (JArray)value;
                for (int j = 0; j < arrayValue.Count; j++)
                {
                    processedInfo += $"{name}.{j}: {arrayValue[j]}\n";
                }
            }
            else
            {
                processedInfo += $"{name}: {value}\n";
            }
        }

        return processedInfo.Trim();
    }
}

