namespace OSS.Tools.MsgDak
{
    class MsgDakFactory
    {
        public static string EncryptMessage(string message, int key)
        {
            StringBuilder encryptedMessage = new StringBuilder();
            foreach (char c in message)
            {
                if (char.IsLetter(c))
                {
                    char shiftedChar = (char)(c + key);
                    if ((char.IsLower(c) && shiftedChar > 'z') || (char.IsUpper(c) && shiftedChar > 'Z'))
                    {
                        shiftedChar = (char)(c - (26 - key));
                    }
                    encryptedMessage.Append(shiftedChar);
                }
                else
                {
                    encryptedMessage.Append(c);
                }
            }
            return encryptedMessage.ToString();
        }

        public static string DecryptMessage(string encryptedMessage, int key)
        {
            StringBuilder decryptedMessage = new StringBuilder();
            foreach (char c in encryptedMessage)
            {
                if (char.IsLetter(c))
                {
                    char shiftedChar = (char)(c - key);
                    if ((char.IsLower(c) && shiftedChar < 'a') || (char.IsUpper(c) && shiftedChar < 'A'))
                    {
                        shiftedChar = (char)(c + (26 - key));
                    }
                    decryptedMessage.Append(shiftedChar);
                }
                else
                {
                    decryptedMessage.Append(c);
                }
            }
            return decryptedMessage.ToString();
        }
    }
}
