    /// <summary>
    /// Encrypts the given file path based on certain criteria.
    /// </summary>
    /// <param name="path">The file path to be encrypted</param>
    /// <param name="existing">A boolean flag indicating whether the file must already exist</param>
    /// <returns>Fully encrypted path or empty string if the path cannot be found</returns>
    public string GetEncryptedPath(string path, bool existing)
    {
        if (existing && !File.Exists(path))
        {
            return string.Empty; // File does not exist, return empty string
        }

        // Custom encryption algorithm using XOR operation with the encryption key
        byte[] pathBytes = Encoding.UTF8.GetBytes(path);
        byte[] keyBytes = Encoding.UTF8.GetBytes(EncryptionKey);
        byte[] encryptedBytes = new byte[pathBytes.Length];

        for (int i = 0; i < pathBytes.Length; i++)
        {
            encryptedBytes[i] = (byte)(pathBytes[i] ^ keyBytes[i % keyBytes.Length]);
        }

        string encryptedPath = Convert.ToBase64String(encryptedBytes);
        return encryptedPath;
    }
}
