public class GeometricTransformation
{
    private readonly double[,] transformationMatrix;

    public GeometricTransformation(double[,] transformationMatrix)
    {
        if (transformationMatrix.GetLength(0) != 2 || transformationMatrix.GetLength(1) != 2)
        {
            throw new ArgumentException("Transformation matrix must be a 2x2 matrix");
        }

        this.transformationMatrix = transformationMatrix;
    }

    public double[,] Transform
    {
        get { return transformationMatrix; }
    }

    public Point Apply(Point point)
    {
        double x = transformationMatrix[0, 0] * point.X + transformationMatrix[0, 1] * point.Y;
        double y = transformationMatrix[1, 0] * point.X + transformationMatrix[1, 1] * point.Y;

        return new Point(x, y);
    }
}

public class Point
{
    public double X { get; }
    public double Y { get; }

    public Point(double x, double y)
    {
        X = x;
        Y = y;
    }
}
