using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;

public class PictureService
{
    private readonly HttpClient _http;

    public PictureService(HttpClient http)
    {
        _http = http;
    }

    public async Task<byte[]> DownloadImage(string url)
    {
        HttpResponseMessage response = await _http.GetAsync(url);
        if (response.IsSuccessStatusCode)
        {
            return await response.Content.ReadAsByteArrayAsync();
        }
        else
        {
            throw new Exception($"Failed to download image from {url}. Status code: {response.StatusCode}");
        }
    }

    public byte[] ResizeImage(byte[] imageData, int width, int height)
    {
        using (MemoryStream ms = new MemoryStream(imageData))
        {
            using (System.Drawing.Image originalImage = System.Drawing.Image.FromStream(ms))
            {
                using (System.Drawing.Image resizedImage = originalImage.GetThumbnailImage(width, height, null, IntPtr.Zero))
                {
                    using (MemoryStream msResized = new MemoryStream())
                    {
                        resizedImage.Save(msResized, originalImage.RawFormat);
                        return msResized.ToArray();
                    }
                }
            }
        }
    }

    public bool SaveImage(byte[] imageData, string filePath)
    {
        try
        {
            File.WriteAllBytes(filePath, imageData);
            return true;
        }
        catch (Exception)
        {
            return false;
        }
    }
}
