using System;
using System.Reflection;
using System.Reflection.Emit;

public class ILCodeGenerator
{
    public static string GenerateILCodeForValue(int value)
    {
        var dynamicMethod = new DynamicMethod("LoadValue", typeof(void), new Type[0]);
        var iLGenerator = dynamicMethod.GetILGenerator();

        if (value >= -128 && value <= 127)
        {
            iLGenerator.Emit(OpCodes.Ldc_I4_S, (sbyte)value);
        }
        else
        {
            iLGenerator.Emit(OpCodes.Ldc_I4, value);
        }

        iLGenerator.Emit(OpCodes.Ret);

        dynamicMethod.Invoke(null, null);

        return GetILCode(dynamicMethod);
    }

    private static string GetILCode(DynamicMethod dynamicMethod)
    {
        var methodBody = dynamicMethod.GetMethodBody().GetILAsByteArray();
        var ilCode = BitConverter.ToString(methodBody).Replace("-", " ");
        return ilCode;
    }
}
```

