    public class ProxyServer
    {
        private int port;
        private TcpListener listener;

        public ProxyServer(int port)
        {
            this.port = port;
            listener = new TcpListener(IPAddress.Any, port);
        }

        public void Start()
        {
            listener.Start();
            Console.WriteLine("Proxy server started on port " + port);
            while (true)
            {
                TcpClient client = listener.AcceptTcpClient();
                HandleRequest(client);
            }
        }

        private void HandleRequest(TcpClient client)
        {
            NetworkStream clientStream = client.GetStream();
            byte[] buffer = new byte[4096];
            int bytesRead = clientStream.Read(buffer, 0, buffer.Length);
            string request = Encoding.ASCII.GetString(buffer, 0, bytesRead);
            string modifiedRequest = ModifyRequest(request);
            byte[] modifiedBuffer = Encoding.ASCII.GetBytes(modifiedRequest);
            clientStream.Write(modifiedBuffer, 0, modifiedBuffer.Length);
            client.Close();
        }

        private string ModifyRequest(string request)
        {
            // Modify the User-Agent header
            string modifiedRequest = request.Replace("User-Agent: ", "User-Agent: ProxyServer/1.0\r\n");
            return modifiedRequest;
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            ProxyServer proxyServer = new ProxyServer(8080);
            proxyServer.Start();
        }
    }
}
