namespace Katarai.Acceptance.StringCalculator.Tests.SpecificTestNegativeNumbers
{
    public class StringCalculator : IStringCalculator
    {
        private static readonly List<string> Delimiters = new List<string> { ",", "\n" };

        public int Add(string numbers)
        {
            if (string.IsNullOrEmpty(numbers))
            {
                return 0;
            }

            if (numbers.StartsWith("//"))
            {
                int delimiterEndIndex = numbers.IndexOf("\n");
                string customDelimiter = numbers.Substring(2, delimiterEndIndex - 2);
                numbers = numbers.Substring(delimiterEndIndex + 1);
                Delimiters.Add(customDelimiter);
            }

            List<int> parsedNumbers = numbers.Split(Delimiters.ToArray(), StringSplitOptions.None)
                .Select(int.Parse)
                .ToList();

            List<int> negativeNumbers = parsedNumbers.Where(n => n < 0).ToList();
            if (negativeNumbers.Any())
            {
                throw new ArgumentException("Negatives not allowed: " + string.Join(", ", negativeNumbers));
            }

            return parsedNumbers.Where(n => n <= 1000).Sum();
        }
    }
}
```

