public class ExecutionTimeLogAttribute : ActionFilterAttribute
{
    public override void OnActionExecuting(ActionExecutingContext filterContext)
    {
        filterContext.HttpContext.Items["StartTime"] = DateTime.Now;
    }

    public override void OnActionExecuted(ActionExecutedContext filterContext)
    {
        DateTime startTime = (DateTime)filterContext.HttpContext.Items["StartTime"];
        DateTime endTime = DateTime.Now;
        TimeSpan executionTime = endTime - startTime;
        string controllerName = filterContext.ActionDescriptor.ControllerDescriptor.ControllerName;
        string actionName = filterContext.ActionDescriptor.ActionName;
        string message = $"Action '{actionName}' in controller '{controllerName}' took {executionTime.TotalMilliseconds} ms to execute.";
        Debug.WriteLine(message);
    }
}

// SampleController.cs
