```csharp
using System;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using System.Text;
using ZYSocket.Interface;

namespace NetxFrame
{
    public class SerializationPacker
    {
        // Serialize an integer to a byte array
        public byte[] PackInt(int value)
        {
            return BitConverter.GetBytes(value);
        }

        // Deserialize an integer from a byte array
        public int UnpackInt(byte[] data, int offset)
        {
            return BitConverter.ToInt32(data, offset);
        }

        // Serialize a string to a byte array
        public byte[] PackString(string value)
        {
            byte[] stringBytes = Encoding.UTF8.GetBytes(value);
            byte[] lengthBytes = BitConverter.GetBytes(stringBytes.Length);
            byte[] result = new byte[lengthBytes.Length + stringBytes.Length];
            lengthBytes.CopyTo(result, 0);
            stringBytes.CopyTo(result, lengthBytes.Length);
            return result;
        }

        // Deserialize a string from a byte array
        public string UnpackString(byte[] data, int offset)
        {
            int length = BitConverter.ToInt32(data, offset);
            return Encoding.UTF8.GetString(data, offset + sizeof(int), length);
        }

        // Serialize a boolean to a byte array
        public byte[] PackBool(bool value)
        {
            return BitConverter.GetBytes(value);
        }

        // Deserialize a boolean from a byte array
        public bool UnpackBool(byte[] data, int offset)
        {
            return BitConverter.ToBoolean(data, offset);
        }

        // Serialize an object to a byte array
        public byte[] PackObject(object obj)
        {
            if (obj == null)
            {
                return new byte[0];
            }
            else
            {
                var binaryFormatter = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter();
                using (var memoryStream = new System.IO.MemoryStream())
                {
                    binaryFormatter.Serialize(memoryStream, obj);
                    return memoryStream.ToArray();
                }
            }
        }

        // Deserialize an object from a byte array
        public T UnpackObject<T>(byte[] data, int offset)
        {
            if (data == null || data.Length == 0)
            {
                return default(T);
            }
            else
            {
                var binaryFormatter = new System.Runtime.Serialization.Formatters.Binary.BinaryFormatter();
                using (var memoryStream = new System.IO.MemoryStream(data, offset, data.Length - offset))
                {
                    return (T)binaryFormatter.Deserialize(memoryStream);
                }
            }
        }
    }
}
```

