{
    public string PropertyName { get; }

    public PropertyChangedEventArgs(string propertyName)
    {
        PropertyName = propertyName;
    }
}

// Define the INotificationSubscription interface
public interface INotificationSubscription
{
    void Unsubscribe();
}

// Define the NotificationSubscription class implementing INotificationSubscription
public class NotificationSubscription : INotificationSubscription
{
    private readonly INotifyPropertyChanged _source;
    private readonly string _propertyName;
    private readonly PropertyChangedEventHandler _handler;

    public NotificationSubscription(INotifyPropertyChanged source, string propertyName, PropertyChangedEventHandler handler)
    {
        _source = source;
        _propertyName = propertyName;
        _handler = handler;
        _source.PropertyChanged += _handler;
    }

    public void Unsubscribe()
    {
        _source.PropertyChanged -= _handler;
    }
}

// Define the static class with the NotifyFor extension method
public static class NotifyExtensions
{
    public static INotificationSubscription NotifyFor<T>(this INotifyPropertyChanged source, Expression<Func<T>> propertyExpression)
    {
        var memberExpression = (MemberExpression)propertyExpression.Body;
        var propertyName = memberExpression.Member.Name;

        PropertyChangedEventHandler handler = (sender, e) =>
        {
            if (e.PropertyName == propertyName)
            {
                // Handle the property change notification
            }
        };

        return new NotificationSubscription(source, propertyName, handler);
    }
}
