using System;
using System.Collections.Generic;

public class Graph
{
    private Dictionary<int, List<int>> adjacencyList;

    public Graph()
    {
        adjacencyList = new Dictionary<int, List<int>>();
    }

    public void AddVertex(int vertex)
    {
        if (!adjacencyList.ContainsKey(vertex))
        {
            adjacencyList[vertex] = new List<int>();
        }
    }

    public void AddEdge(int fromVertex, int toVertex)
    {
        if (adjacencyList.ContainsKey(fromVertex) && adjacencyList.ContainsKey(toVertex))
        {
            adjacencyList[fromVertex].Add(toVertex);
        }
        else
        {
            throw new ArgumentException("Both vertices must exist in the graph");
        }
    }

    public bool HasPath(int fromVertex, int toVertex)
    {
        if (!adjacencyList.ContainsKey(fromVertex) || !adjacencyList.ContainsKey(toVertex))
        {
            return false;
        }

        Queue<int> queue = new Queue<int>();
        HashSet<int> visited = new HashSet<int>();

        queue.Enqueue(fromVertex);
        visited.Add(fromVertex);

        while (queue.Count > 0)
        {
            int currentVertex = queue.Dequeue();
            if (currentVertex == toVertex)
            {
                return true;
            }

            foreach (int neighbor in adjacencyList[currentVertex])
            {
                if (!visited.Contains(neighbor))
                {
                    queue.Enqueue(neighbor);
                    visited.Add(neighbor);
                }
            }
        }

        return false;
    }
}

