namespace CoreCommand.Command.Function
{
    public class AsyncCommandExecutor
    {
        private readonly Dictionary<Guid, Task> _commandTasks = new Dictionary<Guid, Task>();
        private readonly Dictionary<Guid, CancellationTokenSource> _cancellationTokenSources = new Dictionary<Guid, CancellationTokenSource>();

        public Guid RegisterCommand(Action command)
        {
            Guid commandId = Guid.NewGuid();
            _commandTasks.Add(commandId, Task.CompletedTask); // Initialize with a completed task
            return commandId;
        }

        public Task ExecuteCommandAsync(Guid commandId, Action command)
        {
            if (_commandTasks.ContainsKey(commandId))
            {
                var cancellationTokenSource = new CancellationTokenSource();
                _cancellationTokenSources[commandId] = cancellationTokenSource;

                var task = Task.Run(async () =>
                {
                    try
                    {
                        await Task.Delay(100, cancellationTokenSource.Token); // Simulate command execution
                        command.Invoke();
                    }
                    catch (OperationCanceledException)
                    {
                        // Handle cancellation
                    }
                }, cancellationTokenSource.Token);

                _commandTasks[commandId] = task;
                return task;
            }
            else
            {
                throw new ArgumentException("Command with the specified ID does not exist.");
            }
        }

        public bool CancelCommand(Guid commandId)
        {
            if (_cancellationTokenSources.ContainsKey(commandId))
            {
                _cancellationTokenSources[commandId].Cancel();
                return true;
            }
            return false;
        }
    }
}
