class CommandLineParser
{
    private Dictionary<string, Action<int, int>> commands;

    public CommandLineParser()
    {
        commands = new Dictionary<string, Action<int, int>>();
    }

    public void AddCommand(string command, Action<int, int> action)
    {
        commands[command] = action;
    }

    public void ParseAndExecute(string input)
    {
        string[] tokens = input.Split(' ');
        if (tokens[0] == "exit")
        {
            Environment.Exit(0);
        }
        else if (commands.ContainsKey(tokens[0]))
        {
            int value1, value2;
            if (tokens.Length >= 3 && int.TryParse(tokens[1], out value1) && int.TryParse(tokens[2], out value2))
            {
                commands[tokens[0]](value1, value2);
            }
            else
            {
                Console.WriteLine("Invalid command format. Please provide two integer values.");
            }
        }
        else
        {
            Console.WriteLine("Invalid command. Supported commands: add, subtract, multiply, divide, exit");
        }
    }

    static void Main(string[] args)
    {
        var parser = new CommandLineParser();

        parser.AddCommand("add", (a, b) => Console.WriteLine(a + b));
        parser.AddCommand("subtract", (a, b) => Console.WriteLine(a - b));
        parser.AddCommand("multiply", (a, b) => Console.WriteLine(a * b));
