    static void Main(string[] args)
    {
        int n = int.Parse(Console.ReadLine());
        // Call the function to calculate the nth Fibonacci number
        // Print the result
    }

    // Implement the efficient algorithm to calculate the nth Fibonacci number
    // Function signature: static int Fibonacci(int n)
