```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        int n = int.Parse(Console.ReadLine());
        int result = Fibonacci(n);
        Console.WriteLine(result);
    }

    static int Fibonacci(int n)
    {
        if (n <= 1)
        {
            return n;
        }

        int a = 0;
        int b = 1;
        for (int i = 2; i <= n; i++)
        {
            int temp = a + b;
            a = b;
            b = temp;
        }
        return b;
    }
}
```

The solution provides a program structure to calculate the nth Fibonacci number efficiently. The `Fibonacci` function uses an iterative approach to calculate the Fibonacci number, ensuring efficient performance for large values of n.

