// Custom middleware class for authentication and authorization
public class HeaderBasedAuthorizationMiddleware
{
    private readonly RequestDelegate _next;
    private readonly string _requiredHeader;

    public HeaderBasedAuthorizationMiddleware(RequestDelegate next, string requiredHeader)
    {
        _next = next;
        _requiredHeader = requiredHeader;
    }

    public async Task Invoke(HttpContext context)
    {
        if (context.Request.Headers.ContainsKey(_requiredHeader))
        {
            // Header is present, allow access to the next middleware in the pipeline
            await _next(context);
        }
        else
        {
            // Header is missing, return 403 Forbidden response
            context.Response.StatusCode = StatusCodes.Status403Forbidden;
        }
    }
}

public class Startup
{
    public Startup(IConfiguration configuration)
    {
        Configuration = configuration;
    }

    public IConfiguration Configuration { get; }

    public void ConfigureServices(IServiceCollection services)
    {
        services.AddCors();

        // Add the custom middleware to the request processing pipeline
        services.AddTransient<HeaderBasedAuthorizationMiddleware>();
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }
        else
        {
            app.UseExceptionHandler("/Home/Error");
            app.UseHsts();
        }

        // Use the custom middleware to enforce header-based authorization
        app.UseMiddleware<HeaderBasedAuthorizationMiddleware>("X-Custom-Header");

        // Other middleware and routing configuration
        app.UseHttpsRedirection();
        app.UseStaticFiles();
        app.UseRouting();
        app.UseAuthorization();
        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllerRoute(
                name: "default",
                pattern: "{controller=Home}/{action=Index}/{id?}");
        });
    }
}
```
In the solution, a custom middleware class `HeaderBasedAuthorizationMiddleware` is implemented to handle the authentication and authorization logic based on the presence of a specific header in the incoming HTTP request. The `Invoke` method of the middleware checks if the required header is present in the request. If the header is present, the middleware allows the request to proceed to the next middleware in the pipeline. If the header is missing, the middleware returns a 403 Forbidden response, denying access to the requested resource.

