public class ImageAverageHashCalculator
{
    private const int ImageWidth = 64; // Width for resizing the image
    private const int ImageHeight = 64; // Height for resizing the image
    private const int PixelCount = ImageWidth * ImageHeight; // Total number of pixels in the resized image

    public ulong ComputeAverageHash(Stream stream, IImageTransformer transformer)
    {
        if (stream == null)
            throw new ArgumentNullException(nameof(stream));
        if (transformer == null)
            throw new ArgumentNullException(nameof(transformer);

        var pixels = transformer.ConvertToGreyscaleAndResize(stream, ImageWidth, ImageHeight);

        // Calculate the average brightness of the pixels
        var averageBrightness = pixels.Sum(pixel => pixel) / PixelCount;

        // Generate the average hash based on the average brightness
        ulong averageHash = 0;
        for (int i = 0; i < PixelCount; i++)
        {
            if (pixels[i] > averageBrightness)
            {
                averageHash |= (1UL << i);
            }
        }

        return averageHash;
    }
}
