public class Aspect<T>
{
    public T Data { get; set; }
    public Aspect<T> Next { get; set; }
}

public class LinkedList<T>
{
    private Aspect<T> head;
    private Aspect<T> tail;
    private int count;

    public void AddFirst(T data)
    {
        Aspect<T> newAspect = new Aspect<T> { Data = data };
        if (head == null)
        {
            head = newAspect;
            tail = newAspect;
        }
        else
        {
            newAspect.Next = head;
            head = newAspect;
        }
        count++;
    }

    public void AddLast(T data)
    {
        Aspect<T> newAspect = new Aspect<T> { Data = data };
        if (tail == null)
        {
            head = newAspect;
            tail = newAspect;
        }
        else
        {
            tail.Next = newAspect;
            tail = newAspect;
        }
        count++;
    }

    public T RemoveFirst()
    {
        if (head == null)
        {
            throw new InvalidOperationException("The list is empty");
        }
        T data = head.Data;
        head = head.Next;
        count--;
        if (head == null)
        {
            tail = null;
        }
        return data;
    }

    public T RemoveLast()
    {
        if (tail == null)
        {
            throw new InvalidOperationException("The list is empty");
        }
        T data = tail.Data;
        if (head == tail)
        {
            head = null;
            tail = null;
        }
        else
        {
            Aspect<T> current = head;
            while (current.Next != tail)
            {
                current = current.Next;
            }
            current.Next = null;
            tail = current;
        }
        count--;
        return data;
    }

    public void PrintList()
    {
        Aspect<T> current = head;
        while (current != null)
        {
            Console.Write(current.Data + " ");
            current = current.Next;
        }
        Console.WriteLine();
    }

    public int Count
    {
        get { return count; }
    }

    public T First
    {
        get
        {
            if (head == null)
            {
                throw new InvalidOperationException("The list is empty");
            }
            return head.Data;
        }
    }

    public T Last
    {
        get
        {
            if (tail == null)
            {
                throw new InvalidOperationException("The list is empty");
            }
            return tail.Data;
        }
    }
}
