public List<List<int>> CombinationSum2(int[] candidates, int target) {
    Array.Sort(candidates);
    List<List<int>> result = new List<List<int>>();
    FindCombinations(candidates, target, 0, new List<int>(), result);
    return result;
}

private void FindCombinations(int[] candidates, int target, int start, List<int> current, List<List<int>> result) {
    if (target == 0) {
        result.Add(new List<int>(current));
        return;
    }

    for (int i = start; i < candidates.Length; i++) {
        if (i > start && candidates[i] == candidates[i - 1]) {
            continue;
        }
        if (candidates[i] > target) {
            break;
        }
        current.Add(candidates[i]);
        FindCombinations(candidates, target - candidates[i], i + 1, current, result);
        current.RemoveAt(current.Count - 1);
    }
}
