using System;
using System.IO;
using CommandLine;
using CommandLine.Text;

namespace FileCopyUtility
{
    public class CopyOptions
    {
        [Option('s', "source", Required = true, HelpText = "Path of the source file to be copied")]
        public string Source { get; set; }

        [Option('t', "target", Required = true, HelpText = "Directory where the source file should be copied")]
        public string Target { get; set; }

        [Option('o', "override", Required = false, Default = false, HelpText = "Override the target file if it already exists")]
        public bool Override { get; set; }
    }

    class Program
    {
        static void Main(string[] args)
        {
            Parser.Default.ParseArguments<CopyOptions>(args)
                .WithParsed(options => CopyFile(options))
                .WithNotParsed(errors => HandleParseErrors(errors));
        }

        static void CopyFile(CopyOptions options)
        {
            if (!File.Exists(options.Source))
            {
                Console.WriteLine($"Error: Source file '{options.Source}' does not exist.");
                return;
            }

            if (!Directory.Exists(options.Target))
            {
                Directory.CreateDirectory(options.Target);
            }

            string targetFilePath = Path.Combine(options.Target, Path.GetFileName(options.Source));

            if (File.Exists(targetFilePath))
            {
                if (options.Override)
                {
                    File.Copy(options.Source, targetFilePath, true);
                    Console.WriteLine($"File '{options.Source}' copied to '{targetFilePath}' (overwritten).");
                }
                else
                {
                    Console.Write($"File '{targetFilePath}' already exists. Do you want to override it? (Y/N): ");
                    if (Console.ReadLine().Trim().ToUpper() == "Y")
                    {
                        File.Copy(options.Source, targetFilePath, true);
                        Console.WriteLine($"File '{options.Source}' copied to '{targetFilePath}' (overwritten).");
                    }
                    else
                    {
                        Console.WriteLine("File copy operation aborted.");
                    }
                }
            }
            else
            {
                File.Copy(options.Source, targetFilePath);
                Console.WriteLine($"File '{options.Source}' copied to '{targetFilePath}'.");
            }
        }

        static void HandleParseErrors(System.Collections.Generic.IEnumerable<Error> errors)
        {
            var helpText = HelpText.AutoBuild(Parser.Default.Settings, Parser.Default.ParseArguments<CopyOptions>(new string[] { "--help" }));
            Console.WriteLine(helpText);
        }
    }
}
```
