```csharp
public static int CalculateWastedFood(int[] foodConsumed, int[] foodDistributed)
{
    if (foodConsumed.Length != foodDistributed.Length)
    {
        throw new ArgumentException("The number of students and distributed food amounts do not match.");
    }

    int totalWastedFood = 0;
    for (int i = 0; i < foodConsumed.Length; i++)
    {
        if (foodDistributed[i] > foodConsumed[i])
