using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class SimpleHttpClient
{
    private readonly HttpClient _httpClient;

    public SimpleHttpClient()
    {
        _httpClient = new HttpClient();
    }

    public async Task<T> GetAndDeserializeAsync<T>(string uri)
    {
        try
        {
            var request = new HttpRequestMessage(HttpMethod.Get, uri);
            var response = await _httpClient.SendAsync(request);

            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"The HTTP request failed with status code: {response.StatusCode}");
            }

            var str = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<T>(str);
        }
        catch (HttpRequestException ex)
        {
            // Handle HTTP request exceptions
            Console.WriteLine($"HTTP request failed: {ex.Message}");
            throw;
        }
        catch (JsonException ex)
        {
            // Handle JSON deserialization exceptions
            Console.WriteLine($"JSON deserialization failed: {ex.Message}");
            throw;
        }
    }
}
```

In the solution, the `GetAndDeserializeAsync<T>` method uses `HttpClient` to make an asynchronous GET request to the provided URI. It then checks the response status code and reads the response content as a string. Finally, it deserializes the string into an object of type `T` using JSON deserialization. The method also handles potential exceptions that may occur during the HTTP request or deserialization process and ensures non-blocking asynchronous behavior.

