public static int[] Decode7BitEncodedIntegers(byte[] data)
{
    List<int> decodedIntegers = new List<int>();
    int index = 0;

    while (index < data.Length)
    {
        int value = 0;
        int shift = 0;
        byte currentByte;

        do
        {
            currentByte = data[index++];
            value |= (currentByte & 0x7F) << shift;
            shift += 7;
        } while ((currentByte & 0x80) != 0);

        decodedIntegers.Add(value);
    }

    return decodedIntegers.ToArray();
}
```

