using System;
using System.Collections.Generic;
using System.Linq;

public class GrammarChecker<T>
{
    private readonly Dictionary<T, List<T[]>> rules;
    private readonly HashSet<T> startStates;
    private readonly HashSet<T> endStates;

    public GrammarChecker(Dictionary<T, List<T[]>> rules, HashSet<T> startStates, HashSet<T> endStates)
    {
        this.rules = rules;
        this.startStates = startStates;
        this.endStates = endStates;
    }

    public static GrammarChecker<char> BuildGrammarCheckerFrom(Dictionary<char, List<char[]>> grammarRules, string startStates, string endStates)
    {
        var rules = grammarRules.ToDictionary(entry => entry.Key, entry => entry.Value.Select(arr => arr.ToArray()).ToList());
        var start = new HashSet<char>(startStates);
        var end = new HashSet<char>(endStates);
        return new GrammarChecker<char>(rules, start, end);
    }

    public bool Check(IEnumerable<T> word)
    {
        var wordArray = word.ToArray();
        var n = wordArray.Length;
        var dp = new Dictionary<int, HashSet<T>>[n, n];

        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                dp[i, j] = new Dictionary<int, HashSet<T>>();
            }
        }

        for (int i = 0; i < n; i++)
        {
            foreach (var entry in rules)
            {
                if (entry.Value.Any(arr => arr.Length == 1 && arr[0].Equals(wordArray[i])))
                {
                    dp[i, i].Add(entry.Key, new HashSet<T> { wordArray[i] });
                }
            }
        }

        for (int len = 2; len <= n; len++)
        {
            for (int i = 0; i <= n - len; i++)
            {
                int j = i + len - 1;
                for (int k = i; k < j; k++)
                {
                    foreach (var entry in rules)
                    {
                        foreach (var arr in entry.Value)
                        {
                            if (arr.Length == 2)
                            {
                                if (dp[i, k].ContainsKey(arr[0]) && dp[k + 1, j].ContainsKey(arr[1]))
                                {
                                    if (!dp[i, j].ContainsKey(entry.Key))
                                    {
                                        dp[i, j].Add(entry.Key, new HashSet<T>());
                                    }
                                    dp[i, j][entry.Key].UnionWith(dp[i, k][arr[0]].SelectMany(x => dp[k + 1, j][arr[1]], (a, b) => (T)(dynamic)(a.ToString() + b.ToString())));
                                }
                            }
                        }
                    }
                }
            }
        }

        return startStates.Any(start => endStates.Any(end => dp[0, n - 1].ContainsKey(start) && dp[0, n - 1][start].Contains(end)));
    }
}
```

This solution provides a complete implementation of the `GrammarChecker` class, including the `BuildGrammarCheckerFrom` method to build the grammar checker from a set of grammar rules, start states, and end states. The `Check` method is also implemented to verify if a given word adheres to the grammar rules. The solution utilizes dynamic programming to efficiently check the validity of the input word based on the provided grammar rules.

