        if (data == null || !_props.Any())
        {
            throw new InvalidOperationException("Data or mapping not provided.");
        }

        var worksheet = new ExcelWorksheet();
        var headerRow = new List<string>();

        foreach (var propMap in _props)
        {
            headerRow.Add(propMap.Value.ColumnName ?? propMap.Key);
        }

        worksheet.AddRow(headerRow);

        foreach (var item in data)
        {
            var rowData = new List<object>();
            foreach (var propMap in _props)
            {
                var propValue = item.GetType().GetProperty(propMap.Key)?.GetValue(item);
                rowData.Add(propValue);
            }
            worksheet.AddRow(rowData);
        }

        return worksheet;
    }

    private string GetPropertyName<T>(Expression<Func<T, object>> property)
    {
