    {
        try
        {
            var acquired = _cache.StringSet(_lockKey, _lockValue, _lockExpiry, When.NotExists);
            return acquired;
        }
        catch (RedisConnectionException)
        {
            // Handle connection errors
            return false;
        }
        catch (RedisTimeoutException)
        {
            // Handle timeout errors
            return false;
        }
    }

    public void ReleaseLock()
    {
        _cache.KeyDelete(_lockKey);
    }
