using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;

public interface IComponentContainer
{
    T Resolve<T>();
    object Resolve(Type type);
}

public class ComponentContainer : IContainerBuilder, IComponentContainer
{
    private Dictionary<Type, Type> _typeMappings;
    private Dictionary<Type, object> _instanceMappings;

    public ComponentContainer()
    {
        _typeMappings = new Dictionary<Type, Type>();
        _instanceMappings = new Dictionary<Type, object>();
    }

    public IContainerBuilder RegisterAssembly(Assembly assembly)
    {
        var types = assembly.GetTypes().Where(t => t.IsClass);
        foreach (var type in types)
        {
            var interfaces = type.GetInterfaces();
            if (interfaces.Length > 0)
            {
                _typeMappings[interfaces.First()] = type;
            }
        }
        return this;
    }

    public IContainerBuilder RegisterAssemblies(params Assembly[] assemblies)
    {
        foreach (var assembly in assemblies)
        {
            RegisterAssembly(assembly);
        }
        return this;
    }

    public IContainerBuilder RegisterTypes(Type[] types)
    {
        foreach (var type in types)
        {
            var interfaces = type.GetInterfaces();
            if (interfaces.Length > 0)
            {
                _typeMappings[interfaces.First()] = type;
            }
        }
        return this;
    }

    public IContainerBuilder RegisterInstance(object obj, Type asType)
    {
        _instanceMappings[asType] = obj;
        return this;
    }

    public IComponentContainer Build()
    {
        return this;
    }

    public T Resolve<T>()
    {
        return (T)Resolve(typeof(T));
    }

    public object Resolve(Type type)
    {
        if (_instanceMappings.ContainsKey(type))
        {
            return _instanceMappings[type];
        }
        else
        {
            var concreteType = _typeMappings[type];
            var constructor = concreteType.GetConstructors().First();
            var parameters = constructor.GetParameters().Select(p => Resolve(p.ParameterType)).ToArray();
            return Activator.CreateInstance(concreteType, parameters);
        }
    }
}
```

This solution provides a `ComponentContainer` class that implements the `IContainerBuilder` interface and provides the necessary functionality to register and build a component container for managing object dependencies. The `RegisterAssembly`, `RegisterAssemblies`, `RegisterTypes`, and `RegisterInstance` methods allow for registering assemblies, types, and instances, and the `Build` method builds the component container. The `Resolve` method resolves dependencies and returns the requested object.

