You are tasked with implementing a simple dependency injection framework in PascalABC.NET. The framework should allow the registration of services and their dependencies, and provide a way to resolve these dependencies when needed.

Your task is to complete the implementation of the `ServicesInjector` class that implements the `IServicesInjector` interface. The interface has the following methods:
1. `RegisterService<TService, TImplementation>()`: Registers a service and its implementation.
2. `RegisterSingleton<TService, TImplementation>()`: Registers a service and its implementation as a singleton.
3. `ResolveService<TService>()`: Resolves and returns an instance of the requested service, along with its dependencies.

The `ServicesInjector` class should maintain a dictionary of registered services and their implementations. When resolving a service, the class should instantiate the service and resolve its dependencies recursively.

You should also handle the case where a service has already been registered, and provide the ability to register services as singletons, meaning that the same instance should be returned every time the service is resolved.

Complete the implementation of the `ServicesInjector` class to fulfill the requirements of the `IServicesInjector` interface.

```csharp
using System;
using System.Collections.Generic;

public interface IServicesInjector
{
    void RegisterService<TService, TImplementation>() where TImplementation : TService;
    void RegisterSingleton<TService, TImplementation>() where TImplementation : TService;
    TService ResolveService<TService>();
}

public class ServicesInjector : IServicesInjector
{
    private readonly Dictionary<Type, Type> serviceImplementations = new Dictionary<Type, Type>();
    private readonly Dictionary<Type, object> singletonInstances = new Dictionary<Type, object>();

    public void RegisterService<TService, TImplementation>() where TImplementation : TService
    {
        Type serviceType = typeof(TService);
        Type implementationType = typeof(TImplementation);

        if (serviceImplementations.ContainsKey(serviceType))
        {
            throw new InvalidOperationException($"Service {serviceType.Name} is already registered.");
        }

        serviceImplementations[serviceType] = implementationType;
    }

    public void RegisterSingleton<TService, TImplementation>() where TImplementation : TService
    {
        RegisterService<TService, TImplementation>();
        singletonInstances[typeof(TService)] = null;
    }

    public TService ResolveService<TService>()
    {
        Type serviceType = typeof(TService);

        if (singletonInstances.ContainsKey(serviceType) && singletonInstances[serviceType] != null)
        {
            return (TService)singletonInstances[serviceType];
        }

        if (!serviceImplementations.ContainsKey(serviceType))
        {
            throw new InvalidOperationException($"Service {serviceType.Name} is not registered.");
        }

        Type implementationType = serviceImplementations[serviceType];
        var instance = (TService)Activator.CreateInstance(implementationType);

        if (singletonInstances.ContainsKey(serviceType))
        {
            singletonInstances[serviceType] = instance;
        }

        return instance;
    }
}
```

