```csharp
using System;
using System.Collections.Concurrent;

public class KeyValueStore
{
    private ConcurrentDictionary<string, object>[] innerData;
    private KeyValuePair<string, object>[][] writeBatch;

    public KeyValueStore(int size)
    {
        innerData = new ConcurrentDictionary<string, object>[size];
        writeBatch = new KeyValuePair<string, object>[size][];

        for (int i = 0; i < size; i++)
        {
            innerData[i] = new ConcurrentDictionary<string, object>();
            writeBatch[i] = new KeyValuePair<string, object>[0];
        }
    }

    public void Add(string key, object value)
    {
        int index = GetIndex(key);
        Array.Resize(ref writeBatch[index], writeBatch[index].Length + 1);
        writeBatch[index][writeBatch[index].Length - 1] = new KeyValuePair<string, object>(key, value);
    }

    public void Update(string key, object value)
    {
        int index = GetIndex(key);
        for (int i = 0; i < writeBatch[index].Length; i++)
        {
            if (writeBatch[index][i].Key == key)
            {
                writeBatch[index][i] = new KeyValuePair<string, object>(key, value);
                return;
            }
        }
        Add(key, value);
    }

    public void Remove(string key)
    {
        int index = GetIndex(key);
        writeBatch[index] = Array.FindAll(writeBatch[index], pair => pair.Key != key);
    }

    public void Commit()
    {
        for (int i = 0; i < writeBatch.Length; i++)
        {
            foreach (var pair in writeBatch[i])
            {
                if (pair.Value is null)
                {
                    innerData[i].TryRemove(pair.Key, out _);
                }
                else
                {
                    innerData[i][pair.Key] = pair.Value;
                }
            }
        }
    }

    private int GetIndex(string key)
    {
        return Math.Abs(key.GetHashCode()) % innerData.Length;
    }
}
