public enum ERecurFromType
{
    Daily,
    Weekly,
    Monthly
}

public class RecurringEvent
{
    private DateTime _startDate;
    private DateTime _endDate;

    public ERecurFromType RecurFromType { get; set; }
    public int MaxRecurrenceCount { get; set; }

    public RecurringEvent(DateTime startDate, DateTime endDate, ERecurFromType recurFromType, int maxRecurrenceCount)
    {
        _startDate = startDate;
        _endDate = endDate;
        RecurFromType = recurFromType;
        MaxRecurrenceCount = maxRecurrenceCount;
    }

    public DateTime? CalculateNextOccurrence(DateTime currentDate)
    {
        if (currentDate < _startDate || currentDate > _endDate)
            return null;

        int recurrenceCount = 0;
        DateTime nextOccurrence = _startDate;

        while (nextOccurrence <= currentDate)
        {
            switch (RecurFromType)
            {
                case ERecurFromType.Daily:
                    nextOccurrence = nextOccurrence.AddDays(1);
                    break;
                case ERecurFromType.Weekly:
                    nextOccurrence = nextOccurrence.AddDays(7);
                    break;
                case ERecurFromType.Monthly:
                    nextOccurrence = nextOccurrence.AddMonths(1);
                    break;
            }

            if (nextOccurrence > _endDate)
                return null;

            recurrenceCount++;
            if (recurrenceCount >= MaxRecurrenceCount)
                return null;
        }

        return nextOccurrence;
    }

    public bool IsEventOngoing(DateTime date)
    {
        return date >= _startDate && date <= _endDate;
    }
}
```
