            group1.AddEmployee(individualEmployee1);
            group1.AddEmployee(individualEmployee2);

            // Create another individual employee
            Employee individualEmployee3 = new Employee("Bob");

            // Create another group of employees
            GroupEmployee group2 = new GroupEmployee("Construction Team 2");
