    public static void RetryAssert(int retryInterval, int retryCount, string failureMessage, Func<bool> assertion)
    {
        var count = 0;
        while (count < retryCount)
        {
            if (assertion())
            {
                return; // Assertion succeeded, exit the method
            }
            Thread.Sleep(retryInterval); // Wait for the specified interval before the next retry
            count++;
        }
