    public MethodInfo Locate(TypeInfo type, TypeInfo elementType)
    {
        // Get all methods of the type
        MethodInfo[] methods = type.GetMethods();

        // Iterate through the methods to find the one that can locate the elementType
        foreach (MethodInfo method in methods)
        {
            // Check if the method returns the elementType
            if (method.ReturnType == elementType)
            {
                // Check if the method takes the type as a parameter
                ParameterInfo[] parameters = method.GetParameters();
                foreach (ParameterInfo parameter in parameters)
                {
                    if (parameter.ParameterType == type)
                    {
                        // Found the method that can locate the elementType within the given type
                        return method;
                    }
                }
            }
        }

        // If no suitable method is found, return null
        return null;
    }
}
