public class CustomRNG
{
    private uint[] _State = new uint[1];  // Internal state array

    /// <param name="seed">
    ///     RNG seed.
    /// </param>
    public void SetSeed(uint seed)
    {
        this._State[0] = (seed & 0x1fffffffu) + 1156979152u;  // Accepts 29 seed-bits.
    }

    /// <summary>
    ///     Generates the next pseudo-random number using the LCG algorithm.
    /// </summary>
    /// <returns>
    ///     The next pseudo-random number.
    /// </returns>
    public uint GetNextRandom()
    {
        const uint a = 1664525u;  // Multiplier
        const uint c = 1013904223u;  // Increment
        const uint m = 0x100000000u;  // Modulus (2^32)

        _State[0] = (a * _State[0] + c) % m;  // LCG algorithm

        return _State[0];
    }
}
```

