```csharp
using System;
using System.Collections.Generic;
using System.Reflection;

public class TypeMemberEnumerator
{
    public List<string> EnumerateTypeMembers(Type type)
    {
        List<string> memberNames = new List<string>();

        try
        {
            // Get all public fields, properties, and methods of the type
            FieldInfo[] fields = type.GetFields(BindingFlags.Public | BindingFlags.Instance);
            PropertyInfo[] properties = type.GetProperties(BindingFlags.Public | BindingFlags.Instance);
            MethodInfo[] methods = type.GetMethods(BindingFlags.Public | BindingFlags.Instance);

            // Add the names of the fields, properties, and methods to the list
            foreach (var field in fields)
            {
                memberNames.Add(field.Name);
            }
            foreach (var property in properties)
            {
                memberNames.Add(property.Name);
            }
            foreach (var method in methods)
            {
                memberNames.Add(method.Name);
            }
        }
        catch (Exception ex)
        {
            // Handle any exceptions that may occur during enumeration
            Console.WriteLine("An error occurred while enumerating type members: " + ex.Message);
        }

        return memberNames;
    }
}
```

This solution uses reflection to obtain the fields, properties, and methods of the given type. It then adds the names of these members to a list, which is returned as the result. The solution also includes exception handling to catch and handle any potential errors during the enumeration process.

