using System;
using System.Collections.Generic;

public class UriParser
{
    public static (string, Dictionary<string, string>) ExtractFileNameAndQuery(string uriString)
    {
        Uri uri;
        if (Uri.TryCreate(uriString, UriKind.RelativeOrAbsolute, out uri))
        {
            string fileName = GetFileName(uri);
            Dictionary<string, string> queryParameters = GetQueryParameters(uri);
            return (fileName, queryParameters);
        }
        else
        {
            throw new ArgumentException("Invalid URI format");
        }
    }

    private static string GetFileName(Uri uri)
    {
        string path = uri.IsAbsoluteUri ? uri.AbsolutePath : uri.OriginalString;
        int lastSlashIndex = path.LastIndexOf('/');
        return path.Substring(lastSlashIndex + 1);
    }

    private static Dictionary<string, string> GetQueryParameters(Uri uri)
    {
        Dictionary<string, string> queryParameters = new Dictionary<string, string>();
        string query = uri.Query.TrimStart('?');
        if (!string.IsNullOrEmpty(query))
        {
            string[] queryParams = query.Split('&');
            foreach (string param in queryParams)
            {
                string[] keyValue = param.Split('=');
                if (keyValue.Length == 2)
                {
                    queryParameters[keyValue[0]] = keyValue[1];
                }
            }
        }
        return queryParameters;
    }
}
```

