    private int length;
    private dynamic[] values;

    public bool IsStatic { get; private set; }

    public DynamicArray(bool isStatic, int initialCapacity)
    {
        length = 0;
        values = new dynamic[initialCapacity];
        IsStatic = isStatic;
    }

    public void AddElement(dynamic element)
    {
        if (length == values.Length)
        {
            ResizeArray(values.Length * 2);
        }
        values[length] = element;
        length++;
    }

    public void RemoveElement()
    {
        if (length > 0)
        {
            length--;
            values[length] = null;
            if (length < values.Length / 2)
            {
                ResizeArray(values.Length / 2);
            }
        }
    }

    private void ResizeArray(int newCapacity)
    {
        dynamic[] newArray = new dynamic[newCapacity];
        Array.Copy(values, newArray, length);
        values = newArray;
    }
}
