public class Magma
{
    public static bool IsPrime(int number)
    {
        if (number <= 1) return false;
        if (number == 2) return true;
        if (number % 2 == 0) return false;

        int boundary = (int)Math.Floor(Math.Sqrt(number));

        for (int i = 3; i <= boundary; i += 2)
        {
            if (number % i == 0) return false;
        }

        return true;
    }
}

public class PrimeNumberCounter
{
    private int count;
    private object syncRoot = new object();

    public int CountPrimeNumbers(int start, int end)
    {
        count = 0;

        int[] range = new int[end - start + 1];
        for (int i = 0; i < range.Length; i++)
        {
            range[i] = start + i;
        }

        Parallel.ForEach(range, new ParallelOptions
        {
            MaxDegreeOfParallelism = Environment.ProcessorCount,
            CancellationToken = new CancellationToken()
        }, TestIfPrime);

        return count;
    }

    private void TestIfPrime(int j)
    {
        if (Magma.IsPrime(j))
        {
            lock (syncRoot)
            {
                count++;
            }
        }
    }
}

public class Program
{
    public static void Main()
    {
        PrimeNumberCounter counter = new PrimeNumberCounter();
        int startRange = 1;
        int endRange = 100;
        int primeCount = counter.CountPrimeNumbers(startRange, endRange);
        Console.WriteLine($"Number of prime numbers between {startRange} and {endRange}: {primeCount}");
    }
}
