public class DegradationProfile : IDegradationProfile
{
    private List<double> historicalData;

    public DegradationProfile(List<double> historicalData)
    {
        this.historicalData = historicalData;
    }

    public double CalculateDegradationRate()
    {
        // Simple linear regression to calculate the degradation rate
        double sumX = 0;
        double sumY = 0;
        double sumXY = 0;
        double sumXSquare = 0;
        int n = historicalData.Count;

        for (int i = 0; i < n; i++)
        {
            sumX += i;
            sumY += historicalData[i];
            sumXY += i * historicalData[i];
            sumXSquare += i * i;
        }

        double slope = (n * sumXY - sumX * sumY) / (n * sumXSquare - sumX * sumX);
        return slope;
    }

    public double EstimatePerformance(double time)
    {
        double degradationRate = CalculateDegradationRate();
        return historicalData[0] - degradationRate * time; // Simple linear degradation model
    }
}
```

