using System;
using System.Collections.Concurrent;
using System.Threading;
using NUnit.Framework;

public class BackgroundTaskProcessor
{
    private readonly ConcurrentQueue<Action> taskQueue = new ConcurrentQueue<Action>();
    private readonly AutoResetEvent taskEvent = new AutoResetEvent(false);
    private readonly Thread workerThread;

    public BackgroundTaskProcessor()
    {
        workerThread = new Thread(Run);
        workerThread.Start();
    }

    public void EnqueueTask(Action task)
    {
        taskQueue.Enqueue(task);
        taskEvent.Set();
    }

    private void Run()
    {
        while (true)
        {
            if (taskQueue.TryDequeue(out var task))
            {
                task();
            }
            else
            {
                taskEvent.WaitOne();
            }
        }
    }

    public void Dispose()
    {
        taskEvent.Set();
        workerThread.Join();
    }
}

