public class LabelLayoutManager
{
    public int MarginX { get; set; }
    public int MarginY { get; set; }

    public (int width, int height) CalculateTotalSize(List<(int x, int y, int textLength)> labels)
    {
        int maxWidth = 0;
        int totalHeight = 0;

        foreach (var label in labels)
        {
            int labelWidth = label.textLength + (2 * MarginX); // Account for text length and horizontal margin
            int labelHeight = 13 + (2 * MarginY); // Assuming a standard label height of 13 and accounting for vertical margin

            if (label.x + labelWidth > maxWidth)
            {
                maxWidth = label.x + labelWidth;
            }

            if (label.y + labelHeight > totalHeight)
            {
                totalHeight = label.y + labelHeight;
            }
        }

        return (maxWidth, totalHeight);
    }
}
