using System;
using System.Collections.Generic;

public class MaxInRangeQueue
{
    private Queue<int> queue;
    private SortedDictionary<int, int> maxCountMap;

    public MaxInRangeQueue()
    {
        queue = new Queue<int>();
        maxCountMap = new SortedDictionary<int, int>();
    }

    public void Enqueue(int element)
    {
        queue.Enqueue(element);
        if (maxCountMap.ContainsKey(element))
        {
            maxCountMap[element]++;
        }
        else
        {
            maxCountMap[element] = 1;
        }
    }

    public int Dequeue()
    {
        int element = queue.Dequeue();
        if (maxCountMap[element] == 1)
        {
            maxCountMap.Remove(element);
        }
        else
        {
            maxCountMap[element]--;
        }
        return element;
    }

    public int MaxInRange(int start, int end)
    {
        int[] elements = queue.ToArray();
        int maxInRange = int.MinValue;
        for (int i = start; i <= end; i++)
        {
            maxInRange = Math.Max(maxInRange, elements[i]);
        }
        return maxInRange;
    }
}
```

