public class SchemaTableBuilder
{
    public static DataTable BuildSchemaTable((string fieldName, Type dataType)[] fieldMappings, SchemaMappingColumn[] additionColumns = null)
    {
        List<SchemaMappingColumn> columns = new List<SchemaMappingColumn>();

        foreach (var fieldMapper in fieldMappings)
        {
            Type dataType = fieldMapper.dataType.GetNullableBaseType();
            bool allowDbNull = !dataType.IsValueType;

            if (dataType.IsEnum)
                dataType = typeof(int);

            var column = new SchemaMappingColumn(fieldMapper.fieldName, dataType, allowDbNull);
            columns.Add(column);
        }

        if (additionColumns != null)
            columns.AddRange(additionColumns);

        return BuildSchemaTable(columns.ToArray());
    }

    private static DataTable BuildSchemaTable(SchemaMappingColumn[] columns)
    {
        DataTable schemaTable = new DataTable();

        foreach (var column in columns)
        {
            schemaTable.Columns.Add(column.FieldName, column.DataType).AllowDBNull = column.AllowDbNull;
        }

        return schemaTable;
    }
}
