using Gurobi;

int nSubsets = 5; // Number of subsets
int nItems = 10; // Total number of items

// Create a new model
GRBModel model = new GRBModel(new GRBEnv());

// Set global sense for ALL objectives
model.ModelSense = GRB.MAXIMIZE;

// Limit how many solutions to collect
model.Parameters.PoolSolutions = 100;

// Set and configure i-th objective
for (int i = 0; i < nSubsets; i++) {
    string vname = string.Format("Set{0}", i);
    GRBLinExpr objn = new GRBLinExpr();

    // Define decision variables for items in the subset
    GRBVar[] x = new GRBVar[nItems];
    for (int j = 0; j < nItems; j++) {
        x[j] = model.AddVar(0.0, 1.0, 0.0, GRB.BINARY, vname + "_Item" + j);
    }

    // Define the objective function for subset i (maximize profit)
    GRBLinExpr profitExpr = new GRBLinExpr();
    for (int j = 0; j < nItems; j++) {
        profitExpr.AddTerm(profit[i, j], x[j]);
    }
    model.SetObjective(profitExpr, GRB.MAXIMIZE);

    // Add capacity constraint for subset i
    GRBLinExpr weightExpr = new GRBLinExpr();
    for (int j = 0; j < nItems; j++) {
        weightExpr.AddTerm(weight[i, j], x[j]);
    }
    model.AddConstr(weightExpr <= capacity[i], "Capacity_" + vname);
}

// Optimize the model
model.Optimize();

// Collect multiple solutions for analysis
for (int s = 0; s < model.SolCount; s++) {
    model.Parameters.SolutionNumber = s;
    Console.WriteLine("Solution " + s + ":");
    for (int i = 0; i < nSubsets; i++) {
        string vname = string.Format("Set{0}", i);
        Console.Write(vname + ": ");
        for (int j = 0; j < nItems; j++) {
            Console.Write(x[j].Get(GRB.DoubleAttr.Xn) + " ");
        }
        Console.WriteLine();
    }
}
