                        return ConnectionStatus.ReceivedInitiation;
                    else if (currentStatus == ConnectionStatus.InitiatedConnect)
                        return ConnectionStatus.RespondedConnect;
                    break;
                case "ApprovalReceived":
                    if (currentStatus == ConnectionStatus.ReceivedInitiation)
                        return ConnectionStatus.RespondedAwaitingApproval;
                    break;
                case "ConnectionEstablished":
                    if (currentStatus == ConnectionStatus.RespondedAwaitingApproval)
                        return ConnectionStatus.Connected;
                    break;
                case "DisconnectInitiationReceived":
                    if (currentStatus == ConnectionStatus.Connected)
                        return ConnectionStatus.Disconnecting;
                    break;
                case "Disconnected":
                    if (currentStatus == ConnectionStatus.Disconnecting)
                        return ConnectionStatus.Disconnected;
                    break;
            }
            return currentStatus;
        }
