```csharp
using System;
using System.Collections.Generic;
using System.Linq.Expressions;

public class SerializationGenerator
{
    public delegate void SerializeDelegate(object obj, IWriter writer);

    public static SerializeDelegate GenerateSerializationFunction(List<Case> cases)
    {
        var valueParameter = Expression.Parameter(typeof(object), "value");
        var writerParameter = Expression.Parameter(typeof(IWriter), "writer");

        var switchCases = cases.Select(c => Expression.SwitchCase(
            Expression.Block(
                c.SerializationLogic.Type,
                c.SerializationLogic,
                Expression.Break(Expression.Label("End"))
            ),
            Expression.TypeEqual(valueParameter, c.Type)
        )).ToList();

        var switchExpression = Expression.Switch(valueParameter,
            Expression.Throw(Expression.Constant(new InvalidOperationException())),
            switchCases.ToArray());

        var lambdaExpression = Expression.Lambda<SerializeDelegate>(switchExpression, writerParameter, valueParameter);
        return lambdaExpression.Compile();
    }
}

public interface IWriter
{
    void Write(string value);
}

public class Case
{
    public Type Type { get; set; }
    public Expression SerializationLogic { get; set; }
}
```

