namespace MessageVault {
    public class MessageVault {
        private readonly Dictionary<Guid, byte[]> messageStore = new Dictionary<Guid, byte[]>();

        public async Task<Guid> StoreMessageAsync(string message) {
            byte[] encryptedMessage = EncryptMessage(message);
            Guid messageId = Guid.NewGuid();
            messageStore.Add(messageId, encryptedMessage);
            return messageId;
        }

        public async Task<string> RetrieveMessageAsync(Guid messageId) {
