using System;
using System.Collections.Generic;

public class Event
{
    public DateTime Until { get; set; }
}

public class Program
{
    public static Dictionary<DateTime, int> CalculateDaysUntilEvent(Event[] events)
    {
        Dictionary<DateTime, int> daysUntilEvent = new Dictionary<DateTime, int>();

        foreach (var e in events)
        {
            TimeSpan timeUntilEvent = e.Until - DateTime.Today;
            int days = (int)timeUntilEvent.TotalDays;
            daysUntilEvent.Add(e.Until, days);
        }

        return daysUntilEvent;
    }

