using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;

public class BinarySerializer
{
    public static byte[] Serialize(Context context)
    {
        using (MemoryStream stream = new MemoryStream())
        using (BinaryWriter writer = new BinaryWriter(stream))
        {
            PropertyInfo[] properties = typeof(Context).GetProperties();
            foreach (var property in properties)
            {
                var attribute = property.GetCustomAttribute<BinaryFormatAttribute>();
                if (attribute != null)
                {
                    if (property.PropertyType == typeof(List<UInt32>))
                    {
                        var value = (List<UInt32>)property.GetValue(context);
                        writer.Write(value.Count);
                        foreach (var item in value)
                        {
                            writer.Write(item);
                        }
                    }
                }
            }
            return stream.ToArray();
        }
    }

    public static Context Deserialize(byte[] data)
    {
        Context context = new Context();
        using (MemoryStream stream = new MemoryStream(data))
        using (BinaryReader reader = new BinaryReader(stream))
        {
            PropertyInfo[] properties = typeof(Context).GetProperties();
            foreach (var property in properties)
            {
                var attribute = property.GetCustomAttribute<BinaryFormatAttribute>();
                if (attribute != null)
                {
                    if (property.PropertyType == typeof(List<UInt32>))
                    {
                        int count = reader.ReadInt32();
                        List<UInt32> value = new List<UInt32>();
                        for (int i = 0; i < count; i++)
                        {
                            value.Add(reader.ReadUInt32());
                        }
                        property.SetValue(context, value);
                    }
                }
            }
        }
        return context;
    }
}

[AttributeUsage(AttributeTargets.Property)]
public class BinaryFormatAttribute : Attribute
{
}

public class Context
{
    [BinaryFormat]
    public List<UInt32> Children { get; set; }
}
```

