```csharp
using System;

public class IntensityModel
{
    private const int NumComponents = 3; // y, cb, cr
    private const int NumIntensityLevels = 256;

    private Array3<Array256<byte>> IntensityIntervalLowerBound;
    private Array3<Array256<byte>> IntensityIntervalUpperBound;
    private Array3<Array256<double>> ModelValues;

    public IntensityModel()
    {
        IntensityIntervalLowerBound = new Array3<Array256<byte>>(NumComponents, NumIntensityLevels);
        IntensityIntervalUpperBound = new Array3<Array256<byte>>(NumComponents, NumIntensityLevels);
        ModelValues = new Array3<Array256<double>>(NumComponents, NumIntensityLevels);
    }

    public void SetIntensityIntervalBounds(int componentIndex, int intensityLevel, byte lowerBound, byte upperBound)
    {
        if (componentIndex < 0 || componentIndex >= NumComponents)
            throw new ArgumentOutOfRangeException(nameof(componentIndex), "Invalid component index");

        if (intensityLevel < 0 || intensityLevel >= NumIntensityLevels)
            throw new ArgumentOutOfRangeException(nameof(intensityLevel), "Invalid intensity level");

        IntensityIntervalLowerBound[componentIndex, intensityLevel] = lowerBound;
        IntensityIntervalUpperBound[componentIndex, intensityLevel] = upperBound;
    }

    public void SetModelValues(int componentIndex, int intensityLevel, double[] values)
    {
        if (componentIndex < 0 || componentIndex >= NumComponents)
            throw new ArgumentOutOfRangeException(nameof(componentIndex), "Invalid component index");

        if (intensityLevel < 0 || intensityLevel >= NumIntensityLevels)
            throw new ArgumentOutOfRangeException(nameof(intensityLevel), "Invalid intensity level");

        if (values.Length != NumComponents)
            throw new ArgumentException("Invalid number of model values");

        for (int i = 0; i < NumComponents; i++)
        {
            ModelValues[componentIndex, intensityLevel, i] = values[i];
        }
    }

    public double[] GetModelValues(int componentIndex, int intensityLevel)
    {
        if (componentIndex < 0 || componentIndex >= NumComponents)
            throw new ArgumentOutOfRangeException(nameof(componentIndex), "Invalid component index");

        if (intensityLevel < 0 || intensityLevel >= NumIntensityLevels)
            throw new ArgumentOutOfRangeException(nameof(intensityLevel), "Invalid intensity level");

        double[] values = new double[NumComponents];
        for (int i = 0; i < NumComponents; i++)
        {
            values[i] = ModelValues[componentIndex, intensityLevel, i];
        }
        return values;
    }
}

