                if (grid[newRow, newCol] == '.')
                {
                    grid[playerRow, playerCol] = '.';
                    playerRow = newRow;
                    playerCol = newCol;
                    grid[playerRow, playerCol] = 'P'; // 'P' represents the player
                }
                else if (grid[newRow, newCol] == 'T')
                {
                    grid[playerRow, playerCol] = '.';
                    playerRow = newRow;
                    playerCol = newCol;
                    grid[playerRow, playerCol] = 'P';
