public class MinStack
{
    private StackNode _top;

    public MinStack()
    {
        _top = null;
    }

    public void Push(int x)
    {
        if (_top == null)
        {
            _top = new StackNode(x, x, null);
        }
        else
        {
            int min = Math.Min(x, _top.Min);
            _top = new StackNode(x, min, _top);
        }
    }

    public void Pop()
    {
        _top = _top.Next;
    }

    public int Top()
    {
        return _top.Value;
    }

    public int GetMin()
    {
        return _top.Min;
    }

    private class StackNode
    {
        public int Value { get; }
        public int Min { get; }
        public StackNode Next { get; }

        public StackNode(int value, int min, StackNode next)
        {
            Value = value;
            Min = min;
            Next = next;
        }
    }
}
```

This implementation uses a custom `StackNode` class to keep track of the minimum value at each node. When pushing a new element, the minimum value is updated accordingly. This allows retrieving the minimum element in constant time. The space complexity is O(n) where n is the number of elements in the stack. All operations have a time complexity of O(1).

