public static unsafe int SumArray(int[] array)
{
    ReadOnlySpan<int> span = new ReadOnlySpan<int>(array);
    ReadOnlySpan<byte> bytes = MemoryMarshal.AsBytes(span);
    fixed (byte* ptr = bytes)
    {
        int* intPtr = (int*)ptr;
        int sum = 0;
