using Azure.Messaging.ServiceBus;

public class AzureServiceBusMessaging
{
    private ServiceBusClient _serviceBusClient;

    public AzureServiceBusMessaging(string connectionString)
    {
        _serviceBusClient = new ServiceBusClient(connectionString);
    }

    public async Task SendMessageToQueue(string queueName, string message)
    {
        ServiceBusSender sender = _serviceBusClient.CreateSender(queueName);
        ServiceBusMessage serviceBusMessage = new ServiceBusMessage(Encoding.UTF8.GetBytes(message));
        await sender.SendMessageAsync(serviceBusMessage);
        await sender.DisposeAsync();
    }

    public async Task<string> ReceiveMessageFromQueue(string queueName)
    {
        ServiceBusProcessor processor = _serviceBusClient.CreateProcessor(queueName, new ServiceBusProcessorOptions());
        string messageBody = string.Empty;

        processor.ProcessMessageAsync += args =>
        {
            messageBody = Encoding.UTF8.GetString(args.Message.Body);
            return Task.CompletedTask;
        };

        processor.ProcessErrorAsync += args =>
        {
            Console.WriteLine(args.Exception.ToString());
            return Task.CompletedTask;
        };

        processor.StartProcessing();
        await Task.Delay(5000); // Simulate processing time
        await processor.StopProcessingAsync();

        return messageBody;
    }
}
