public class Claim
{
    public int x { get; set; }
    public int y { get; set; }
    public int x2 { get; set; }
    public int y2 { get; set; }
}

public int CalculateOverlapArea(List<Claim> claims)
{
    int minX = claims.Min(a => a.x);
    int minY = claims.Min(a => a.y);
    int maxX = claims.Max(a => a.x2);
    int maxY = claims.Max(a => a.y2);

    int[,] grid = new int[maxX, maxY];

    foreach (var claim in claims)
    {
        for (int i = claim.x; i < claim.x2; i++)
        {
            for (int j = claim.y; j < claim.y2; j++)
            {
                grid[i, j]++;
            }
        }
    }

    int overlapArea = 0;
    for (int i = minX; i < maxX; i++)
    {
        for (int j = minY; j < maxY; j++)
        {
            if (grid[i, j] > 1)
            {
                overlapArea++;
            }
        }
    }

    return overlapArea;
}
```

The `CalculateOverlapArea` function takes in a list of claims and calculates the total area of overlap among them. It first determines the minimum and maximum coordinates to create a grid. Then, it iterates through each claim to mark the grid cells covered by the claims. Finally, it counts the cells with more than one claim, representing the overlapped area.

