public class XlsxSpreadsheetDocument
{
    private SpreadsheetDocument _spreadsheetDocument;

    public XlsxSpreadsheetDocument(SpreadsheetDocument spreadsheetDocument)
    {
        _spreadsheetDocument = spreadsheetDocument ?? throw new ArgumentNullException(nameof(spreadsheetDocument));
    }

    public void InitializeWorkbook()
    {
        // Implementation for initializing the workbook
    }

    public void AddWorksheet(string name)
    {
        // Implementation for adding a new worksheet
        WorkbookPart workbookPart = _spreadsheetDocument.WorkbookPart;
        WorksheetPart newWorksheetPart = workbookPart.AddNewPart<WorksheetPart>();
        newWorksheetPart.Worksheet = new Worksheet(new SheetData());
        Sheets sheets = workbookPart.Workbook.GetFirstChild<Sheets>();
        string relationshipId = workbookPart.GetIdOfPart(newWorksheetPart);

        uint sheetId = 1;
        if (sheets.Elements<Sheet>().Any())
        {
            sheetId = sheets.Elements<Sheet>().Select(s => s.SheetId.Value).Max() + 1;
        }

        Sheet sheet = new Sheet() { Id = relationshipId, SheetId = sheetId, Name = name };
        sheets.Append(sheet);
    }

    public void SetCellValue(string worksheetName, string cellAddress, object value)
    {
        // Implementation for setting cell value
        WorksheetPart worksheetPart = GetWorksheetPartByName(worksheetName);
        Cell cell = InsertCellInWorksheet(cellAddress, worksheetPart.Worksheet);
        cell.CellValue = new CellValue(value.ToString());
        cell.DataType = CellValues.String;
    }

    public void Save(string filePath)
    {
        // Implementation for saving the workbook
        _spreadsheetDocument.SaveAs(filePath);
    }

    private WorksheetPart GetWorksheetPartByName(string sheetName)
    {
        WorkbookPart workbookPart = _spreadsheetDocument.WorkbookPart;
        Sheet sheet = workbookPart.Workbook.Descendants<Sheet>().FirstOrDefault(s => s.Name == sheetName);
        if (sheet == null)
        {
            throw new ArgumentException($"Worksheet '{sheetName}' not found.");
        }
        return (WorksheetPart)workbookPart.GetPartById(sheet.Id);
    }

    private Cell InsertCellInWorksheet(string cellAddress, Worksheet worksheet)
    {
        SheetData sheetData = worksheet.GetFirstChild<SheetData>();
        Row row;
        uint rowIndex = GetRowIndex(cellAddress);
        if (sheetData.Elements<Row>().Any(r => r.RowIndex == rowIndex))
        {
            row = sheetData.Elements<Row>().First(r => r.RowIndex == rowIndex);
        }
        else
        {
            row = new Row() { RowIndex = rowIndex };
            sheetData.Append(row);
        }

        Cell cell = row.Elements<Cell>().FirstOrDefault(c => c.CellReference.Value == cellAddress);
        if (cell == null)
        {
            cell = new Cell() { CellReference = cellAddress };
            row.InsertAt(cell, GetCellIndex(row, cellAddress));
        }
        return cell;
    }

    private uint GetRowIndex(string cellAddress)
    {
        string rowPart;
        for (int i = 0; i < cellAddress.Length; i++)
        {
            if (Char.IsDigit(cellAddress[i]))
            {
                rowPart = cellAddress.Substring(i);
                if (UInt32.TryParse(rowPart, out uint rowIndex))
                {
                    return rowIndex;
                }
                else
                {
                    throw new ArgumentException($"Invalid cell address: {cellAddress}");
                }
            }
        }
        throw new ArgumentException($"Invalid cell address: {cellAddress}");
    }

    private int GetCellIndex(Row row, string cellAddress)
    {
        int index = 0;
        foreach (Cell cell in row.Elements<Cell>())
        {
            if (string.Compare(cell.CellReference.Value, cellAddress, StringComparison.OrdinalIgnoreCase) > 0)
            {
                return index;
            }
            index++;
        }
        return index;
    }
}
```

