public class ValidationResult
{
    public List<string> UnresolvedTypes { get; set; }
    public string ErrorMessage { get; set; }
}

public class ContainerValidator
{
    public ValidationResult ValidateContainer(Mock<IContainer> container)
    {
        var result = new ValidationResult();
        result.UnresolvedTypes = new List<string>();

        if (container.Object == null)
        {
            result.ErrorMessage = "Container is null";
            return result;
        }

        if (container.Object.IsEmpty())
        {
            result.ErrorMessage = "Container is empty";
            return result;
        }

        foreach (var type in container.Object.RegisteredTypes)
        {
            try
            {
                container.Object.Resolve(type);
            }
            catch (Exception ex)
            {
                result.UnresolvedTypes.Add(type);
                // Log the exception or capture the error message for the unresolved type
            }
        }

        return result;
    }
}
