            try {
                int maxFileSizeInMB = int.Parse(ConfigurationManager.AppSettings["MaxFileSizeMB"]);
                string[] allowedExtensions = ConfigurationManager.AppSettings["AllowedFileExtensions"].Split(',');

                if (uploadedFile.ContentLength > maxFileSizeInMB * 1024 * 1024) {
                    return false; // File size exceeds the limit
                }

                string fileExtension = Path.GetExtension(uploadedFile.FileName).TrimStart('.');
                if (!allowedExtensions.Contains(fileExtension, StringComparer.OrdinalIgnoreCase)) {
                    return false; // File type not allowed
                }

                string uploadDirectory = ConfigurationManager.AppSettings["UploadDirectory"];
                string filePath = Path.Combine(uploadDirectory, Path.GetFileName(uploadedFile.FileName));
                uploadedFile.SaveAs(filePath);
                return true; // File saved successfully
            }
            catch (Exception) {
                return false; // Error occurred during file upload
            }
        }
    }
}
