using UnityEngine;

public static class TransformExtensions
{
    public static T With<T>(this Transform transform, System.Func<Transform, T> componentSelector) where T : Component
    {
        if (transform == null)
        {
            Debug.LogWarning("Transform is null. Unable to retrieve component.");
            return null;
        }

        Transform nestedTransform = componentSelector(transform)?.transform;
        if (nestedTransform == null)
        {
            Debug.LogWarning("Nested transform not found. Unable to retrieve component.");
            return null;
        }

        T component = nestedTransform.GetComponent<T>();
        if (component == null)
        {
            Debug.LogWarning($"Component of type {typeof(T)} not found in the nested transform.");
        }

        return component;
    }
}

