using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class XmlDocumentationParser
{
    public List<string> ExtractXmlDocumentationComments(string code)
    {
        List<string> xmlComments = new List<string>();

        // Regular expression pattern to match XML documentation comments
        string pattern = @"///.*?\n.*?///.*?\n.*?///.*?\n";

        // Match XML documentation comments using regular expression
        MatchCollection matches = Regex.Matches(code, pattern, RegexOptions.Singleline);

        // Add matched XML documentation comments to the list
        foreach (Match match in matches)
        {
            xmlComments.Add(match.Value.Trim());
        }

        return xmlComments;
    }
}

