public class DataProcessor
{
    public List<DataEntry> ProcessData(List<DataEntry> entries)
    {
        List<DataEntry> uniqueEntries = new List<DataEntry>();
        HashSet<string> uniqueNames = new HashSet<string>();

        foreach (var entry in entries)
