```csharp
public class GameBoard
{
    public int MinToWinVertically { get; set; }
    public int MinToWinDiagonally { get; set; }
    private int[,] board; // Assume this is the game board represented as a 2D array

    public bool HasPlayerWon(int player)
    {
        // Check for vertical win
        for (int col = 0; col < board.GetLength(1); col++)
        {
            int count = 0;
            for (int row = 0; row < board.GetLength(0); row++)
            {
                if (board[row, col] == player)
                {
                    count++;
                    if (count >= MinToWinVertically)
                    {
                        return true;
                    }
                }
                else
                {
                    count = 0;
                }
            }
        }

        // Check for diagonal win
        for (int row = 0; row < board.GetLength(0); row++)
        {
            for (int col = 0; col < board.GetLength(1); col++)
            {
                if (board[row, col] == player)
                {
                    // Check diagonally to the right
                    int count = 1;
                    for (int i = 1; i < MinToWinDiagonally; i++)
                    {
                        if (row + i < board.GetLength(0) && col + i < board.GetLength(1) && board[row + i, col + i] == player)
                        {
                            count++;
                            if (count >= MinToWinDiagonally)
                            {
                                return true;
                            }
                        }
                        else
                        {
                            break;
                        }
                    }

                    // Check diagonally to the left
                    count = 1;
                    for (int i = 1; i < MinToWinDiagonally; i++)
                    {
                        if (row + i < board.GetLength(0) && col - i >= 0 && board[row + i, col - i] == player)
                        {
                            count++;
                            if (count >= MinToWinDiagonally)
                            {
                                return true;
                            }
                        }
                        else
                        {
                            break;
                        }
                    }
                }
            }
        }

        return false; // No win condition found
    }
}
```

In the solution, the `HasPlayerWon` method iterates through the game board to check for the win condition vertically and diagonally based on the `MinToWinVertically` and `MinToWinDiagonally` properties. It efficiently checks for the specified player's win condition and returns `true` if the player has won, and `false` otherwise.

