public class Stack
{
    private Node top;

    public void Push(int value)
    {
        if (top == null)
        {
            top = new Node { Value = value, MinValue = value, Next = null };
        }
        else
        {
            var newNode = new Node { Value = value, Next = top, MinValue = Math.Min(value, top.MinValue) };
            top = newNode;
        }
    }

    public int Pop()
    {
        if (top == null)
        {
            return -1; // Stack is empty
        }
        else
        {
            int value = top.Value;
            top = top.Next;
            return value;
        }
    }

    public int Peek()
    {
        if (top == null)
        {
            return -1; // Stack is empty
        }
        else
        {
            return top.Value;
        }
    }

    public int GetMin()
    {
        if (top == null)
        {
            return -1; // Stack is empty
        }
        else
        {
            return top.MinValue;
        }
    }
}
```

The `Stack` class maintains a reference to the top node of the stack. When pushing a new value, a new node is created with the current minimum value and added to the top of the stack. When popping a value, the top node is removed and its value is returned. The `Peek` method returns the value of the top node without removing it, and the `GetMin` method returns the minimum value in the stack. All operations have a time complexity of O(1).

