        {
            if (ver >= 5)
            {
                TargetVersion = version;
            }
            else
            {
                throw new ArgumentException("Invalid JavaScript version. Minimum supported version is es5.");
            }
        }
        else
        {
            throw new ArgumentException("Invalid JavaScript version format. Use 'es' followed by a version number.");
