using Microsoft.Office.Interop.Word;

class Program
{
    static void Main(string[] args)
    {
        if (args.Length > 0)
        {
            string path = args[0];
            ConvertToDocx(path);
        }
        else
        {
            Console.WriteLine("Please provide the directory path as a command-line argument.");
        }
    }

    static void ConvertToDocx(string directoryPath)
    {
        string[] files = Directory.GetFiles(directoryPath, "*.*", SearchOption.AllDirectories);
        Application wordApp = new Application();

        foreach (string file in files)
        {
            if (Path.GetExtension(file) != ".docx")
            {
                try
                {
                    Document doc = wordApp.Documents.Open(file);
                    string newFilePath = Path.ChangeExtension(file, ".docx");
                    doc.SaveAs2(newFilePath, WdSaveFormat.wdFormatXMLDocument);
                    doc.Close();
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error converting {file} to .docx: {ex.Message}");
                }
            }
        }

        wordApp.Quit();
        Console.WriteLine("Conversion to .docx completed.");
    }
}
