```csharp
public class Float3
{
    public float X { get; }
    public float Y { get; }
    public float Z { get; }

    public Float3(float x, float y, float z)
    {
        X = x;
        Y = y;
        Z = z;
    }

    public static Float3 Cross(Float3 u, Float3 v)
    {
        return new Float3(u.Y * v.Z - u.Z * v.Y, u.Z * v.X - u.X * v.Z, u.X * v.Y - u.Y * v.X);
    }

    public static float Dot(Float3 u, Float3 v)
    {
        return u.X * v.X + u.Y * v.Y + u.Z * v.Z;
    }

    public static Float3 operator -(Float3 u, Float3 v)
    {
        return new Float3(u.X - v.X, u.Y - v.Y, u.Z - v.Z);
    }

    public void Normalize()
    {
        float length = (float)Math.Sqrt(X * X + Y * Y + Z * Z);
        X /= length;
        Y /= length;
        Z /= length;
    }
}

public class Flat
{
    public Float3 Normal { get; }
    public float Distance { get; }

    public Flat(in Float3 a, in Float3 b, in Float3 c)
    {
        Normal = Float3.Cross(b - a, c - a);
        Normal.Normalize();
        Distance = -Float3.Dot(Normal, a);
    }

    public bool ContainsPoint(Float3 point)
    {
        float result = Normal.X * point.X + Normal.Y * point.Y + Normal.Z * point.Z + Distance;
        return Math.Abs(result) < float.Epsilon;
    }
}
```

