```csharp
using System;
using System.Collections.Generic;

public class ViewModelCache
{
    private Dictionary<int, IMvxViewModel> cache;
    private Dictionary<Type, int> typeIndexMap;
    private int currentIndex;

    public ViewModelCache()
    {
        cache = new Dictionary<int, IMvxViewModel>();
        typeIndexMap = new Dictionary<Type, int>();
        currentIndex = 0;
    }

    public int Cache(IMvxViewModel viewModel)
    {
        cache[currentIndex] = viewModel;
        typeIndexMap[viewModel.GetType()] = currentIndex;
        return currentIndex++;
    }

    public IMvxViewModel Get(int index)
    {
        if (cache.ContainsKey(index))
        {
            return cache[index];
        }
        else
        {
            throw new KeyNotFoundException("View model not found in cache");
        }
    }

    public IMvxViewModel Get(Type viewModelType)
    {
        if (typeIndexMap.ContainsKey(viewModelType))
        {
            int index = typeIndexMap[viewModelType];
            return cache[index];
        }
        else
        {
            throw new KeyNotFoundException("View model type not found in cache");
        }
    }

    public void Remove(int index)
    {
        if (cache.ContainsKey(index))
        {
            typeIndexMap.Remove(cache[index].GetType());
            cache.Remove(index);
        }
        else
        {
            throw new KeyNotFoundException("View model not found in cache");
        }
    }
}
```

