```csharp
public class Polygon
{
    public static Vector2 GetClosestPointOnPolygonToPoint(List<Vector2> polygonPoints, Vector2 relativePoint,
        out float distanceSquared, out Vector2 normal)
    {
        Vector2 closestPoint = Vector2.zero;
        distanceSquared = float.MaxValue;
        normal = Vector2.zero;

        for (int i = 0; i < polygonPoints.Count; i++)
        {
            int nextIndex = (i + 1) % polygonPoints.Count;
            Vector2 edge = polygonPoints[nextIndex] - polygonPoints[i];
            Vector2 pointVector = relativePoint - polygonPoints[i];
            float t = Vector2.Dot(pointVector, edge) / Vector2.Dot(edge, edge);

            if (t < 0)
            {
                t = 0;
            }
            else if (t > 1)
            {
                t = 1;
            }

            Vector2 closest = polygonPoints[i] + t * edge;
            float distSqr = (relativePoint - closest).sqrMagnitude;

            if (distSqr < distanceSquared)
            {
                distanceSquared = distSqr;
                closestPoint = closest;
                normal = Vector2.Perpendicular(edge).normalized;
            }
        }

        return closestPoint;
    }
}
```

In the `GetClosestPointOnPolygonToPoint` method, we iterate through each edge of the polygon and calculate the closest point on the edge to the given point. We then update the closest point and the distance squared if the calculated distance is smaller than the current minimum. Finally, we return the closest point on the polygon to the given point.

