```csharp
using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class Program
{
    public static Dictionary<string, string> ExtractRequestInfo(string codeSnippet)
    {
        Dictionary<string, string> requestInfo = new Dictionary<string, string>();

        // Define the pattern to match the verb and URL
        string pattern = @"\.WithVerb\((?<verb>.*?)\)\.WithResourceUrl\((?<url>.*?)\)";

        // Match the pattern in the code snippet
        Match match = Regex.Match(codeSnippet, pattern);

        // Extract the verb and URL from the match
        if (match.Success)
        {
            string verb = match.Groups["verb"].Value.Trim('\'');
            string url = match.Groups["url"].Value.Trim('\'');
            requestInfo.Add("Verb", verb);
            requestInfo.Add("URL", url);
        }

        return requestInfo;
    }

