{
    // Implementation details not relevant to the problem
}

public class ArgIterator
{
    // Implementation details not relevant to the problem
}

public class RemainingArgumentsParser<T>
{
    private readonly T _t = default(T);
    private readonly MemberAttribute _remaining = null;
    private readonly ArgIterator _argIt = null;

    public RemainingArgumentsParser(T t, MemberAttribute remaining, ArgIterator argIt)
    {
        _t = t;
        _remaining = remaining;
        _argIt = argIt;
    }

    public void Parse()
    {
