```csharp
public void Parse()
{
    var remainingArguments = new List<string>();
    var namedArguments = new Dictionary<string, string>();

    while (_argIt.HasNext())
    {
        string arg = _argIt.GetNext();

        if (arg.StartsWith("-"))
        {
            // Named argument
            string flag = arg.TrimStart('-');
            if (_argIt.HasNext())
            {
                string value = _argIt.GetNext();
                namedArguments[flag] = value;
            }
            else
            {
                // Named argument without value
                namedArguments[flag] = null;
            }
        }
        else
        {
            // Remaining argument
            remainingArguments.Add(arg);
        }
    }

    // Store named arguments in the generic type T
    foreach (var prop in typeof(T).GetProperties())
    {
        if (namedArguments.ContainsKey(prop.Name))
        {
            prop.SetValue(_t, Convert.ChangeType(namedArguments[prop.Name], prop.PropertyType));
        }
    }

    // Store remaining arguments in the MemberAttribute
    _remaining.SetValue(remainingArguments.ToArray());
}
```

This solution iterates through the command-line arguments using the `ArgIterator` and separates them into named arguments and remaining arguments. It then stores the named arguments in the properties of the generic type `T` and the remaining arguments in the `MemberAttribute` instance.

