namespace System.Data
{
    public class MinStack
    {
        private Stack<int> stack;
        private Stack<int> minStack;

        public MinStack()
        {
            stack = new Stack<int>();
            minStack = new Stack<int>();
        }

        public void Push(int x)
        {
            stack.Push(x);
            if (minStack.Count == 0 || x <= minStack.Peek())
            {
                minStack.Push(x);
            }
        }

        public void Pop()
        {
            if (stack.Count > 0)
            {
                if (stack.Peek() == minStack.Peek())
                {
                    minStack.Pop();
                }
                stack.Pop();
            }
        }

        public int Top()
        {
            if (stack.Count > 0)
            {
                return stack.Peek();
            }
            throw new InvalidOperationException("Stack is empty");
        }

        public int GetMin()
        {
            if (minStack.Count > 0)
            {
                return minStack.Peek();
            }
            throw new InvalidOperationException("Stack is empty");
        }
    }
}
```

In this solution, the `MinStack` class is implemented using two stacks: `stack` to store the actual elements and `minStack` to keep track of the minimum element at the top of the stack at any given time. The `Push` operation adds the element to the `stack` and updates the `minStack` if the new element is smaller or equal to the current minimum. The `Pop` operation removes the top element from both stacks if the `stack` is not empty. The `Top` operation retrieves the top element from the `stack`, and the `GetMin` operation retrieves the minimum element from the `minStack`. All operations are designed to handle nullable reference types.

