1. `Push(int x)`: Add element x to the stack.
2. `Pop()`: Remove the top element from the stack.
3. `Top()`: Get the top element of the stack.
4. `GetMin()`: Retrieve the minimum element in the stack.

Your task is to implement the `MinStack` class using the provided code snippet as a starting point. You should use a Windows Universal Platform (UWP) application and the `List<T>` class from the `System.Collections.Generic` namespace to store the stack elements. The `MinStack` class should have O(1) time complexity for all operations.

```csharp
using System;
using System.Collections.Generic;

namespace MinStackImplementation
{
    public class MinStack
    {
        private List<int> stack;
        private List<int> minStack;

        public MinStack()
        {
            stack = new List<int>();
            minStack = new List<int>();
        }

        public void Push(int x)
        {
            stack.Add(x);
            if (minStack.Count == 0 || x <= minStack[minStack.Count - 1])
            {
                minStack.Add(x);
            }
        }

        public void Pop()
        {
            if (stack.Count > 0)
            {
                int popped = stack[stack.Count - 1];
                stack.RemoveAt(stack.Count - 1);
                if (popped == minStack[minStack.Count - 1])
                {
                    minStack.RemoveAt(minStack.Count - 1);
                }
            }
        }

        public int Top()
        {
            if (stack.Count > 0)
            {
                return stack[stack.Count - 1];
            }
            throw new InvalidOperationException("Stack is empty");
        }

        public int GetMin()
        {
            if (minStack.Count > 0)
            {
                return minStack[minStack.Count - 1];
            }
            throw new InvalidOperationException("Stack is empty");
        }
    }
}
