public class RomanNumeralFormatter
{
    private static readonly string[] Thousands = { "", "M", "MM", "MMM" };
    private static readonly string[] Hundreds = { "", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM" };
    private static readonly string[] Tens = { "", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC" };
    private static readonly string[] Ones = { "", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX" };

    public string Format(int number)
    {
        if (number < -3999 || number > 3999)
        {
            throw new ArgumentOutOfRangeException("number", "Number must be within the range of -3999 to 3999");
        }

        if (number == 0)
        {
            return "N";
        }

        string sign = number < 0 ? "−" : "";
        number = Math.Abs(number);

        return sign + Thousands[number / 1000] + Hundreds[(number % 1000) / 100] + Tens[(number % 100) / 10] + Ones[number % 10];
    }
}
