public int GetRandomCubeId(MonoBlock.BlockType type)
{
    List<int> matchingIds = new List<int>();

    // Find all cube asset IDs that match the given block type
    for (int i = 0; i < CubeAssetList.Count; i++)
    {
        if (CubeAssetList[i].BlockType == type)
        {
            matchingIds.Add(i);
        }
    }

    // If no matching cube asset IDs found, return -1
    if (matchingIds.Count == 0)
