    static void Main()
    {
        Console.Write("Enter the file path: ");
        string filePath = Console.ReadLine();

        if (File.Exists(filePath))
        {
            string text = File.ReadAllText(filePath);
            string[] words = Regex.Split(text, @"\W+"); // Tokenize the text into words, ignoring punctuation

            Dictionary<string, int> wordCount = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (string word in words)
            {
                if (!string.IsNullOrWhiteSpace(word))
                {
                    if (wordCount.ContainsKey(word))
                    {
                        wordCount[word]++;
                    }
                    else
                    {
                        wordCount[word] = 1;
                    }
                }
            }

            Console.Write("Enter the number of top words to display: ");
            if (int.TryParse(Console.ReadLine(), out int topN))
            {
                var topWords = wordCount.OrderByDescending(pair => pair.Value).Take(topN);
                foreach (var pair in topWords)
                {
                    Console.WriteLine($"Word: {pair.Key}, Count: {pair.Value}");
                }
            }
            else
            {
                Console.WriteLine("Invalid input for the number of top words.");
            }
        }
        else
        {
            Console.WriteLine("File not found at the specified path.");
        }
    }
