```csharp
public override object InterpolateGeneric(object from, object to, float weight)
{
    Type type = from.GetType();

    if (type == typeof(int))
    {
        int fromValue = (int)from;
        int toValue = (int)to;
        return (int)(fromValue + (toValue - fromValue) * weight);
    }
    else if (type == typeof(float))
    {
        float fromValue = (float)from;
        float toValue = (float)to;
        return fromValue + (toValue - fromValue) * weight;
    }
    else if (type == typeof(double))
    {
        double fromValue = (double)from;
        double toValue = (double)to;
        return fromValue + (toValue - fromValue) * weight;
    }
    else if (type == typeof(decimal))
    {
        decimal fromValue = (decimal)from;
        decimal toValue = (decimal)to;
        return fromValue + (toValue - fromValue) * (decimal)weight;
    }
    else
    {
        // Handle custom types that implement interpolation logic
        MethodInfo interpolateMethod = type.GetMethod("Interpolate");
        if (interpolateMethod != null)
        {
            return interpolateMethod.Invoke(null, new object[] { from, to, weight });
        }
        else
        {
            throw new ArgumentException("Unsupported type for interpolation");
        }
    }
}
