    public static string ConvertGlobToRegex(string globPattern)
    {
        StringBuilder regexPattern = new StringBuilder("^");

        foreach (char c in globPattern)
        {
            switch (c)
            {
                case '*':
                    regexPattern.Append(".*");
                    break;
                case '?':
                    regexPattern.Append(".");
                    break;
                case '.':
                case '(':
                case ')':
                case '[':
                case ']':
                case '{':
                case '}':
                case '^':
                case '$':
                case '|':
                case '+':
                case '\\':
                    regexPattern.Append("\\" + c);
                    break;
                default:
                    regexPattern.Append(c);
                    break;
            }
        }

        regexPattern.Append("$");
        return regexPattern.ToString();
    }

