public class CustomStringBuilder
{
    public static string CustomReplace(string originalString, char oldChar, char newChar, int startIndex, int count)
    {
        if (startIndex < 0 || startIndex >= originalString.Length || count < 0)
        {
            throw new ArgumentException("Invalid startIndex or count");
        }

        int endIndex = startIndex + count;
        if (endIndex > originalString.Length)
        {
            endIndex = originalString.Length;
        }

        StringBuilder sb = new StringBuilder(originalString);
        for (int i = startIndex; i < endIndex; i++)
        {
            if (sb[i] == oldChar)
            {
                sb[i] = newChar;
            }
        }

        return sb.ToString();
    }

