using System;
using System.Threading;

public struct InterlockedBoolean : IComparable, IComparable<InterlockedBoolean>, IComparable<bool>, IEquatable<InterlockedBoolean>, IEquatable<bool>
{
    const int FALSE = 0;
    const int TRUE = ~FALSE; //-1
    volatile int _value; // Will be initialized as False

    public InterlockedBoolean(bool value)
    {
        _value = value ? TRUE : FALSE;
    }

    public void SetTrue()
    {
        Interlocked.Exchange(ref _value, TRUE);
    }

    public void SetFalse()
    {
        Interlocked.Exchange(ref _value, FALSE);
    }

    public bool GetValue()
    {
        return Interlocked.CompareExchange(ref _value, FALSE, FALSE) != FALSE;
    }

    public static implicit operator bool(InterlockedBoolean interlockedBoolean)
    {
        return interlockedBoolean.GetValue();
    }

    public int CompareTo(InterlockedBoolean other)
    {
        return _value.CompareTo(other._value);
    }

    public int CompareTo(bool other)
    {
        return GetValue().CompareTo(other);
    }

    public bool Equals(InterlockedBoolean other)
    {
        return _value == other._value;
    }

    public bool Equals(bool other)
    {
        return GetValue() == other;
    }
}
