```csharp
public List<uint> GetAppIdsWithMatchingTags(List<string> tags)
{
    List<uint> matchingAppIds = new List<uint>();

    // Get all the files in the directory
    string[] manifestFiles = Directory.GetFiles(this.path, "appmanifest_*.acf");

    foreach (string manifestFile in manifestFiles)
    {
        bool allTagsMatched = true;

        // Read the manifest file and check if it contains all the specified tags
        string[] lines = File.ReadAllLines(manifestFile);
        foreach (string tag in tags)
        {
            if (!lines.Any(line => line.Contains(tag)))
            {
                allTagsMatched = false;
                break;
            }
        }

        if (allTagsMatched)
        {
            // Extract the appid from the file name and add it to the matching list
            string fileName = Path.GetFileNameWithoutExtension(manifestFile);
            if (fileName.StartsWith("appmanifest_") && uint.TryParse(fileName.Substring(12), out uint appId))
            {
                matchingAppIds.Add(appId);
            }
        }
    }

    return matchingAppIds;
}
```

