```csharp
// Define the MappingConfig class to hold the mapping configurations
public class MappingConfig
{
    private readonly List<Mapping> mappings = new List<Mapping>();

    public void CreateMap<TSource, TDestination>(Expression<Func<TSource, object>> source, Expression<Func<TDestination, object>> destination)
    {
        var mapping = new Mapping(typeof(TSource), typeof(TDestination), source, destination);
        mappings.Add(mapping);
    }

    public List<Mapping> GetMappings()
    {
        return mappings;
    }
}

// Define the Mapping class to represent a mapping configuration
public class Mapping
{
    public Type SourceType { get; }
    public Type DestinationType { get; }
    public LambdaExpression SourceExpression { get; }
    public LambdaExpression DestinationExpression { get; }

    public Mapping(Type sourceType, Type destinationType, LambdaExpression source, LambdaExpression destination)
    {
        SourceType = sourceType;
        DestinationType = destinationType;
        SourceExpression = source;
        DestinationExpression = destination;
    }
}

// Define the Mapper class to perform the mapping based on the provided configuration
public class Mapper
{
    private readonly MappingConfig mappingConfig;

    public Mapper(MappingConfig config)
    {
        mappingConfig = config;
    }

    public TDestination Map<TSource, TDestination>(TSource source)
    {
        var destination = Activator.CreateInstance<TDestination>();
        var mappings = mappingConfig.GetMappings().Where(m => m.SourceType == typeof(TSource) && m.DestinationType == typeof(TDestination));

        foreach (var mapping in mappings)
        {
            var sourceValue = mapping.SourceExpression.Compile().DynamicInvoke(source);
            var destinationProperty = (PropertyInfo)((MemberExpression)mapping.DestinationExpression.Body).Member;
            destinationProperty.SetValue(destination, sourceValue);
        }

        return destination;
    }
}
```

In this solution, the `MappingConfig` class allows the creation of mapping configurations using lambda expressions, and the `Mapper` class performs the actual mapping based on the provided configuration. The `Map` method iterates through the mappings for the given source and destination types, retrieves the source property value using the source lambda expression, and sets the corresponding destination property value using reflection. This solution supports mapping properties of different types and can be extended to handle nested objects and more complex mapping scenarios.

