public class Message
{
    public CodecType CodecType { get; set; }
    public byte[] Data { get; set; }
}

public enum CodecType
{
    JSON,
    XML,
    Binary
}

public class MessageSerializer
{
    public byte[] Serialize(Message message)
    {
        using (MemoryStream output = new MemoryStream())
        {
            output.WriteByte((byte)message.CodecType);

            if (message.Data != null)
            {
                output.Write(message.Data, 0, message.Data.Length);
            }

            return output.ToArray();
        }
    }

    public Message Deserialize(byte[] data)
    {
        if (data == null || data.Length == 0)
        {
            throw new ArgumentException("Invalid byte stream for deserialization");
        }

        Message message = new Message();

        message.CodecType = (CodecType)data[0];

        if (data.Length > 1)
        {
            message.Data = new byte[data.Length - 1];
            Array.Copy(data, 1, message.Data, 0, data.Length - 1);
        }

        return message;
    }
}
```

In the solution, the `Deserialize` method checks for the validity of the byte stream and then extracts the codec type and optional data from the byte stream to reconstruct the original message. If the byte stream is empty or null, an `ArgumentException` is thrown. If the byte stream contains only the codec type, the data in the message object is set to null. If the byte stream contains both the codec type and data, the data is extracted and assigned to the message object.

