public class Othello
{
    public static int[,] Board = new int[8, 8]; // Initialize the game board

    public void PlaceDisc(int x, int y, int playerColor)
    {
        if (Board[y, x] != 0) // Cell is not empty
        {
            Console.WriteLine("Invalid move: Cell is not empty.");
            return;
        }

        int opponentColor = (playerColor == 1) ? 2 : 1;

        // Check all 8 directions for opponent discs to flip
        for (int dx = -1; dx <= 1; dx++)
        {
            for (int dy = -1; dy <= 1; dy++)
            {
                if (dx == 0 && dy == 0) continue; // Skip the current cell

                int cx = x + dx;
                int cy = y + dy;
                bool foundOpponent = false;

                while (cx >= 0 && cx < 8 && cy >= 0 && cy < 8 && Board[cy, cx] == opponentColor)
                {
                    cx += dx;
                    cy += dy;
                    foundOpponent = true;
                }

                if (foundOpponent && cx >= 0 && cx < 8 && cy >= 0 && cy < 8 && Board[cy, cx] == playerColor)
                {
                    // Flip opponent discs in this direction
                    int flipX = x + dx;
                    int flipY = y + dy;
                    while (flipX != cx || flipY != cy)
                    {
                        Board[flipY, flipX] = playerColor;
                        flipX += dx;
                        flipY += dy;
                    }
                }
            }
        }

        if (!CanFlipInAnyDirection(x, y, playerColor))
        {
            Console.WriteLine("Invalid move: No opponent discs can be flipped.");
            return;
        }

        // Place the player's disc at the specified position
        Board[y, x] = playerColor;
    }

    private bool CanFlipInAnyDirection(int x, int y, int playerColor)
    {
        for (int dx = -1; dx <= 1; dx++)
        {
            for (int dy = -1; dy <= 1; dy++)
            {
                if (dx == 0 && dy == 0) continue; // Skip the current cell

                int cx = x + dx;
                int cy = y + dy;
                bool foundOpponent = false;

                while (cx >= 0 && cx < 8 && cy >= 0 && cy < 8 && Board[cy, cx] == (playerColor == 1 ? 2 : 1))
                {
                    cx += dx;
                    cy += dy;
                    foundOpponent = true;
                }

                if (foundOpponent && cx >= 0 && cx < 8 && cy >= 0 && cy < 8 && Board[cy, cx] == playerColor)
                {
                    return true;
                }
            }
        }
        return false;
    }
}
```
