    public EventEmitter()
    {
        eventHandlers = new Dictionary<string, List<Action<object>>>();
    }

    public void On(string eventName, Action<object> eventHandler)
    {
        if (!eventHandlers.ContainsKey(eventName))
        {
            eventHandlers[eventName] = new List<Action<object>>();
        }
        eventHandlers[eventName].Add(eventHandler);
    }

    public void Emit(string eventName, object eventData = null)
    {
        if (eventHandlers.ContainsKey(eventName))
        {
            foreach (var handler in eventHandlers[eventName])
            {
                handler?.Invoke(eventData);
            }
        }
    }

    public void Off(string eventName, Action<object> eventHandler)
    {
        if (eventHandlers.ContainsKey(eventName))
        {
            eventHandlers[eventName].Remove(eventHandler);
        }
    }
}
