public class UriParser
{
    public string ParseScheme(string uri)
    {
        Uri parsedUri;
        if (Uri.TryCreate(uri, UriKind.Absolute, out parsedUri))
        {
            return parsedUri.Scheme;
        }
        return null;
    }

    public string ParseHost(string uri)
    {
        Uri parsedUri;
        if (Uri.TryCreate(uri, UriKind.Absolute, out parsedUri))
        {
            return parsedUri.Host;
        }
        return null;
    }

    public string ParsePort(string uri)
    {
        Uri parsedUri;
        if (Uri.TryCreate(uri, UriKind.Absolute, out parsedUri))
        {
            if (parsedUri.IsDefaultPort)
            {
                return null;
            }
            return parsedUri.Port.ToString();
        }
        return null;
    }

    public string ParsePath(string uri)
    {
        Uri parsedUri;
        if (Uri.TryCreate(uri, UriKind.Absolute, out parsedUri))
        {
            return parsedUri.AbsolutePath;
        }
        return null;
    }

    public Dictionary<string, string> ParseQueryParameters(string uri)
    {
        Uri parsedUri;
        if (Uri.TryCreate(uri, UriKind.Absolute, out parsedUri))
        {
            var query = parsedUri.Query.TrimStart('?');
            var queryParameters = new Dictionary<string, string>();
            foreach (var parameter in query.Split('&'))
            {
                var pair = parameter.Split('=');
                if (pair.Length == 2)
                {
                    queryParameters.Add(pair[0], pair[1]);
                }
            }
            return queryParameters;
        }
        return null;
    }

    public string ParseFragment(string uri)
    {
        Uri parsedUri;
        if (Uri.TryCreate(uri, UriKind.Absolute, out parsedUri))
        {
            return parsedUri.Fragment.TrimStart('#');
        }
        return null;
    }
