public async Task<List<Entry>> GetAllEntriesAsync(DatabaseClient client, Builder noCoordinatesBuilder)
{
    List<Entry> entriesWithoutCoordinates = await client.GetEntriesWithoutCoordinatesAsync(); // Retrieve entries without coordinates from the database

    List<Task<EntryWithCoordinates>> coordinateTasks = new List<Task<EntryWithCoordinates>>();

    foreach (var entry in entriesWithoutCoordinates)
    {
        Task<EntryWithCoordinates> coordinateTask = FetchCoordinatesAsync(entry, noCoordinatesBuilder); // Asynchronously fetch coordinates for each entry
        coordinateTasks.Add(coordinateTask);
    }

    await Task.WhenAll(coordinateTasks); // Wait for all coordinate retrieval tasks to complete

    List<EntryWithCoordinates> entriesWithCoordinates = new List<EntryWithCoordinates>();

    foreach (var task in coordinateTasks)
    {
        entriesWithCoordinates.Add(await task); // Retrieve the completed tasks and add the entries with coordinates to the list
    }

    return entriesWithCoordinates;
}

