```csharp
public static int BinaryGcd(int a, int b)
{
    if (a < 0 || b < 0)
    {
        throw new ArgumentOutOfRangeException("Both numbers must be non-negative");
    }

    if (a == 0)
    {
        return b;
    }
    else if (b == 0)
    {
        return a;
    }

    int shift;
    for (shift = 0; ((a | b) & 1) == 0; ++shift)
    {
        a >>= 1;
        b >>= 1;
    }

    while ((a & 1) == 0)
    {
        a >>= 1;
    }

    while (b != 0)
    {
        while ((b & 1) == 0)
        {
            b >>= 1;
        }

        if (a > b)
        {
            int temp = b;
            b = a;
            a = temp;
        }

        b = b - a;
    }

    return a << shift;
}
```
