using System;

class Program
{
    static void Main(string[] args)
    {
        Console.Write("Enter a string: ");
        string userString = Console.ReadLine();

        string reversed = ReverseString(userString);

        string encrypted = CaesarCipher(reversed, 3);

        Console.WriteLine("Encrypted string: " + encrypted);

    }

    static string ReverseString(string s)
    {
        char[] arr = s.ToCharArray();
        Array.Reverse(arr);
        return new string(arr);
    }

    static string CaesarCipher(string input, int shift)
    {
        char[] buffer = input.ToCharArray();
        for (int i = 0; i < buffer.Length; i++)
        {
            // Letters only
            char letter = buffer[i];
            if (char.IsLetter(letter))
            {
                // Add shift to all.
                letter = (char)(letter + shift);
                // Subtract 26 on overflow.
                // Add 26 on underflow.
                if (char.IsUpper(buffer[i]))
                {
                    if (letter > 'Z')
                    {
                        letter = (char)(letter - 26);
                    }
                    else if (letter < 'A')
                    {
                        letter = (char)(letter + 26);
                    }
                }
                else
                {
                    if (letter > 'z')
                    {
                        letter = (char)(letter - 26);
                    }
                    else if (letter < 'a')
                    {
                        letter = (char)(letter + 26);
                    }
                }
                // Store.
                buffer[i] = letter;
            }
        }
        return new string(buffer);
    }
}
```

This program first captures user input string. Then, it reverses the input string. After that, it applies a Caesar cipher (with a shift of 3) to the reversed string. When applying the cipher, it checks if the character is a letter or not. If it is a letter, it shifts it by 3. In the case of an overflow (e.g., 'z' shifted by 3), it wraps around to the start of the alphabet. If it underflows (e.g., 'a' shifted by -3), it wraps around to the end of the alphabet. Finally, it prints the final encrypted string.

