using System.Collections.Generic;
using System.Linq;

public class Solution {
    public List<List<string>> ListSort(List<string> lst) {
        // Deleting strings of odd lengths
        lst.RemoveAll(s => s.Length % 2 != 0);

        // Sorting the list of strings first by their lengths and then alphabetically
        lst.Sort( (a, b) => a.Length != b.Length ? a.Length.CompareTo(b.Length) : String.Compare(a, b));

        // Using Dictionary to maintain the order of insertion
        Dictionary<int, List<string>> map = new Dictionary<int, list<string>>();

        foreach (string s in lst) {

            // Grouping the strings by their lengths and eliminating duplicates
            if (!map.ContainsKey(s.Length))
                map[s.Length] = new List<string>();

            if (!map[s.Length].Contains(s))
                map[s.Length].Add(s);
