```Csharp
using System;
using System.Linq;

public static (int index, double sum) FindAndSum<T>(T[] arr, T val, T divisor) where T: IConvertible
{
    int firstOccurrence = -1;
    double sum = 0.0;
    double value = Convert.ToDouble(val);
    double divisorValue = Convert.ToDouble(divisor);

    for (int i = 0; i < arr.Length; i++)
    {
        double current = Convert.ToDouble(arr[i]);

        if (current % divisorValue != 0) // current value not divisible by divisor value
        {
            if (current > value && firstOccurrence == -1)
            {
                firstOccurrence = i;
            }
            if (firstOccurrence == -1 || i < firstOccurrence)
            {
                sum += current;
            }
        }
    }

    return (firstOccurrence, sum);
}
```

