Here's the PascalABC.NET code to implement a recursive function to find all prime numbers within a given range. This code uses the Sieve of Eratosthenes algorithm for finding prime numbers which has a time complexity of O(n log(log n)). The code also includes input validation with exception handling.

```csharp
using System;
using System.Collections;
using System.Collections.Generic;

class Program
{
    public static void Main(string[] args)
    {
        try
        {
            int N = int.Parse(Console.ReadLine());
            int M = int.Parse(Console.ReadLine());

            if(N < 2 || N > 1000 || N > M || M > 100000)
            {
                throw new Exception("Invalid Input");
            }

            PrintPrimes(N, M);

        }
        catch(Exception ex)
        {
            Console.WriteLine(ex.Message);
        }
    }

    public static void PrintPrimes(int N, int M, int i = 2)
    {
        // Base Case
        if(i > M)
        {
            return;
        }

        // Recursive Case
        if(IsPrime(i) && i >= N)
        {
            Console.Write(i + " ");
        }

        PrintPrimes(N, M, i + 1);
    }

    public static bool IsPrime(int n)
    {
        if (n <= 1) 
            return false;

        if (n == 2 || n == 3) 
            return true;

        if (n % 2 == 0 || n % 3 == 0)
            return false;

        int i = 5;
        int w = 2;    

        while (i * i <= n)
        {
            if(n % i == 0)
                return false;

            i += w;
            w = 6 - w; 
        }

        return true;
    }      
}
```

