                }

                Console.WriteLine(ConvertNumberToWords(number));
            }
        }
        catch (ArgumentException ex)
        {
            Console.WriteLine(ex.Message);
        }
    }

    private static string ConvertNumberToWords(int number)
    {
        if (number == 0)
        {
            return NumberToWordLookup[number];
