```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    private static T GetNth<T>(List<T> l, int N, Func<T, T, int> cmp_func)
    {
        if (l.Count <= 1)
        {
            return l[0];
        }

        T pivot = l[l.Count / 2];
        var less = l.Where(x => cmp_func(x, pivot) < 0).ToList();
        var equal = l.Where(x => cmp_func(x, pivot) == 0).ToList();
        var greater = l.Where(x => cmp_func(x, pivot) > 0).ToList();

        if (N < less.Count)
        {
            return GetNth(less, N, cmp_func);
        }
        else if (N < less.Count + equal.Count)
        {
            return pivot;
        }
        else
        {
            return GetNth(greater, N - less.Count - equal.Count, cmp_func);
        }
    }

    public static double Median<T>(List<T> l, Func<T, T, int> cmp_func)
    {
        if (l.Count % 2 == 1)
        {
            return Convert.ToDouble(GetNth(l, l.Count / 2, cmp_func));
        }
        else
        {
            return (Convert.ToDouble(GetNth(l, l.Count / 2 - 1, cmp_func)) +
                    Convert.ToDouble(GetNth(l, l.Count / 2, cmp_func))) / 2;
        }
    }

    public static void Main()
    {
        // tests
        var list1 = new List<Tuple<int, int>> {
            new Tuple<int, int>(1, 2),
            new Tuple<int, int>(3, 4),
            new Tuple<int, int>(5, 6)};

        Console.WriteLine(Median(list1, (x, y) => (x.Item1 * x.Item2) - (y.Item1 * y.Item2)));

        var list2 = new List<Tuple<int, int>> {
            new Tuple<int, int>(1, 2),
            new Tuple<int, int>(3, 4),
            new Tuple<int, int>(5, 6),
            new Tuple<int, int>(7, 8)};

        Console.WriteLine(Median(list2, (x, y) => (x.Item1 * x.Item2) - (y.Item1 * y.Item2)));
    }
}
```

Please note that in PascalABC.NET, lambda expression are represented with the `Func` delegate type. Also, PascalABC.NET doesn't support callable type as a function argument as Python does. For those reasons, the comparison function has to be passed in the form of a delegate (Func). A Func with two input arguments of type T and an output argument of type int is the PascalABC.NET equivalent of the Python callable. In the given test case, T corresponds to `Tuple <int, int>`.

The example was rewritten with a common type T so that potentially any type comparing function can be passed. The comparison function must take two arguments of type T, and return an integer. If the returned number is > 0, the second argument is considered greater, if it's < 0, the first one is considered greater. If it equals to 0, the arguments are considered equal.

