```CSharp
public class NumberToWords
{
    private string[] ones = { "", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine" };
    private string[] teens = { "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen" };
    private string[] tens = { "", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety" };

    public string ToWords(int number)
    {
        if (number == 0)
            return "Zero";
        else if (number < 10)
            return ones[number % 10];
        else if (number < 20)
            return teens[number % 10];
        else if (number < 100)
            return tens[number / 10] + (number % 10 != 0 ? " " + ones[number % 10] : "");
        else if(number < 1000)
        {
            var hundredPart = ones[number / 100] + " Hundred";
            var rest = number % 100;

            if (rest >= 10 && rest < 20)
                return hundredPart + " and " + teens[rest % 10];
            else if (rest >= 20)
                return hundredPart + " and " + tens[rest / 10] + (rest % 10 != 0 ? " " + ones[rest % 10] : "");
            else if (rest < 10 && rest > 0)
                return hundredPart + " and " + ones[rest % 10];
            else
                return hundredPart;
        }
        else // Handle numbers up to 9999
        {
            var thousandPart = ones[number / 1000] + " Thousand";
            var rest = number % 1000;
            if (rest != 0)
                return thousandPart + ", " + ToWords(rest);
            else
                return thousandPart;
        }
    }

    public void TranslateArray(int[] numbers)
    {
        foreach(int number in numbers)
        {
            if(number>9999 || number<0)
            {
                Console.WriteLine("Invalid number: " + number);
