            if (unicodeCategory == UnicodeCategory.UppercaseLetter) 
                upperCaseCount++;

            if (unicodeCategory == UnicodeCategory.UppercaseLetter || unicodeCategory == UnicodeCategory.LowercaseLetter)
                totalLetters++;
        }

        double percentage = ((double)upperCaseCount / totalLetters) * 100;
        return String.Format("{0:0.00}%", percentage); 
    }   

    static void Main(string[] args)
    {
        Console.WriteLine(CountUpperCase("Hello World"));
        Console.WriteLine(CountUpperCase("HELLO WORLD"));
        Console.WriteLine(CountUpperCase("hello world"));
        Console.WriteLine(CountUpperCase("Héllo Wôrld"));
        Console.WriteLine(CountUpperCase(""));
        Console.WriteLine(CountUpperCase(null));
    }
}
```
This function works as follows: first, it checks if the string is empty or null. If it is, the function returns "0%". Then it converts the string to its normalized form in order to accurately count the number of characters even in multibyte symbols. 

This function iterates over the normalized string, incrementing `upperCaseCount` and `totalLetters` if the unicode category of each symbol is UppercaseLetter or LowercaseLetter respectively.

The percentage of uppercase letters is calculated by dividing `upperCaseCount` by `totalLetters` and multiplying the result by 100. The result is returned in form of a string with a percentage symbol appended.

