Below is a simple PascalABC.NET code to generate a random string fulfilling your requirements using `System.Security.Cryptography` for generating random numbers:

```PascalABC.NET
using System;
using System.Security.Cryptography;

public class RandomStringGenerator
{
    const string charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890!@#$%^&*()";
    private RNGCryptoServiceProvider cryptoProvider = new RNGCryptoServiceProvider();

    // Generate a random string
    public string Generate()
    {
        string randomString = "";
        char lastChar = '\0';
        byte[] buffer = new byte[1];

        while (randomString.Length < 8)
        {
            cryptoProvider.GetBytes(buffer);
            char newChar = charset[buffer[0] % charset.Length];
            if (newChar != lastChar)
            {
                randomString += newChar;
                lastChar = newChar;
            }
        }

        return randomString;
    }

    // Mutate a string
    public string Mutate(string original)
    {
        byte[] buffer = new byte[1];
        cryptoProvider.GetBytes(buffer);
        int position = buffer[0] % original.Length;

        char oldChar = original[position];
        char newChar;
        do
        {
            cryptoProvider.GetBytes(buffer);
            newChar = charset[buffer[0] % charset.Length];
        }
        while (newChar == oldChar);

        return original.Substring(0, position) + newChar + original.Substring(position + 1);
    }

    // Measure entropy, for simplicity, we are taking the number of distinct characters as our entropy
    public int MeasureEntropy(string str)
    {
        return str.ToCharArray().Distinct().Count();
    }
}
```

This will allow you to generate a string via the `Generate` function and mutate a given string with the `Mutate` function. The entropy of a given string is measured in a simple way based on the number of distinct characters, which is done in the `MeasureEntropy` method.

