        foreach (var (action, value) in items)
        {
            if (action.Equals("Add", StringComparison.OrdinalIgnoreCase))
            {
                total += value;
            }
            else if (action.Equals("Remove", StringComparison.OrdinalIgnoreCase))
            {
                total -= value;
            }
        }

        // Apply the discount code if applicable
        var key = caseSensitive ? discountCode : discountCode.ToUpper();
        if (_discountCodes.ContainsKey(key))
        {
            var (discountValue, minValue) = _discountCodes[key];

