using Google.Cloud.Firestore;
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public class FirestoreDb
{
    private readonly FirestoreDb _db;

    public FirestoreDb(string projectId)
    {
        // Instantiate the Firestore client
        _db = FirestoreDb.Create(projectId);
    }

    public async Task AddToFirestore(string collectionName, string docId, Dictionary<string, object> doc)
    {
        // Add document
        var documentReference = _db.Collection(collectionName).Document(docId);
        await documentReference.SetAsync(doc);
        Console.WriteLine($"Document {docId} added to collection {collectionName}");
    }

    public async Task ReplicateDoc(string collectionName, string docId, string newDocId)
    {
        // Get the document
        var documentReference = _db.Collection(collectionName).Document(docId);
        var snapshot = await documentReference.GetSnapshotAsync();
        if (snapshot.Exists)
        {
            var doc = snapshot.ToDictionary();

            // Add the document with new id
            await AddToFirestore(collectionName, newDocId, doc);
            Console.WriteLine($"Document {docId} replicated as {newDocId} in collection {collectionName}");
        }
    }

    public async Task RunExample()
    {
        var doc = new Dictionary<string, object>
        {
            { "name", "John Doe" },
            { "email", "johndoe@example.com" },
            { "phone", "1234567890" }
        };

        // Add a document
        await AddToFirestore("collection_name", "doc1", doc);

        // Replicate the document
        await ReplicateDoc("collection_name", "doc1", "doc2");
    }
}
```

