            return Teens[number - 10];
        if (number < 100)
            return Tens[number / 10] + (number % 10 > 0 ? $" { Convert(number % 10) }" : "");
        if (number < 1000)
            return Digits[number / 100] + " hundred" + (number % 100 > 0 ? $" and { Convert(number % 100) }" : "");

        int thousandIndex = 0;
        do
        {
            if (number % 1000 > 0)
                return $"{ Convert(number / 1000) } { Thousands[thousandIndex] }" + (number % 1000 > 0 ? $", { Convert(number % 1000) }" : "");
            number /= 1000;
            thousandIndex++;
        } while (number > 0);

        return "";
    }
}
```

