Here is a sample recursive PascalABC.NET code to find the product of all prime numbers within a given range.

The function `AllPrimeProduct()` is recursive. It takes two parameters, `m` and `n` (lower and upper range). The function `CheckPrime()` checks whether the given number is prime.

To handle potential overflow scenarios, we use the `checked` keyword in PascalABC.NET which throws an `OverflowException` if an arithmetic operation results in a value that is outside the range of the return type. However, for extremely large results, this solution still does not handle the overflow since the built-in data types in PascalABC.NET can't handle such values.

```Csharp
using System;

public class Program
{
    public static void Main()
    {
        try
        {
            Console.WriteLine(AllPrimeProduct(2, 20));
        }
        catch (System.OverflowException)
        {
            Console.WriteLine("The product is too big!");
        }
    }

    public static long AllPrimeProduct(int m, int n)
    {
        if(m > n)
        {
            return 1;
        }
        else
        {
            if (CheckPrime(m) && m % 5 != 0)
            {
                checked  // To handle Overflow
                {
                    return m * AllPrimeProduct(m + 1, n);
                }
            }
            else
            {
                return AllPrimeProduct(m + 1, n);
            }
        }
    }

    public static bool CheckPrime(int number)
    {
        if(number <= 1) return false;
        if(number == 2) return true;
        for(int i = 2; i <= Math.Sqrt(number); i++)
        {
            if(number % i == 0) 
            {
                return false;
            }
        }
        return true;
    }
}
```

This function will calculate the product of all prime numbers in the range [m, n] excluding prime numbers that are multiples of 5.

Please note that the function may still throw an overflow exception if the product of the prime numbers exceeds the maximum limit of the `long` datatype. The range of a `long` in .NET is `-9,223,372,036,854,775,808` to `9,223,372,036,854,775,807`. In such cases, you may need to use a third-party library or datatype that can handle arbitrary large integers (like BigInteger).

Here's a simplified implementation of an AVL tree in PascalABC.NET. It should give you a good idea of how to implement a self-balancing binary search tree:

An `AVLNode` would be defined as:

```PascalABC.NET
public class AVLNode
{
    public int Key;
    public int Height;
    public AVLNode Left;
    public AVLNode Right;

    public AVLNode(int item)
    {
        Key = item;
        Height = 1;
    }
}
```
Next, creating an `AVLTree`:

```PascalABC.NET
public class AVLTree
{
    AVLNode root;

    // Function to get maximum of two integers 
    private int max(int a, int b)
    {
        return (a > b) ? a : b;
    }

    private int height(AVLNode N)
    {
        if (N == null)
            return 0;

        return N.Height;
    }

    // Function to right rotate subtree rooted with y 
    private AVLNode rightRotate(AVLNode y)
    {
        AVLNode x = y.Left;
        AVLNode T2 = x.Right;

        x.Right = y;
        y.Left = T2;

        y.Height = max(height(y.Left), height(y.Right)) + 1;
        x.Height = max(height(x.Left), height(x.Right)) + 1;

        return x;
    }

    private AVLNode leftRotate(AVLNode x)
    {
        AVLNode y = x.Right;
        AVLNode T2 = y.Left;

        y.Left = x;
        x.Right = T2;

        x.Height = max(height(x.Left), height(x.Right)) + 1;
        y.Height = max(height(y.Left), height(y.Right)) + 1;

        return y;
    }

    private int getBalance(AVLNode N)
    {
        if (N == null)
            return 0;

        return height(N.Left) - height(N.Right);
    }

    public AVLNode insert(AVLNode node, int key)
    {
        if (node == null)
            return (new AVLNode(key));

        if (key < node.Key)
            node.Left = insert(node.Left, key);
        else if (key > node.Key)
            node.Right = insert(node.Right, key);
        else
            throw new Exception("Duplicate Key not allowed");

        node.Height = 1 + max(height(node.Left), height(node.Right));

        int balance = getBalance(node);

        if (balance > 1 && key < node.Left.Key)
            return rightRotate(node);

        if (balance < -1 && key > node.Right.Key)
            return leftRotate(node);

        if (balance > 1 && key > node.Left.Key)
        {
             node.Left = leftRotate(node.Left);
             return rightRotate(node);
        }

        if (balance < -1 && key < node.Right.Key)
        {
            node.Right = rightRotate(node.Right);
            return leftRotate(node);
        }

        return node;
    }

    public AVLNode deleteNode(AVLNode root, int key)
    {
        if (root == null)
            return root;

        if (key < root.Key)
            root.Left = deleteNode(root.Left, key);
        else if (key > root.Key)
            root.Right = deleteNode(root.Right, key);
        else
        {
            if ((root.Left == null) || (root.Right == null))
            {
                AVLNode temp = null;
                if (temp == root.Left)
                {
                    temp = root.Right;
                }
                else
                {
                    temp = root.Left;
                }

                if (temp == null)
                {
                    temp = root;
                    root = null;
                }
                else
                {
                    root = temp; 
                }
            }
            else
            {
                AVLNode temp = minValueNode(root.Right);

                root.Key = temp.Key;

                root.Right = deleteNode(root.Right, temp.Key);
            }
        }

        if (root == null)
            return root;

        root.Height = max(height(root.Left), height(root.Right)) + 1;

        int balance = getBalance(root);

        if (balance > 1 && getBalance(root.Left) >= 0)
            return rightRotate(root);

        if (balance > 1 && getBalance(root.Left) < 0)
        {
            root.Left = leftRotate(root.Left);
            return rightRotate(root);
        }

        if (balance < -1 && getBalance(root.Right) <= 0)
            return leftRotate(root);

        if (balance < -1 && getBalance(root.Right) > 0)
        {
            root.Right = rightRotate(root.Right);
            return leftRotate(root);
        }

        return root;
    }

    AVLNode minValueNode(AVLNode node)
    {
        AVLNode current = node;

        while (current.Left != null)
            current = current.Left;

        return current;
    }

    public void preOrder(AVLNode node)
    {
        if (node != null)
        {
            Console.Write(node.Key + " ");
            preOrder(node.Left);
            preOrder(node.Right);
        }
    }

    public void inOrder(AVLNode node)
    {
        if (node != null)
        {
            inOrder(node.Left);
            Console.Write(node.Key + " ");
            inOrder(node.Right);
        }
    }

    public void postOrder(AVLNode node)
    {
        if (node != null)
        {
            postOrder(node.Left);
            postOrder(node.Right);
            Console.Write(node.Key + " ");
        }
    }

    public int count(AVLNode node)
    {
        if (node == null)
            return 0;
        else
            return (count(node.Left) + 1 + count(node.Right));
    }
}
```
You can use above `AvlTree` as:

```csharp
