using System.Threading.Tasks;

public class ThreadSafeListEditor<T>
{
    private List<T> listToEdit;
    private Action<T> actionToApply;

    public ThreadSafeListEditor(List<T> list, Action<T> action)
    {
        if (list == null)
            throw new ArgumentNullException(nameof(list));

        if (action == null)
            throw new ArgumentNullException(nameof(action));

        this.listToEdit = list;
        this.actionToApply = action;
    }

    public void EditList()
    {
        if (listToEdit == null)
        {
            throw new InvalidOperationException("List is empty.");
        }

        List<Task> tasks = new List<Task>();
        object lockObject = new object();

        foreach (T item in listToEdit)
        {
            tasks.Add(Task.Factory.StartNew(() =>
            {
                lock (lockObject)
                {
                    actionToApply(item);
                }
            }, TaskCreationOptions.LongRunning));
        }

        try
        {
            Task.WaitAll(tasks.ToArray());
        }
        catch (Exception ex)
        {
            throw new AggregateException("One or more exceptions occurred during list editing.", ex);
        }
    }
}
