        Console.WriteLine("Do you want to save the primes and their digit frequencies to a file (yes/no)?");
        string choice = Console.ReadLine();

        if (choice.ToLower() == "yes")
        {
            SavePrimesToFile(primes);
        }
    }

    static IEnumerable<int> GeneratePrimeNumbers(int start, int end)
    {
        return Partitioner.Create(start, end + 1)
            .AsParallel()
            .Where(IsPrime);
    }

    static bool IsPrime(int num)
    {
        if (num < 2)
        {
            return false;
        }

        for (int i = 2; i * i <= num; ++i)
        {
            if (num % i == 0)
            {
                return false;
            }
        }

        return true;
    }

    static void SavePrimesToFile(List<int> primes)
    {
        using (StreamWriter file = new StreamWriter("primes.txt"))
        {
            foreach (int prime in primes)
            {
                int[] digitFreqs = CountDigitFrequencies(prime);

                string primeDescription = $"{prime}: {string.Join(", ", digitFreqs.Select((freq, index) => $"digit {index}: {freq}"))}";
                file.WriteLine(primeDescription);
            }
        }

        Console.WriteLine("Primes and their digit frequencies saved to primes.txt");
    }

    static int[] CountDigitFrequencies(int num)
    {
        int[] digitFreqs = new int[10];

        while (num > 0)
        {
            ++digitFreqs[num % 10];
            num /= 10;
        }

        return digitFreqs;
    }
}
```

