        const double tolerance = 1.0E-6;
        double fraction = number - Math.Floor(number);

        // if fraction is less than tolerance, return the main number
        if (fraction < tolerance) 
        {
            return $"{Math.Floor(number)}";
        }

        // if fraction is very close to 1, then return the rounded up number
        if (1 - tolerance < fraction) 
        {
            return $"{Math.Ceiling(number)}";
        }

        int lowerN = 0, lowerD = 1, upperN = 1, upperD = 1;

        while (true)
        {
            var middleN = lowerN + upperN;
            var middleD = lowerD + upperD;

            // update upper bounds
            if (middleD * (fraction + tolerance) < middleN)
            {
                upperN = middleN;
                upperD = middleD;
            }
            // update lower bounds
            else if (middleN < (fraction - tolerance) * middleD)
            {
                lowerN = middleN;
                lowerD = middleD;
            }
            else
            {
                int integerPart = (int)Math.Floor(number);
                middleN += integerPart * middleD;
                var commonDivisor = Gcd(middleN, middleD);

                return $"{middleN / commonDivisor}/{middleD / commonDivisor}"; // returns the fraction in format numerator/denominator
            }
        }
    }

    public static void Main()
    {
        Console.WriteLine(ReturnDecimalAsFraction(2.76)); // For Testing
    }
}
```

