```PascalABC.NET
using System;
using System.Linq;
using System.Collections.Generic;

public class Program
{
    static void Main(string[] args)
    {
        Console.WriteLine(TrimmedMean(new List<double> { 3, 1, 2, 4, 5 }, 0.2f));
        Console.WriteLine(TrimmedMean(new List<double> { -10, 4, 6, 1000, 10, 20 }, 0.15f));
    }

    static double TrimmedMean(List<double> l, float trimPercentage)
    {
        if (!l.Any())   // if list is empty
           return 0.0;

        int totalElements = l.Count();
        int trimElements = (int)(totalElements * trimPercentage);

        l = l.OrderBy(x => x).ToList();   //sort the list in ascending order

        // If number of elements to trim is greater than total number of elements in the list, return 0
        if (trimElements > totalElements)
            return 0.0;

        l = l.Skip(trimElements).Take(totalElements - (trimElements * 2)).ToList();  // trimming

        double meanVal = l.Average();  //calculate mean

        return meanVal;
    }
}
```

The PascalABC.NET code follows very similar logic to the original Python code. 

- It first checks if the list of numbers is empty. If yes, then it returns 0.0.
- It then determines the total number of elements in the list, as well as the number of elements that need to be trimmed (which is calculated as a percentage of the total number of elements).
- The list is then sorted in ascending order, and the entered trim percentage is used to remove certain elements from the list.
- If the number of elements to trim exceeds the total number of elements in the list, the function returns 0.0.
- The mean of the remaining elements in the list (after the irrelevant elements have been trimmed) is then calculated and returned as the result.

