Here is a simple example to help you get started with PascalABC.NET. In this sample, a class Program creates an instance of the class MyThread which starts a new thread. The class MyThread has an event that fires every time a new number is added and the Program class is subscribed to this event. In practice, you'd use lock objects, Monitor class, Mutex, Semaphore and other constructs depending on the concurrency and synchronization need of your software.

```csharp
using System;
using System.Threading;

namespace MultiThreadedEvent
{
    // Delegate for the event
    public delegate void OnNumberAddedDelegate();

    public class MyThread
    {
        // Define the event
        public event OnNumberAddedDelegate OnNumberAdded;

        private int _number;
        public int Number
        {
            get { return _number; }
            private set
            {
                _number = value;
                // Fire the event
                OnNumberAdded?.Invoke();
            }
        }

        public void RunThread()
        {
            for(int i=0; i<10; i++)
            {
                Thread.Sleep(1000); 
                Number = i; 
            }
        }
    }

    class Program
    {
        static int _sum = 0;
        static object _lock = new object();

        static void Main(string[] args)
        {
            MyThread myThread = new MyThread();
            myThread.OnNumberAdded += delegate { AddNumber(myThread.Number); };
            new Thread(new ThreadStart(myThread.RunThread)).Start();

            while(true)
            {
                lock(_lock)
                {
                    if(_sum > 40) break;
                }
                Thread.Sleep(500);
            }

            Console.WriteLine("Sum: " + _sum);
        }

        static void AddNumber(int number)
        {
            lock(_lock)
            {
                _sum += number;
                Console.WriteLine("Added " + number + " sum: " + _sum);
            }
        }
    }
}
```
