Here's how you could potentially convert the above Python code to PascalABC.NET. I mostly followed the logic from your original script but had to use a `Dictionary<char, int>` to implement a similar feature to Python's `Counter`:

```PascalABC.NET
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;

public class Program
{
    public static void Main()
    {
        string word = "He79llo!";
        Tuple<string, Dictionary<char, int>> result = TransformString(word);
        Console.WriteLine(result.Item1);
        foreach(var item in result.Item2)
        {
            Console.WriteLine($"Character: {item.Key}, Count: {item.Value}");
        }
    }

    public static Tuple<string, Dictionary<char, int>> TransformString(string input)
    {
        // Define a list to keep the transformed characters
        List<string> transformed = new List<string>();
        string copyInput = input;

        // Initialize the start index of remaining string
        int start = 0;

        // Regular expression to match the first numeral in the string
        Regex regex = new Regex(@"\d+");

        Dictionary<char, int> counter = new Dictionary<char, int>();

        // Loop through each character of the string
        while (start < copyInput.Length)
        {
            // Get a match of a numeral from the beginning of remaining string
            Match match = regex.Match(copyInput, start);

            if (match.Success && match.Index == start)
            {
                // Extract the matched number and increment it if it's odd
                int num = int.Parse(match.Value);
                if (num % 2 == 1)
                    num++;
                transformed.Add(num.ToString());

                // Move the start index after the matched number
                start = match.Index + match.Length;
            }
            else
            {
                char ch = copyInput[start];
                if (char.IsLetter(ch))
                {
                    // Swap case of the character if it's a letter
                    transformed.Add(char.IsUpper(ch) ? char.ToLower(ch).ToString() : char.ToUpper(ch).ToString());
                }
                else
                {
                    // Double the character if it's not alphanumeric
                    transformed.Add(ch.ToString() + ch);
                }

                // Move the start index one character ahead
                start++;
            }
        }

        // Combine the transformed characters to get the transformed string
        string transformedStr = string.Join("", transformed);

        foreach(var ch in transformedStr)
        {
            if(counter.ContainsKey(ch))
            {
                counter[ch]++;
            }
            else
            {
                counter[ch] = 1;
            }
        }

        // Return the transformed string along with its characters' frequency count  
        return new Tuple<string, Dictionary<char, int>>(transformedStr, counter);
    }
}
```

