            ? $"Element found at index {result}"
            : "Element not found in array");
    }

    static int BinarySearch(int[] array, int target, int start, int end)
    {
        if (start <= end)
        {
            int mid = (start + end) / 2;
            Console.WriteLine($"Checking element at index {mid}");

            // check the middle element
            if (array[mid] == target)
            {
                return mid;
            }

            // if the target is smaller than the middle element
            // adjust the end index to ignore the right half of the list
            else if (array[mid] > target)
            {
                Console.WriteLine($"Target is less than element at index {mid}. Adjust end to {mid - 1} and retry");
                return BinarySearch(array, target, start, mid - 1);
            }

            // if the target is greater than the mid value
            // adjust the start index to ignore the left half of the list
            else
            {
                Console.WriteLine($"Target is greater than element at index {mid}. Adjust start to {mid + 1} and retry");
