        if (!typeof(T).IsEnum)
        {
            throw new ArgumentException("T must be an enumerated type");
        }

        var inputValue = input.ToInt64(CultureInfo.CurrentCulture);
        var matchToValue = matchTo.ToInt64(CultureInfo.CurrentCulture);

        return (inputValue & matchToValue) != 0;
    }

    public static bool IsFlagSet(this Enum input, Enum flag)
    {
        var inputValue = Convert.ToInt64(input);
        var flagValue = Convert.ToInt64(flag);

        return (inputValue & flagValue) != 0;
    }
}
