using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        int[] arr = {1, 2, 3, 4, 5, 2, 3, 4};
        int itemToRemove = 2;

        List<int> newArr = RemoveItem(arr, itemToRemove);

        foreach(int i in newArr)
            Console.Write(i + " ");
    }

    public static List<int> RemoveItem(int[] arr, int itemToRemove)
    {
        List<int> newArr = new List<int>();

        for (int i = 0; i < arr.Length; i++)
        {
            if (arr[i] != itemToRemove)
            {
                newArr.Add(arr[i]);
            }
        }
        return newArr;
    }
