class Program
{
    static void Main()
    {
        EsotericSort(new List<int> { 1, 2, 3, 4 }); // [1, 4, 2, 3]
        EsotericSort(new List<int> { 5, 5, 5, 5 }); // [5, 5, 5, 5]
        EsotericSort(new List<int> { }); // []
        EsotericSort(new List<int> { -2, 1, 3, -1 }); // [-2, 3, -1, 1]
    }

    static List<int> EsotericSort(List<int> lst)
    {
        // Using SortedSet to simulate MinHeap
        SortedSet<int> minHeap = new SortedSet<int>(lst);
        // Using SortedSet with reversed comparer to simulate MaxHeap
        SortedSet<int> maxHeap = new SortedSet<int>(Comparer<int>.Create((x, y) => y.CompareTo(x)));
        List<int> output = new List<int>();

        while (minHeap.Count > 0)
        {
            maxHeap.Add(minHeap.Min);
            minHeap.Remove(minHeap.Min);

            if (minHeap.Count > 0)
            {
                output.Add(maxHeap.Min);
                maxHeap.Remove(maxHeap.Min);
            }

            if (maxHeap.Count > 0)
            {
                output.Add(minHeap.Min);
                minHeap.Remove(minHeap.Min);
            }
        }

        foreach(var item in output)
        {
            Console.Write(item + " ");
        }
        Console.WriteLine();
        return output;
    }
}
