using System;
using System.Collections.Generic;
using System.Numerics;
using System.Threading.Tasks;

public class PrimeProductFinder
{
    private List<int> primes;

    public PrimeProductFinder()
    {
        primes = new List<int>();
    }

    public async Task<(List<int>, BigInteger)> FindPrimeProductsAsync(int n)
    {
        if (n < 2)
        {
            throw new ArgumentException("The input must be greater or equal to 2.", nameof(n));
        }

        return await Task.Run(() =>
        {
            BigInteger product = 1;
            primes.Clear();
            for (int number = 2; number <= n; number++)
            {
                if (IsPrime(number))
                {
                    primes.Add(number);
                    product *= number;
                }
            }

            return (primes, product);
        });
    }

    private bool IsPrime(int number)
    {
        if (number < 2) return false;
        for (int i = 2; i * i <= number; i++)
        {
            if (number % i == 0) return false;
        }
        return true;
    }
}

