    {
        PrimeProductFinder finder = new PrimeProductFinder();
        var (primes, product) = await finder.FindPrimeProductsAsync(50);
        Console.WriteLine($"Primes: {string.Join(", ", primes)}");
        Console.WriteLine($"Product: {product}");
    }
}
