Here is an implementation of the `ToRGB` function in PascalABC.NET. It uses the alpha blending formula to blend the source color with the background color. 

```csharp
public Color ToRGB(Color src, Color background)
{
    double a = src.A / 255.0;
    double inv_a = 1 - a; 

    int r = (int) ((background.R * inv_a + src.R * a) );
    int g = (int) ((background.G * inv_a + src.G * a) );
    int b = (int) ((background.B * inv_a + src.B * a) );

    return Color.FromArgb(255,ClipToByte(r),ClipToByte(g),ClipToByte(b));
}

private int ClipToByte(double colorValue)
{
    return (int)(colorValue > 255 ? 255u : (colorValue < 0 ? 0u : colorValue));
