using System;
using System.Numerics;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        int number = 16;
        BigInteger product;
        int totalDistinctPrimes;

        Solve(number, out product, out totalDistinctPrimes);

        Console.WriteLine("Product of primes: " + product);
        Console.WriteLine("Total number of distinct primes: " + totalDistinctPrimes);
    }

    static void Solve(int n, out BigInteger product, out int totalDistinctPrimes)
    {
        product = 1;
        totalDistinctPrimes = 0;
        List<int> primes = new List<int>();

        if (n < 2)
        {
            return;
        }

        for (int i = 2; i <= n; i++)
        {
            if (IsPrime(i))
            {
                primes.Add(i);
                product *= i;
                totalDistinctPrimes += NumberOfDistinctPrimeFactors(i);
            }
        }
    }

    static bool IsPrime(int number)
    {
        if (number == 2)
        {
            return true;
        }
        if (number < 2 || number % 2 == 0)
        {
            return false;
        }
        for (int i = 3; i * i <= number; i += 2)
        {
            if (number % i == 0)
            {
                return false;
            }
        }
        return true;
    }

    static int NumberOfDistinctPrimeFactors(int number)
    {
        if (number < 2)
        {
            return 0;
        }
        int count = 0;
        for (int i = 2; i * i <= number; i++)
        {
            if (number % i == 0)
            {
                count++;
                while (number % i == 0)
                {
                    number /= i;
                }
            }
        }
        if (number > 1)
        {
            count++;
        }
        return count;
    }
}
```

For performance purpose, we are using 'Sieve of Eratosthenes' to find out a given number is prime or not. Also for prime factorization, iterate only to the square root of the number, which significantly reduces the computation time.

