```PascalABC.NET
using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        Console.WriteLine(IsArmstrongNumber(371));
        Console.WriteLine(IsArmstrongNumber(1634));
        Console.WriteLine(IsArmstrongNumber(9474));
        Console.WriteLine(IsArmstrongNumber(124));

        int start = 1; 
        int end = 10000;
        List<int> armstrongNumbersInRange = FindArmstrongNumberInRange(start, end);
        foreach(var number in armstrongNumbersInRange)
        {
            Console.WriteLine(number);
        }
    }

    private static bool IsArmstrongNumber(int number)
    {
        int temp = number;
        var digits = new List<int>();
        while(temp != 0)
        {
            digits.Add(temp % 10);
            temp = temp / 10;
        }

        int sum = 0;
        int power = digits.Count;
        for(int index = 0; index < power; index++)
        {
            sum += (int)Math.Pow(digits[index], power);
        }

        return (sum == number);       
    }

    private static List<int> FindArmstrongNumberInRange(int start, int end)
    {
        if(start > end)
        {
            int temp = start;
            start = end;
            end = temp;
        }
        var armstrongNumbers = new List<int>();
        for(int index = start; index <= end; index++)
        {
            if(IsArmstrongNumber(index))
            {
                armstrongNumbers.Add(index);
            }
        }
        return armstrongNumbers; 
    }
}
```

In the IsArmstrongNumber method, we are minimizing the computation by calculating the number of digits only once. The FindArmstrongNumberInRange method is taking in a range and calling the IsArmstrongNumber on each number in that range. It also handles the case where start is greater than the end by swapping them. It is also ensuring no duplicates in the output as we are only considering integers, so no integer can appear more than once in the resulting list. For further optimization, you may consider multithreading based on the range size or using more efficient data structures.

