using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static List<int> CalculatePrimes(int n)
    {
        bool[] isPrime = new bool[n + 1];
        for(int i = 0; i < n; i++)
        {
            isPrime[i] = true;
        }
        int p = 2;
        while(p * p <= n)
        {
            if(isPrime[p]){
                for(int i = p * p; i <= n; i += p)
                {
                    isPrime[i] = false;
                }
            }
            p += 1;    
        }
        return Enumerable.Range(2, n-2).Where(x => isPrime[x]).ToList(); 
    }

    static bool RotateArrayElements(List<int> arr) 
    {
        if(!arr.Any()) return true;

        int arrSum = arr.Sum();
        int arrLen = arr.Count();
        float arrAvg = (float)arrSum / arrLen;

        List<int> primes = CalculatePrimes(arr.Max() + 1);
        int primeCounter = 0;

        int rotations = 0;
        while(rotations < 2)
        {
            int oddsLessAvg = arr.Where((x, i) => i % 2 != 0 && x < arrAvg).Count();
            if(oddsLessAvg % 2 == 0) return false;

            for(int i = 0; i < arrLen; i++) 
            {
                if(i % 2 == 0 && primes.Contains(arr[i])) 
                { 
                    if(primeCounter < primes.Count)
                    {
                        int temp = arr[i];
                        arr[i] = arr[primeCounter];
                        arr[primeCounter] = temp;
                        primeCounter += 1;
                    }
                    else
                    {
                        return false;
                    }
                }
            }
            rotations += 1;

            if(arr.SequenceEqual(arr.OrderBy(i => i)))
            {
                return true;
            }
        }

        return false;
    }

