```csharp
using System;
using System.Collections.Generic;
using System.Linq;

namespace ServiceHandler
{
    public class FilterService
    {
        public enum LogicalOperator
        {
            AND,
            OR
        }

        public List<string> Filter(List<string>[] lists, Predicate<string>[] conditions, LogicalOperator logicalOperator)
        {
            List<string> result = new List<string>();

            foreach (List<string> list in lists)
            {
                foreach (string item in list)
                {
                    bool shouldAdd = false;

                    switch (logicalOperator)
                    {
                        case LogicalOperator.AND:
                            shouldAdd = conditions.All(condition => condition(item));
                            break;

                        case LogicalOperator.OR:
                            shouldAdd = conditions.Any(condition => condition(item));
                            break;
                    }

                    if (shouldAdd)
                        result.Add(item);
                }
            }

            return result.Distinct().OrderBy(item => item).ToList();
        }
    }

