        if (arr.Length == 0 || arr.Length == 1)
            return true;

        int[] arrOrig = (int[]) arr.Clone();
        // Performing "argsort" equivalent in PascalABC.NET, getting the sorted indices of the array.
        int[] sortedIndices = arrOrig.Select((x, i) => new KeyValuePair<int, int>(x, i))
                                     .OrderBy(x => x.Key)
                                     .Select(x => x.Value)
                                     .ToArray();

        int numSwaps = 0;

        // For each index, iteratively swap elements until the element at current index is in its correct position.
        for (int i = 0; i < sortedIndices.Length; i++)
        {
            int sortedIdx = sortedIndices[i];
            while (i != sortedIdx)
            {
                // Swap elements.
                int temp = arr[sortedIdx];
                arr[sortedIdx] = arr[i];
                arr[i] = temp;
                sortedIdx = sortedIndices[i];
                numSwaps++;
            }
        }

        if (numSwaps > 4)
            return false;

        double avg = arr.Average();
        int arrLtAvg = arr.Count(el => el < avg);

        if (arrLtAvg % 2 == 0)
            return false;

        bool primesOddIndices = arr.Where((el, idx) => IsPrime(el) && idx % 2 == 0).All(el => IsPrime(el));
        if (!primesOddIndices)
            return false;

        return true;
    }
}
```
