```PascalABC.NET
public static void Main(string[] args)
{
    var numbers = new List<int> { 3, 7, 5, 2, 4, 1 };
    Sorter.Sort(numbers);
    foreach (var number in numbers)
    {
        Console.WriteLine(number);
    }
}
```
