```csharp
using System;

public class Program
{
    static void Main(string[] args)
    {
        Console.WriteLine("Enter the base area of the pyramid:");
        double baseArea;
        while (!double.TryParse(Console.ReadLine(), out baseArea) || baseArea <= 0)
            Console.WriteLine("Input must be a positive real number. Please enter again.");

        Console.WriteLine("Enter the height of the pyramid:");
        double height;
        while (!double.TryParse(Console.ReadLine(), out height) || height <= 0)
            Console.WriteLine("Input must be a positive real number. Please enter again.");

        double pyramidVolume = (1.0 / 3.0) * baseArea * height;
        Console.WriteLine("The volume of the pyramid is: {0}", pyramidVolume);

        Console.WriteLine("Enter the height of the frustum:");
        double frustumHeight;
        while (!double.TryParse(Console.ReadLine(), out frustumHeight) || frustumHeight <= 0 || frustumHeight >= height)
            Console.WriteLine("Input must be a positive real number and less than the height of the pyramid. Please enter again.");

        Console.WriteLine("Enter the base area of the frustum:");
        double frustumArea;
