using System; 
public class Program
{
    public static void Main()
    {
        int[] nums = {10, 2, 36, 14, 25};
        Array.Sort(nums);    
        double median; 
        int size = nums.Length; 

        // Check if the size is even or odd
        if (size % 2 == 0)
        { 
            // If even, average the two middle elements
            median = ((double)nums[size / 2 - 1] + (double)nums[size / 2]) / 2; 
        }    
        else
        { 
            // If odd, choose the middle element
            median = (double) nums[size / 2]; 
        }

        // Print the median
        Console.WriteLine("Median: " + median);
    }    
}
```

This program first sorts the array, then checks if the size of the array is even or odd. If it's even, it finds the two middle numbers, adds them together, and divides by 2 to find the median. If it's odd, it simply picks the middle number. Then the calculated median is printed to the console.

