using System;

class Program{

    static void Main(string[] args){
        CheckPrimeInRange(2, 100);
        Console.ReadKey();
    }

    //recursive method to print prime numbers in a range
    static void CheckPrimeInRange(int start, int end){
        if(start > end){
            return;
        }

        if(IsPrime(start)){
            Console.WriteLine(start);
        }

        CheckPrimeInRange(start + 1, end);
    }

    //method to check if the given number is prime or not
    static bool IsPrime(int num){
        if(num <= 1){
            return false;
        }

        for(int i = 2; i*i <= num; i++){
            if(num % i == 0){
                return false;
            }
        }

        return true;
    }
}
```
