public static int FindKthLargest(List<int> nums, int k)
{
    int pivot = nums[nums.Count / 2];

    List<int> left = nums.Where(x => x < pivot).ToList();
    List<int> mid = nums.Where(x => x == pivot).ToList();
    List<int> right = nums.Where(x => x > pivot).ToList();

