    private ManualResetEvent _shutdownEvent = new ManualResetEvent(false);
    private Thread _thread;

    static void Main(string[] args)
    {
        Program p = new Program();
        p.StartThread();
    }

    void StartThread()
    {
        _thread = new Thread(DoWork);
        _thread.Start();

        Console.ReadLine();  // Wait for user input

        _shutdownEvent.Set();  // Signal the thread to shut down
        _thread.Join(); // Optional: Wait for the thread to finish
    }

    void DoWork()
    {
        while (!_shutdownEvent.WaitOne(0))
        {
            // This loop continues to execute until the user enters input,
            // which sets the _shutdownEvent.
            Console.WriteLine("Working...");
            Thread.Sleep(1000);
        }
        Console.WriteLine("Shutting down...");
    }
}
```
This creates a manual reset event that starts out unset. In the DoWork loop, it checks at each iteration whether the signal has been set. If it has, it exits the loop (and therefore the function, and therefore the thread). If it has not, it loops again.

In the main thread, when the user inputs anything, it sets the signal, which makes the next iteration of the loop in the worker thread exit.

AutoResetEvent works on a similar principle but resets itself back to an unset state automatically after releasing a waiting thread.

