public class Solution
{
    string[] ReverseArray(string[] array, int start, int end)
    {
        if(array == null) 
            throw new ArgumentNullException("Input array cannot be null");

        // buffer overflow checks
        if(start > end || start < 0 || end >= array.Length)
            throw new ArgumentOutOfRangeException("Array index is out of range");

        if (start >= end)
		{
            return array;
        }
        else
        {
            string temp = array[start];

            // Recursive call for swapping array members
            array[start] = array[end];
            array[end] = temp;

            // Limiting end and incrementing start for next swap
            return ReverseArray(array, start + 1, end - 1);
        }
    }

    public void Start()
    {
        try
        {
            // Test Array
            string[] testArray = new string[] { "one", "two", "three", "four", "five" };

            // Reverse the array
            testArray = ReverseArray(testArray, 0, testArray.Length - 1);

            Console.WriteLine("Reversed Array: ");

