        {
            Console.Write("ArgumentNullException: ", e);
        }
        catch (ArgumentOutOfRangeException e)
        { 
            Console.Write("ArgumentOutOfRangeException: ", e);
        }
        catch (Exception e)
        {
            Console.Write("Exception: ", e);
        }
    }
}
