Here is your Python code converted to PascalABC.NET:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Solution 
{
    List<(int, int)> directions = new List<(int, int)> { (0, -1), (0, 1), (-1, 0), (1, 0) };
    List<(int, int)> res = new List<(int, int)>();
    int[][] grid;
    int n;
    int max_val;
    int min_val;

    public List<int> MaxPath(int[][] grid, int k)
    {
        this.grid = grid;
        this.n = grid.Length;
        this.max_val = n*n;
        this.min_val = 1;

        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                if (this.grid[i][j] == max_val || this.grid[i][j] == min_val)
                {
                    DFS((i, j), (i, j), k, new List<(int, int)> { (i, j) });
                }
            }
        }
        return this.res.Select(t => this.grid[t.Item1][t.Item2]).ToList();
    }

    private void DFS((int, int) start, (int, int) end, int remain, List<(int, int)> path)
    {
        if (remain == 0)
        {
            if (path.Count > res.Count)
            {
                this.res = new List<(int, int)>(path);
            }
            return;
        }
        foreach ((int dx, int dy) in directions)
        {
            int x = start.Item1 + dx;
            int y = start.Item2 + dy;
            if (0 <= x && x < n && 0 <= y && y < n && !path.Contains((x, y)) && path.Any(t => this.grid[t.Item1][t.Item2] == this.min_val) && path.Any(t => this.grid[t.Item1][t.Item2] == this.max_val))
            {
                path.Add((x, y));
                DFS((x, y), end, remain - 1, path);
                path.RemoveAt(path.Count - 1);
            }
        }
    }
}
```

