```PascalABC.NET
using System;
using System.Collections.Generic;

public class Program {

    List<string> ones = new List<string>{ "", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine" };
    List<string> teens = new List<string>{ "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen" };
    List<string> tens = new List<string>{ "", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety" };
    List<string> thousands = new List<string>{ "", "Thousand", "Million", "Billion" };

    public void Main() {

        int[] numbers = {47, 981, 3521};

        foreach(int number in numbers)
        {
            Console.WriteLine(NumberToWords(number));
        }
    }

    public string NumberToWords(int num)
    {
        if (num == 0)
            return "Zero";
        int i = 0;
        string words = "";

        while (num > 0)
        {
            if (num % 1000 != 0)
            {
                words = Helper(num % 1000) + thousands[i] + " " + words;
            }
            num /= 1000;
            i++;
        }
        return words.Trim();
    }


    private string Helper(int num)
    {
        if (num == 0)
            return "";
        else if (num < 10)
            return ones[num] + " ";
        else if (num < 20)
            return teens[num - 10] + " ";
        else
        {
            return tens[num/10] + " " + Helper(num%10);
        }
    }
}
