```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        Console.Write("Enter edge length: ");
        double edgeLength;

        if (!double.TryParse(Console.ReadLine(), out edgeLength))
        {
            Console.WriteLine("Invalid input. Please enter a number.");
            return;
        }

        if (edgeLength <= 0)
        {
            Console.WriteLine("Edge length must be positive.");
            return;
        }

        double volume = ComputeVolume(edgeLength);
        Console.WriteLine("The volume of the tetrahedron is: " + volume);
