        Partnership Partnership = new Partnership();
        Partnership.AddPartner(mike);
        Partnership.AddPartner(alex);
        Partnership.AddPartner(sarah);

        Partnership.ModifyShares(mike, 4); // Mike buys 4 more bookstores.
        Partnership.ModifyShares(alex, -2); // Alex sells 2 bookstores.
        Partnership.ModifyShares(sarah, 3); // Sarah buys 3 more bookstores.

        Partnership.DisplayShares();
    }
}

public class Partner
{
    public string Name { get; private set; }
    public int Bookstores { get; set; }

    public Partner(string name, int bookstores)
    {
        Name = name;
        Bookstores = bookstores;
    }
}

public class Partnership
{
    private List<Partner> Partners = new List<Partner>();

    public void AddPartner(Partner partner)
    {
        if (this.Partners == null)
            this.Partners = new List<Partner>();

        this.Partners.Add(partner);
    }

    public void ModifyShares(Partner partner, int change)
    {
        partner.Bookstores += change;
        DistributeEqually();
    }

    private void DistributeEqually()
    {
        int totalBookstores = Partners.Sum(p => p.Bookstores);
        int equalShare = totalBookstores / Partners.Count;

        foreach (Partner partner in Partners)
        { 
            partner.Bookstores = equalShare;
        }
    }

    public void DisplayShares()
    {
        foreach (Partner partner in Partners)
        { 
            Console.WriteLine($"{partner.Name} now owns {partner.Bookstores} bookstores.");
        }
    }
}
```
In this solution, `Partner` class represents each partner and `Partnership` represents the business partnership. In methods `ModifyShares` and `DistributeEqually`, we calculate the total bookstores and distribute them equally.

