    }

    // Function to calculate sum of all numbers from 1 to "n" that are prime using recursion
    public static int SumOfPrimes(int n, int i) {
        if (i > n) // Base case
            return 0;
        // if i is prime then add to sum otherwise add 0
        // Recursive case
        else return (IsPrime(i, 2) ? i : 0) + SumOfPrimes(n, i + 1);
    }

