using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;

public static Complex? ComplexMedian(List<Complex> list)
{
    if (list == null)
    {
        return null;
    }

    var sortableValues = new List<(double real, double imag)>();

    foreach (var item in list)
    {
        sortableValues.Add((item.Real, item.Imaginary));
    }

    sortableValues.Sort();

    int n = sortableValues.Count;
    if (n % 2 == 1)
    {
        var medianTuple = sortableValues[n / 2];
        return new Complex(medianTuple.real, medianTuple.imag);
    }
    else
    {
        var medianTuple1 = sortableValues[n / 2 - 1];
        var medianTuple2 = sortableValues[n / 2];
        double medianRealComponent = (medianTuple1.real + medianTuple2.real) / 2;
        double medianImagComponent = (medianTuple1.imag + medianTuple2.imag) / 2;

        return new Complex(medianRealComponent, medianImagComponent);
    }
}
```
The function obtains the median value of a list of complex numbers. It first checks whether the given object is not null. If it is, it returns null. Then it adds each list item to a new list in a form of a value tuple consisting of the real and imaginary parts. It sorts this list and calculates the median according to the standard rules (for an odd number of elements, it's the middle one, for an even number, it's an average of the two middle ones). In the end, it returns a new complex number composed from the real and imaginary median values.

