    if (s.Length < 3) return false;

    // Create a dictionary to hold how often each character appears in the string
    Dictionary<char, int> characterAppearances = new Dictionary<char, int>();
    char previousCharacter = s[0];

    for (int i = 1; i < s.Length; i++)
    {
        char currentChar = s[i];

        // Update the count value in dictionary for the current character
        if (characterAppearances.ContainsKey(currentChar))
            characterAppearances[currentChar]++;
        else
            characterAppearances[currentChar] = 1;

        // Check condition d: if any character repeats consecutively, return false
        if (previousCharacter == currentChar) return false;
        previousCharacter = currentChar;
    }

    // Check condition c: if any character appears less than 2 times, return false
    if (characterAppearances.Any(x => x.Value < 2)) return false;

    // Check condition b: if any 3 consecutive characters have repeating characters, return false
    for (int i = 0; i < s.Length - 2; i++)
    {
        if (s.Substring(i, 3).Distinct().Count() != 3) return false;
    }

    // Check if there is any pair of consecutive characters in the string that are in alphabetical order
    for (int i = 0; i < s.Length - 1; i++)
    {
        if (Math.Abs((int)s[i] - (int)s[i + 1]) == 1) break;
    }
    else 
