```PascalABC.NET
using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main(string[] args)
    {
        object[,] array = new object[,] { { 1, "test", 1 }, { 2, "hello", "world" }, { 2, "test", "test" } };

        var result = FindMostFrequentElements(array);

        foreach (var item in result)
        {
            foreach (var element in item.Value)
            {
                Console.WriteLine($"The most frequent element of type {item.Key} is '{element.Key}', it appears {element.Value} times.");
            }
        }

        Console.ReadKey();
    }

    static Dictionary<Type, Dictionary<object, int>> FindMostFrequentElements(object[,] multiDimensionArray)
    {
        // Create a dictionary to store the count and type of objects
        Dictionary<Type, Dictionary<object, int>> countDictionary = new Dictionary<Type, Dictionary<object, int>>();

        // Loop over each element in the array
        foreach(var element in multiDimensionArray)
        {
            Type type = element.GetType();
            if (!countDictionary.ContainsKey(type))
            {
                countDictionary[type] = new Dictionary<object, int>();
            }

            if (!countDictionary[type].ContainsKey(element))
            {
                countDictionary[type][element] = 0;
            }

            countDictionary[type][element]++;
        }

        // Use LINQ to find the most common elements
        return countDictionary.ToDictionary(
            pair => pair.Key,
            pair => pair.Value.GroupBy(p => p.Value)
                          .OrderByDescending(group => group.Key)
                          .FirstOrDefault()
                          .ToDictionary(p => p.Key, p => p.Value)
        );
    }
}
```

In the `FindMostFrequentElements` function, we loop over each element in the multi-dimensional array. We first add the type of the element to the dictionary if it does not exist. Then, we add the element itself to the nested dictionary (of its type) or increment its count if it already exists. 

At the end, the dictionary is transformed so that each type is associated with only the most frequent elements of the same type (and their count).

