```Csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        Console.Write("Enter a positive integer: ");
        if (!int.TryParse(Console.ReadLine(), out int number) || number <= 0) // check if the input is a positive integer
        {
            Console.WriteLine("Invalid input! Please enter a positive integer.");
            return;
        }

        GenerateMultiplicationTable(number);
    }

    public static void GenerateMultiplicationTable(int input)
    {
        int[] table = new int[10]; // initialize array to store multiplication values
        for (int i = 0; i < 10; i++) // loop through array
        {
            table[i] = (i + 1) * input;
        }

        printTable(input, table);
    }

    private static void printTable(int input, int[] table)
    {
        Console.WriteLine($"Multiplication table for {input}:");
        for (int i = 1; i <= 10; i++) // start from 1 to display multiplication times
        {
            Console.WriteLine($"{input} * {i} = {table[i - 1]}");
        }
    }
}
