    public static List<List<int>> ComplexSort(List<List<int>> list1)
    {
        List<List<int>> evenList = new List<List<int>>(); //list to hold even numbers
        List<List<int>> oddList = new List<List<int>>();  //list to hold odd numbers
        List<List<int>> mixedList = new List<List<int>>(); //list to hold mixed numbers

        //if the list is empty
        if (list1.Count == 0) return new List<List<int>>();

        //if the list has only one element
        if (list1.Count == 1) return list1;

        foreach (var sublist in list1)
        {
            //if first and last elements of sublist are even
            if (sublist[0] % 2 == 0 && sublist[sublist.Count - 1] % 2 == 0)
                evenList.Add(sublist);
            //if first and last elements of sublist are odd
            else if (sublist[0] % 2 != 0 && sublist[sublist.Count - 1] % 2 != 0)
                oddList.Add(sublist);
            //if it's a mix
