                mixedList.Add(sublist);
        }

        //sorting each list based on condition
        SortLists(evenList);
        SortLists(oddList);
        SortLists(mixedList);

        //merging all lists into one
        return evenList.Concat(oddList).Concat(mixedList).ToList();
    }

    //Sorting logic
