    static string RemoveConsecutiveDuplicates(string input)
    {
        StringBuilder sb = new StringBuilder();
        char lastChar = '\0';

        foreach (char c in input)
        {
            if (c != lastChar) sb.Append(c);
            lastChar = c;
        }

