The following is an equivalent PascalABC.NET method to your Python function:

```PascalABC.NET
using System;
using System.Collections.Generic;

public class Program
{
    public static Tuple<string, Dictionary<string, int>> AdvancedStringManipulation(string str)
    {
        string transStr = string.Empty;
        Dictionary<string, int> charDict = new Dictionary<string, int>();

        foreach(char s in str)
        {
            string charStr;
            if(Char.IsLetter(s))   // Check if char is a letter
                charStr = Char.IsUpper(s) ? Char.ToLower(s).ToString() : Char.ToUpper(s).ToString();
            else if(Char.IsDigit(s) && int.Parse(s.ToString()) % 2 == 1)   // Check if char is an odd number
                charStr = (int.Parse(s.ToString()) + 1).ToString();
            else  // Repeat other characters (special characters) twice
                charStr = s.ToString() + s.ToString();

            transStr += charStr;

            // Populating the dictionary
            if(charDict.ContainsKey(charStr)) 
                charDict[charStr] += 1; 
            else 
                charDict.Add(charStr, 1);
        }

        return Tuple.Create(transStr, charDict);
    }
}
