```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    // Define a delegate for comparison function
    public delegate int CompareFunc(int a, int b);

    public static void Main()
    {
        List<int> numbers = new List<int> { 1, 2, 3, 4, 5 };
        Console.WriteLine("Median: " + Median(numbers, CompareNumbers));
    }

    public static int? Median(List<int> list, CompareFunc cmpFunc)
    {
        // Get list length
        int listLen = list.Count;

        // Return null for empty list
        if (listLen == 0)
        {
            return null;
        }

        // Create count of less than and greater than for each element
        var counts = list.Select(i => 
                     (list.Count(j => cmpFunc(i, j) > 0),
                     list.Count(j => cmpFunc(i, j) < 0))).ToList();

        try
        {
            // For odd-sized lists, find the element where counts equal (n-1)//2
            if (listLen % 2 == 1)
            {
                return list.FirstOrDefault((t, i) => Math.Max(counts[i].Item1, counts[i].Item2) == (listLen - 1) / 2);
            }
            else
            {
                // For even-sized lists, find two elements where upper count equals n//2 and lower equals n//2 -1
                int lo = list.FirstOrDefault((t, i) => counts[i].Item2 == listLen / 2 - 1 && counts[i].Item1 <= listLen / 2);
                int hi = list.FirstOrDefault((t, i) => counts[i].Item2 <= listLen / 2 && counts[i].Item1 == listLen / 2 - 1);

                // Return average of two elements
                return (lo + hi) / 2.0;
            }
        }
        catch 
        {
            // Return null if no median can be found (due to mismatch datatypes in cmpFunc)
            return null;
        }
    }

    // Method for integer comparison
    public static int CompareNumbers(int a, int b)
    {
        return a.CompareTo(b);
    }
}
```

