Here is a simple implementation of an INI file reader:

```csharp
using System.IO;
using System.Collections;

class IniFile
{
    Hashtable keyPairs = new Hashtable();

    public IniFile(string iniPath)
    {
        var txtLines = File.ReadAllLines(iniPath);

        foreach (var line in txtLines)
        {
            string currentLine = line.Trim();

            if (!string.IsNullOrEmpty(currentLine) && 
                !currentLine.StartsWith(";"))
            {
                string sectionName = currentLine;
                Hashtable tmpDictionary = new Hashtable();

                if (sectionName.StartsWith("[") &&   
                    sectionName.EndsWith("]"))
                {
                    sectionName = sectionName.Substring(1, sectionName.Length-2);

                    while (!string.IsNullOrEmpty(currentLine))
                    {
                        string key = currentLine.Substring(0, currentLine.IndexOf('='));
                        string value = currentLine.Substring(currentLine.IndexOf('=')+1);

                        tmpDictionary[key] = value;
                    }

                    keyPairs[sectionName] = tmpDictionary;
                }
            }
        }
    }

    public string GetValue(string sectionName, string settingName)
    {
        Hashtable section = (Hashtable)keyPairs[sectionName];

        if (section == null)
            return null;

        return (string) section[settingName];
    }
}
```

This is a very basic implementation and can be used like this:

