using System.Numerics;
using System.Collections.Generic;

public class Program
{
    public static void Main(string[] args)
    {
        Console.WriteLine(Lcm(new List<int>{4, 6})); // Should output 12
        Console.WriteLine(Lcm(new List<int>{21, 14, 7})); // Should output 42
        Console.WriteLine(Lcm(new List<int>{10, 25, 5})); // Should output 50
        Console.WriteLine(Lcm(new List<int>{12, 15, 20})); // Should output 60
        Console.WriteLine(Lcm(new List<int>{9, 3, 3})); // Should output 9
    }

    public static BigInteger Lcm(List<int> numbers)
    {
        /*
        Uses resource-efficient techniques to find the LCM of a list of integers.
        Assumes: 1 <= numbers.Count <= 10^3, 1 <= numbers[i] <= 10^9 
        */

        // The LCM of two numbers x, y is (x * y) / gcd(x, y)
        Func<BigInteger, int, BigInteger> lcmOfTwo = (x, y) => x * y / BigInteger.GreatestCommonDivisor(x, y);

        BigInteger result = 1;
        foreach (var number in numbers)
        {
            // Calculating LCM of current result and next number
            result = lcmOfTwo(result, number);
        }
        return result;
    }
}
```

