The following impersonation class uses Windows API functions to implement impersonation. 

```csharp
using System;
using System.Runtime.InteropServices;
using System.Security.Principal;
using System.Security.Permissions;

[PermissionSet(SecurityAction.Demand, Name = "FullTrust")]
public class Impersonation : IDisposable
{
    private WindowsImpersonationContext context;
    private IntPtr tokenHandle = IntPtr.Zero;
    private const int LOGON32_PROVIDER_DEFAULT = 0;
    private const int LOGON32_LOGON_INTERACTIVE = 2;

    [DllImport("advapi32.dll", SetLastError = true)]
    private static extern bool LogonUser(String lpszUsername, String lpszDomain, String lpszPassword,
        int dwLogonType, int dwLogonProvider, out IntPtr phToken);

    [DllImport("kernel32.dll", CharSet = CharSet.Auto)]
    private extern static bool CloseHandle(IntPtr handle);

    public Impersonation(String username, String password, String domain)
    {
        if LogonUser(username, domain, password, LOGON32_LOGON_INTERACTIVE,
            LOGON32_PROVIDER_DEFAULT, out this.tokenHandle))
        {
            WindowsIdentity identity = new WindowsIdentity(tokenHandle);
            this.context = identity.Impersonate();
        }
        else
        {
            throw new System.ComponentModel.Win32Exception();
        }
    }

    public void Dispose()
    {
        this.context.Undo();

        if (this.tokenHandle != IntPtr.Zero)
            CloseHandle(this.tokenHandle);
    }
}
