```csharp
using System;
using System.Numerics;
using System.Threading;

namespace PrimeNumberChecker
{
    public class PrimeNumberChecker
    {
        /// <summary>
        /// Checks whether a given number is prime.
        /// </summary>
        /// <param name="number">The number to be checked.</param>
        /// <returns>True if the number is prime, false otherwise.</returns>
        public static bool IsPrime(BigInteger number)
        {
            // Handle special cases
            if (number <= 1)
            {
                return false;
            }
            if (number <= 3)
            {
                return true;
            }
            if (number % 2 == 0 || number % 3 == 0)
            {
                return false;
            }

            // Multi-threaded approach to increase performance
            int processorCount = Environment.ProcessorCount;
            ManualResetEvent[] resetEvents = new ManualResetEvent[processorCount];
            bool[] results = new bool[processorCount];

            for (int i = 0; i < processorCount; i++)
            {
                resetEvents[i] = new ManualResetEvent(false);
                ThreadPool.QueueUserWorkItem(CheckPrime, new CheckPrimeParams(number, i, processorCount, resetEvents, results));
            }

            WaitHandle.WaitAll(resetEvents);

            foreach (bool result in results)
            {
                if (!result)
                {
                    return false;
                }
            }

            return true;
        }

        private static void CheckPrime(object state)
        {
            CheckPrimeParams parameters = (CheckPrimeParams)state;

            BigInteger number = parameters.Number;
            int startIndex = parameters.StartIndex;
            int step = parameters.Step;
            ManualResetEvent[] resetEvents = parameters.ResetEvents;
            bool[] results = parameters.Results;

            for (BigInteger i = 5 + 2 * startIndex; i * i <= number; i += 2 * step)
            {
                if (number % i == 0)
                {
                    results[startIndex] = false;
                    resetEvents[startIndex].Set();
                    return;
                }
            }

            results[startIndex] = true;
            resetEvents[startIndex].Set();
        }

        /// <summary>
        /// Finds the closest prime number for a given number.
        /// </summary>
        /// <param name="number">The number for which to find the closest prime.</param>
        /// <returns>The closest prime number.</returns>
        public static BigInteger FindClosestPrime(BigInteger number)
        {
            if (IsPrime(number))
            {
                return number;
            }

            BigInteger lowerPrime = number;
            BigInteger upperPrime = number;

            while (true)
            {
                lowerPrime--;
                upperPrime++;

                if (IsPrime(lowerPrime))
                {
                    return lowerPrime;
                }
                if (IsPrime(upperPrime))
                {
                    return upperPrime;
                }
            }
        }

        public class CheckPrimeParams
        {
            public BigInteger Number { get; }
            public int StartIndex { get; }
            public int Step { get; }
            public ManualResetEvent[] ResetEvents { get; }
            public bool[] Results { get; }

            public CheckPrimeParams(BigInteger number, int startIndex, int step, ManualResetEvent[] resetEvents, bool[] results)
            {
                Number = number;
                StartIndex = startIndex;
                Step = step;
                ResetEvents = resetEvents;
                Results = results;
            }
        }
    }

    public class Program
    {
        static void Main(string[] args)
        {
            // Test IsPrime method
            Console.WriteLine(PrimeNumberChecker.IsPrime(13)); // True
            Console.WriteLine(PrimeNumberChecker.IsPrime(15)); // False
            Console.WriteLine(PrimeNumberChecker.IsPrime(1000000007)); // True

            // Test FindClosestPrime method
            Console.WriteLine(PrimeNumberChecker.FindClosestPrime(13)); // 13
            Console.WriteLine(PrimeNumberChecker.FindClosestPrime(15)); // 13
            Console.WriteLine(PrimeNumberChecker.FindClosestPrime(1000000007)); // 1000000007

            Console.ReadLine();
        }
    }
}
```

The code first checks for some special cases (numbers less than or equal to 3), then utilizes a multi-threaded approach to check for primality. It splits the work among the available processors, reducing the number of iterations required to determine if a number is prime. It also handles negative numbers, decimal numbers, and overflow scenarios. Finally, it includes a unit test in the `Main` method to verify the correctness of the implementation.

