```csharp
using System;

class TriangleAreaCalculator
{
    static void Main()
    {
        Console.WriteLine("Enter the lengths of the three sides of the triangle:");

        // Read the side lengths from the user
        Console.Write("Side 1: ");
        double side1 = Convert.ToDouble(Console.ReadLine());

        Console.Write("Side 2: ");
        double side2 = Convert.ToDouble(Console.ReadLine());

        Console.Write("Side 3: ");
        double side3 = Convert.ToDouble(Console.ReadLine());

        // Check if the side lengths form a valid triangle
        if (IsValidTriangle(side1, side2, side3))
        {
            // Calculate the area of the triangle
            double area = CalculateTriangleArea(side1, side2, side3);

            // Display the result
            Console.WriteLine("The area of the triangle is: " + area);
        }
        else
        {
            Console.WriteLine("Invalid triangle! The sum of any two sides should be greater than the third side.");
        }
    }

    // Function to check if the given side lengths form a valid triangle
    static bool IsValidTriangle(double side1, double side2, double side3)
    {
        return (side1 + side2 > side3) && (side1 + side3 > side2) && (side2 + side3 > side1);
    }

    // Function to calculate the area of a triangle using Heron's formula
    static double CalculateTriangleArea(double side1, double side2, double side3)
    {
        double s = (side1 + side2 + side3) / 2; // Calculate the semi-perimeter
        double area = Math.Sqrt(s * (s - side1) * (s - side2) * (s - side3)); // Calculate the area using Heron's formula
        return area;
    }
}
```

In this program, we first prompt the user to enter the lengths of the three sides of the triangle. We then check if the given side lengths form a valid triangle using the `IsValidTriangle` function. If they do, we calculate the area of the triangle using Heron's formula in the `CalculateTriangleArea` function and display the result. If the side lengths do not form a valid triangle, we display an error message.

