public static decimal MultiplyBySumOfDigits(decimal number)
{
    decimal sum = 0;
    decimal tempNumber = Math.Abs(number); // Take the absolute value to handle negative numbers

    // Calculate the sum of the digits
    while (tempNumber > 0)
    {
        sum += tempNumber % 10; // Get the last digit and add it to the sum
        tempNumber = Math.Floor(tempNumber / 10); // Remove the last digit from the number
    }

    // Multiply the original number by the sum of its digits
    decimal result = number * sum;

    return result;
}
