```csharp
using System;

class Program
{
    static void Main()
    {
        Console.Write("Enter a number: ");
        int number = int.Parse(Console.ReadLine());

        long factorial = CalculateFactorial(number);
        Console.WriteLine("Factorial of {0} is: {1}", number, factorial);

        Console.Write("Enter a base number: ");
        double baseNumber = double.Parse(Console.ReadLine());

        Console.Write("Enter an exponent: ");
        int exponent = int.Parse(Console.ReadLine());

        double powerResult = Power(baseNumber, exponent);
        Console.WriteLine("{0} raised to the power of {1} is: {2}", baseNumber, exponent, powerResult);

        Console.ReadLine();
    }

    static long CalculateFactorial(int number)
    {
        if (number == 0)
            return 1;

        long factorial = 1;
        for (int i = 1; i <= number; i++)
        {
            factorial *= i;
        }
        return factorial;
    }

    static double Power(double baseNumber, int exponent)
    {
        double result = 1;
        for (int i = 0; i < Math.Abs(exponent); i++)
        {
            result *= baseNumber;
        }

        if (exponent < 0)
            result = 1 / result;

        return result;
    }
}
```

In this program, the `CalculateFactorial` function calculates the factorial of a given number using a loop. The `Power` function calculates the power of a base number raised to an exponent using another loop. The `Main` method prompts the user to enter a number and then calls both functions to calculate the factorial and power. Finally, it displays the results on the console.

