    static string[] ones = new string[] { "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen" };
    static string[] tens = new string[] { "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety" };

    static void Main(string[] args)
    {
        Console.Write("Enter a number: ");
        string input = Console.ReadLine();
        double number;

        if (double.TryParse(input, out number))
        {
            if (number < -1000000 || number > 1000000)
            {
                Console.WriteLine("Number out of range");
                return;
            }

            if (number < 0)
            {
                Console.Write("negative ");
                number = Math.Abs(number);
            }

            int wholePart = (int)number;
            double decimalPart = number - wholePart;

            if (decimalPart != 0)
            {
                Console.Write(ConvertToWords(wholePart) + " and " + ConvertDecimalToWords(decimalPart));
            }
            else
            {
                Console.Write(ConvertToWords(wholePart));
            }
        }
        else
        {
            Console.WriteLine("Invalid number format");
        }
    }

    static string ConvertToWords(int number)
    {
        if (number < 20)
        {
            return ones[number];
        }
        else if (number < 100)
        {
            int tensDigit = number / 10;
            int onesDigit = number % 10;
            return tens[tensDigit - 2] + (onesDigit > 0 ? " " + ones[onesDigit] : "");
        }
        else if (number < 1000)
        {
            int hundredsDigit = number / 100;
            int remainder = number % 100;
            return ones[hundredsDigit] + " hundred" + (remainder > 0 ? " and " + ConvertToWords(remainder) : "");
        }
        else if (number < 1000000)
        {
            int thousands = number / 1000;
            int remainder = number % 1000;
            return ConvertToWords(thousands) + " thousand" + (remainder > 0 ? " " + ConvertToWords(remainder) : "");
        }
        else
        {
            return "Number out of range";
        }
    }

    static string ConvertDecimalToWords(double number)
    {
        string decimalPart = number.ToString().Split('.')[1];
        return ConvertToWords(int.Parse(decimalPart));
    }
}
```

This program uses a combination of if-else statements and arrays to convert the given number into words. The `ConvertToWords` method is used to convert the whole number part into words, while the `ConvertDecimalToWords` method is used to convert the decimal part into words. The program also handles negative numbers and prints them as "negative" followed by the words for the absolute value of the number. It checks for out of range numbers and displays an error message if necessary.

